window.DATA = {"i18n": {"site_title": {"az": "AN Psixoloji Mərkəzi — Diaqnostik Qiymətləndirmə", "ru": "AN Психологический Центр — Диагностическая оценка", "en": "AN Psychology Center — Diagnostic Assessment"}, "nav_home": {"az": "Ana səhifə", "ru": "Главная", "en": "Home"}, "brand": {"az": "AN Psixoloji Mərkəzi", "ru": "AN Психологический Центр", "en": "AN Psychology Center"}, "center_full": {"az": "AN Psixoloji Dəstək və Reabilitasiya Mərkəzi", "ru": "AN Центр психологической поддержки и реабилитации", "en": "AN Center for Psychological Support and Rehabilitation"}, "hero_eyebrow": {"az": "Diplomlu və sertifikatlı mütəxəssislər tərəfindən", "ru": "Дипломированные и сертифицированные специалисты", "en": "By qualified and certified specialists"}, "hero_title_a": {"az": "Xüsusi qayğıya ehtiyacı olan uşaqlar üçün", "ru": "Для детей с особыми потребностями —", "en": "For children with special needs —"}, "hero_title_em": {"az": "diaqnostik qiymətləndirmə", "ru": "диагностическая оценка", "en": "diagnostic assessment"}, "hero_title_b": {"az": "sistemi", "ru": "система", "en": "system"}, "hero_lead": {"az": "Altı beynəlxalq qiymətləndirmə aləti bir platformada. Mərkəzimizin mütəxəssisləri uşağı qiymətləndirir, sistem isə müşahidələri toplayır, peşəkar hesabat hazırlayır və həm mütəxəssisə, həm valideynə aydın tövsiyələr verir.", "ru": "Шесть международных инструментов оценки на одной платформе. Специалисты нашего центра оценивают ребёнка, а система собирает наблюдения, формирует профессиональный отчёт и даёт понятные рекомендации специалисту и родителю.", "en": "Six international assessment tools on one platform. Our specialists assess the child, while the system collects observations, builds a professional report and gives clear recommendations to both specialist and parent."}, "stat_tools": {"az": "Qiymətləndirmə aləti", "ru": "Инструментов оценки", "en": "Assessment tools"}, "stat_cert": {"az": "Sertifikatlı mütəxəssis", "ru": "Сертифицированные специалисты", "en": "Certified specialists"}, "stat_report": {"az": "Mütəxəssis + valideyn hesabatı", "ru": "Отчёт для специалиста и родителя", "en": "Specialist + parent report"}, "scroll": {"az": "Aşağı", "ru": "Вниз", "en": "Scroll"}, "tools_kicker": {"az": "Qiymətləndirmə alətləri", "ru": "Инструменты оценки", "en": "Assessment tools"}, "tools_head": {"az": "Mərkəzimizdə keçirilən testlər", "ru": "Тесты, проводимые в нашем центре", "en": "Tests conducted at our center"}, "tools_sub": {"az": "Hər test ayrı bölmədə açılır: yuxarıda keçirilmə təlimatı, sonra uşaq və mütəxəssis məlumatları, müşahidə sahələri və nəticə hesabatı.", "ru": "Каждый тест открывается в отдельном разделе: инструкция по проведению, данные ребёнка и специалиста, области наблюдения и итоговый отчёт.", "en": "Each test opens in its own section: administration guide, child and specialist details, observation areas and a final report."}, "why_kicker": {"az": "Niyə bizim mərkəz", "ru": "Почему наш центр", "en": "Why our center"}, "why_head": {"az": "Bu yanaşmanın üstünlükləri", "ru": "Преимущества подхода", "en": "Advantages of this approach"}, "prof_note": {"az": "Peşəkar qeyd.", "ru": "Профессиональное примечание.", "en": "Professional note."}, "prof_note_txt": {"az": "Bu platforma standartlaşdırılmış testləri əvəz etmir — onları dəstəkləyir. Yekun bal, norma müqayisəsi və diaqnoz həmişə mərkəzin rəsmi, lisenziyalı dəsti və ixtisaslı mütəxəssisin mühakiməsi ilə müəyyən edilir. Sistemin müşahidə xülasələri qərar dəstəyi məqsədi daşıyır.", "ru": "Эта платформа не заменяет стандартизированные тесты — она их дополняет. Итоговый балл, сравнение с нормами и диагноз всегда определяются официальным лицензированным набором центра и суждением квалифицированного специалиста. Сводки наблюдений служат поддержкой решения.", "en": "This platform does not replace standardized tests — it supports them. The final score, norm comparison and diagnosis are always determined by the center's official licensed kit and the judgment of a qualified specialist. The observation summaries are intended as decision support."}, "open_test": {"az": "Testi aç", "ru": "Открыть тест", "en": "Open test"}, "areas": {"az": "sahə", "ru": "обл.", "en": "areas"}, "back": {"az": "Geri", "ru": "Назад", "en": "Back"}, "howto": {"az": "Keçirilmə qaydası", "ru": "Порядок проведения", "en": "Administration"}, "methods": {"az": "Forma və metodlar", "ru": "Формы и методы", "en": "Forms & methods"}, "scoring": {"az": "Qiymətləndirmə və yekun", "ru": "Оценка и итог", "en": "Scoring & summary"}, "child_info": {"az": "Uşaq haqqında məlumat", "ru": "Данные о ребёнке", "en": "Child information"}, "spec_info": {"az": "Mütəxəssis haqqında", "ru": "О специалисте", "en": "Specialist information"}, "f_name": {"az": "Uşağın adı", "ru": "Имя ребёнка", "en": "Child's first name"}, "f_surname": {"az": "Uşağın soyadı", "ru": "Фамилия ребёнка", "en": "Child's surname"}, "f_age": {"az": "Yaş", "ru": "Возраст", "en": "Age"}, "f_spec_name": {"az": "Mütəxəssisin adı", "ru": "Имя специалиста", "en": "Specialist's first name"}, "f_spec_surname": {"az": "Mütəxəssisin soyadı", "ru": "Фамилия специалиста", "en": "Specialist's surname"}, "f_profession": {"az": "Peşə", "ru": "Профессия", "en": "Profession"}, "f_wa": {"az": "Valideynin WhatsApp nömrəsi (göndərmək üçün)", "ru": "WhatsApp родителя (для отправки)", "en": "Parent's WhatsApp number (to send)"}, "f_wa_ph": {"az": "məs. 994501234567 (ölkə kodu ilə)", "ru": "напр. 994501234567 (с кодом страны)", "en": "e.g. 994501234567 (with country code)"}, "official_kicker": {"az": "Rəsmi bal (istəyə bağlı)", "ru": "Официальный балл (по желанию)", "en": "Official score (optional)"}, "official_note": {"az": "Bu bölmə məcburi deyil. Lisenziyalı dəstdən rəsmi bal almısınızsa, onu buraya əlavə edin, hesabata daxil olacaq. Bu ballar nəticənin hesablanmasına təsir etmir, hesabatda yalnız göstərilir. Boş buraxsanız, hesabat yalnız müşahidələrə əsaslanacaq.", "ru": "Этот раздел необязателен. Если вы получили официальный балл по лицензированному набору, добавьте его здесь, и он попадёт в отчёт. Эти баллы не влияют на расчёт результата и лишь отображаются в отчёте. Если оставить пустым, отчёт будет основан только на наблюдениях.", "en": "This section is optional. If you have an official score from the licensed kit, add it here and it will be included in the report. These scores do not affect how the result is calculated and are only displayed in the report. If left empty, the report will rely on observations only."}, "obs_kicker": {"az": "Müşahidə sahələri", "ru": "Области наблюдения", "en": "Observation areas"}, "obs_note": {"az": "Hər bənd üzrə müşahidənizi qeyd edin. Bu, rəsmi balı əvəz etmir — onu tamamlayır.", "ru": "Отметьте ваше наблюдение по каждому пункту. Это не заменяет официальный балл, а дополняет его.", "en": "Mark your observation for each item. This does not replace the official score — it complements it."}, "show_result": {"az": "Nəticəni göstər", "ru": "Показать результат", "en": "Show result"}, "progress": {"az": "tamamlandı", "ru": "заполнено", "en": "completed"}, "result_title": {"az": "Qiymətləndirmə hesabatı", "ru": "Отчёт об оценке", "en": "Assessment report"}, "res_official": {"az": "Daxil edilmiş rəsmi ballar", "ru": "Введённые официальные баллы", "en": "Entered official scores"}, "res_domains": {"az": "Müşahidə xülasəsi (sahələr üzrə)", "ru": "Сводка наблюдений (по областям)", "en": "Observation summary (by area)"}, "res_diag": {"az": "Mütəxəssis üçün diaqnostik mülahizələr", "ru": "Диагностические соображения для специалиста", "en": "Diagnostic considerations for the specialist"}, "res_spec": {"az": "Mütəxəssisə tövsiyələr", "ru": "Рекомендации специалисту", "en": "Recommendations for the specialist"}, "res_parent": {"az": "Valideynə sadə dildə tövsiyələr", "ru": "Простые рекомендации для родителя", "en": "Simple recommendations for the parent"}, "res_games": {"az": "Evdə oyun nümunələri", "ru": "Примеры игр дома", "en": "Example games at home"}, "send_wa": {"az": "WhatsApp-a göndər", "ru": "Отправить в WhatsApp", "en": "Send to WhatsApp"}, "save_report": {"az": "Hesabatı yüklə (HTML)", "ru": "Скачать отчёт (HTML)", "en": "Download report (HTML)"}, "print_pdf": {"az": "Çap / PDF", "ru": "Печать / PDF", "en": "Print / PDF"}, "edit_again": {"az": "Yenidən redaktə et", "ru": "Редактировать снова", "en": "Edit again"}, "fill_more": {"az": "Hesabat üçün daha çox sahəni doldurun.", "ru": "Заполните больше областей для отчёта.", "en": "Fill in more areas for the report."}, "band_ok": {"az": "Çətinlik müşahidə olunmur", "ru": "Трудности не наблюдаются", "en": "No difficulty observed"}, "band_warn": {"az": "Yüngül çətinlik", "ru": "Лёгкие трудности", "en": "Mild difficulty"}, "band_high": {"az": "Orta çətinlik", "ru": "Умеренные трудности", "en": "Moderate difficulty"}, "band_crit": {"az": "Əhəmiyyətli çətinlik", "ru": "Значительные трудности", "en": "Significant difficulty"}, "disclaimer": {"az": "Yekun diaqnoz və bal lisenziyalı dəst və ixtisaslı mütəxəssis tərəfindən müəyyən edilir. Bu hesabat qərar dəstəyi məqsədi daşıyır.", "ru": "Итоговый диагноз и балл определяются лицензированным набором и квалифицированным специалистом. Этот отчёт служит поддержкой решения.", "en": "The final diagnosis and score are determined by a licensed kit and a qualified specialist. This report is intended as decision support."}, "foot_rights": {"az": "müvafiq naşirlərin qeydiyyatdan keçmiş alətləridir; rəsmi keçirilmə yalnız lisenziyalı dəst və ixtisaslı mütəxəssis tərəfindən aparılır.", "ru": "являются зарегистрированными инструментами соответствующих издателей; официальное проведение осуществляется только лицензированным набором и квалифицированным специалистом.", "en": "are registered instruments of their respective publishers; official administration is carried out only with a licensed kit and a qualified specialist."}, "contact": {"az": "Əlaqə", "ru": "Контакты", "en": "Contact"}, "address": {"az": "Rizvan Teymurov 59, Bakı", "ru": "Ризван Теймуров 59, Баку", "en": "Rizvan Teymurov 59, Baku"}, "rp_title": {"az": "Ətraflı qiymətləndirmə hesabatı", "ru": "Подробный отчёт об оценке", "en": "Detailed assessment report"}, "rp_overview": {"az": "Ümumi nəticə", "ru": "Общий итог", "en": "Overall result"}, "rp_ov1": {"az": "Müşahidə {n} sahə üzrə aparıldı. Hər sahədə mütəxəssis 3 konkret davranışı qiymətləndirdi.", "ru": "Наблюдение проведено по {n} областям. По каждой области специалист оценил 3 конкретных проявления.", "en": "Observation covered {n} areas. In each area the specialist rated 3 specific behaviours."}, "rp_ov2": {"az": "Əhəmiyyətli çətinlik: {crit} sahə. Orta: {high}. Yüngül: {warn}. Çətinlik müşahidə olunmayan: {ok} sahə.", "ru": "Значительные трудности: {crit}. Умеренные: {high}. Лёгкие: {warn}. Без трудностей: {ok}.", "en": "Significant difficulty: {crit} areas. Moderate: {high}. Mild: {warn}. No difficulty observed: {ok}."}, "rp_ok_list": {"az": "Nisbətən qorunan sahələr: {l}.", "ru": "Относительно сохранные области: {l}.", "en": "Relatively preserved areas: {l}."}, "rp_weak_list": {"az": "Prioritet dəstək tələb edən sahələr: {l}.", "ru": "Области, требующие приоритетной поддержки: {l}.", "en": "Areas needing priority support: {l}."}, "rp_profile": {"az": "Qrup (indeks) üzrə profil", "ru": "Профиль по индексам", "en": "Profile by index"}, "rp_profile_note": {"az": "Hər qrup öz sahələrinin orta müşahidə balıdır (0 = çətinlik yoxdur, 3 = əhəmiyyətli çətinlik). Bu rəsmi test balı deyil.", "ru": "Каждый индекс — среднее наблюдаемых баллов его областей (0 = трудностей нет, 3 = значительные). Это не официальный балл теста.", "en": "Each group is the mean observed score of its areas (0 = no difficulty, 3 = significant difficulty). This is not an official test score."}, "rp_gaps": {"az": "Dəqiq çatışmazlıqlar", "ru": "Конкретные трудности", "en": "Specific difficulties"}, "rp_gaps_note": {"az": "Qrup ortalaması sahələr arasındakı fərqi gizlədə bilər. Aşağıdakı sahələr ayrıca qeyd olunur.", "ru": "Среднее по группе может скрывать различия между областями. Эти области выделены отдельно.", "en": "A group average can hide differences between areas. These areas are listed separately."}, "rp_gaps_none": {"az": "Orta və ya əhəmiyyətli çətinlik müşahidə olunan sahə yoxdur.", "ru": "Областей с умеренными или значительными трудностями не выявлено.", "en": "No areas with moderate or significant difficulty were observed."}, "rp_detail": {"az": "Sahələr üzrə təfsilatlı təhlil", "ru": "Подробный разбор по областям", "en": "Detailed analysis by area"}, "rp_detail_note": {"az": "Hər sahədə: nəyi göstərdiyi, mütəxəssisin tapşırığı, 3 müşahidənin nəticəsi və çətinlik olarsa gündəlik həyatda necə görünə biləcəyi.", "ru": "По каждой области: что она показывает, задание специалиста, результат трёх наблюдений и как трудность может проявляться в быту.", "en": "For each area: what it shows, the specialist's task, the result of 3 observations and how a difficulty may look in daily life."}, "rp_means": {"az": "Nəyi göstərir", "ru": "Что показывает", "en": "What it shows"}, "rp_task": {"az": "Tapşırıq", "ru": "Задание", "en": "Task"}, "rp_looks": {"az": "Gündəlik həyatda necə görünə bilər", "ru": "Как может проявляться в быту", "en": "How it may look in daily life"}, "rp_links": {"az": "Sahələr arası əlaqələr", "ru": "Связи между областями", "en": "Links between areas"}, "rp_link_spread": {"az": "{g} qrupunda sahələr arasında fərq var: {a} ({x}/3) və {b} ({y}/3). Qrup ortalaması bu fərqi gizlədir.", "ru": "В группе {g} есть разница между областями: {a} ({x}/3) и {b} ({y}/3). Среднее по группе её скрывает.", "en": "Within {g} the areas differ: {a} ({x}/3) and {b} ({y}/3). The group average hides this."}, "rp_link_together": {"az": "{g} qrupunda bir neçə sahədə birlikdə çətinlik müşahidə olunur: {l}. Bu, ortaq bir səbəbin ola biləcəyini göstərir və birgə məşq planı tələb edir.", "ru": "В группе {g} трудности отмечены сразу в нескольких областях: {l}. Это может указывать на общую причину и требует совместного плана занятий.", "en": "In {g} difficulty appears in several areas together: {l}. This may point to a shared cause and calls for a joint practice plan."}, "rp_links_none": {"az": "Sahələr arasında xüsusi əlaqə qeyd olunmadı.", "ru": "Особых связей между областями не отмечено.", "en": "No particular links between areas were noted."}, "rp_home": {"az": "Valideyn üçün: evdə nə etməli", "ru": "Родителям: что делать дома", "en": "For parents: what to do at home"}, "rp_home_intro": {"az": "Gündə 10–15 dəqiqə, oyun şəklində. Uğuru tərifləyin, uğursuzluğu vurğulamayın.", "ru": "10–15 минут в день, в форме игры. Хвалите успех, не подчёркивайте неудачи.", "en": "10–15 minutes a day, as play. Praise success, do not stress mistakes."}, "rp_school": {"az": "Məktəb və bağça üçün tövsiyələr", "ru": "Рекомендации для школы и сада", "en": "For school and kindergarten"}, "rp_next": {"az": "Növbəti addımlar", "ru": "Следующие шаги", "en": "Next steps"}, "rp_limits": {"az": "Məhdudiyyətlər", "ru": "Ограничения", "en": "Limitations"}, "rp_limits_txt": {"az": "Bu hesabat mütəxəssisin müşahidəsinə əsaslanır və diaqnoz deyil. Rəsmi bal və yekun qiymətləndirmə yalnız lisenziyalı test dəsti ilə, ixtisaslı mütəxəssis tərəfindən müəyyən edilir. Tövsiyələr ümumi xarakter daşıyır və fərdi planla tamamlanmalıdır.", "ru": "Отчёт основан на наблюдении специалиста и не является диагнозом. Официальный балл и итоговая оценка определяются только лицензированным набором и квалифицированным специалистом. Рекомендации носят общий характер и должны дополняться индивидуальным планом.", "en": "This report is based on the specialist's observation and is not a diagnosis. Official scores and the final assessment are determined only with the licensed kit by a qualified specialist. Recommendations are general and should be completed with an individual plan."}, "rp_for_spec": {"az": "Yalnız mütəxəssis üçün", "ru": "Только для специалиста", "en": "For the specialist only"}, "rp_parent_copy": {"az": "Valideyn nüsxəsi (mütəxəssis bölməsi daxil deyil)", "ru": "Копия для родителей (без раздела для специалиста)", "en": "Parent copy (without the specialist section)"}, "rp_unans": {"az": "qeyd olunmayıb", "ru": "не отмечено", "en": "not rated"}}, "professions": [{"az": "Klinik psixoloq", "ru": "Клинический психолог", "en": "Clinical psychologist"}, {"az": "Psixoloq", "ru": "Психолог", "en": "Psychologist"}, {"az": "Loqoped", "ru": "Логопед", "en": "Speech therapist"}, {"az": "Erqoterapevt", "ru": "Эрготерапевт", "en": "Occupational therapist"}, {"az": "Defektoloq", "ru": "Дефектолог", "en": "Special educator"}, {"az": "Psixiatr", "ru": "Психиатр", "en": "Psychiatrist"}, {"az": "Reabilitoloq", "ru": "Реабилитолог", "en": "Rehabilitation specialist"}, {"az": "ABA terapevti", "ru": "ABA-терапевт", "en": "ABA therapist"}], "scale": [{"az": "Çətinlik yoxdur", "ru": "Нет трудностей", "en": "No difficulty"}, {"az": "Yüngül", "ru": "Лёгкие", "en": "Mild"}, {"az": "Orta", "ru": "Умеренные", "en": "Moderate"}, {"az": "Əhəmiyyətli", "ru": "Значительные", "en": "Significant"}], "why": [{"icon": "shield", "t": {"az": "Standartı pozmadan", "ru": "Без нарушения стандарта", "en": "Without breaking the standard"}, "d": {"az": "Sistem rəsmi testləri əvəz etmir — mütəxəssisin müşahidələrini sistemli toplayır və qanuni qalır.", "ru": "Система не заменяет официальные тесты — она систематизирует наблюдения специалиста и остаётся легальной.", "en": "The system does not replace official tests — it organizes the specialist's observations and stays legal."}}, {"icon": "report", "t": {"az": "İki hesabat birində", "ru": "Два отчёта в одном", "en": "Two reports in one"}, "d": {"az": "Həm mütəxəssis üçün diaqnostik mülahizələr, həm valideyn üçün sadə dildə tövsiyələr.", "ru": "И диагностические соображения для специалиста, и простые рекомендации для родителя.", "en": "Both diagnostic considerations for the specialist and simple guidance for the parent."}}, {"icon": "clock", "t": {"az": "Vaxta qənaət", "ru": "Экономия времени", "en": "Saves time"}, "d": {"az": "Müşahidələr avtomatik xülasələnir, hesabat dərhal hazır olur.", "ru": "Наблюдения автоматически сводятся, отчёт готов мгновенно.", "en": "Observations are summarized automatically; the report is ready instantly."}}, {"icon": "share", "t": {"az": "Asan paylaşım", "ru": "Простой обмен", "en": "Easy sharing"}, "d": {"az": "Hesabatı WhatsApp ilə göndərin, HTML yükləyin və ya PDF çap edin.", "ru": "Отправьте отчёт в WhatsApp, скачайте HTML или распечатайте в PDF.", "en": "Send the report via WhatsApp, download HTML or print to PDF."}}, {"icon": "globe", "t": {"az": "Üç dildə", "ru": "На трёх языках", "en": "Three languages"}, "d": {"az": "Bütün interfeys və hesabatlar Azərbaycan, rus və ingilis dillərində.", "ru": "Весь интерфейс и отчёты на азербайджанском, русском и английском.", "en": "The entire interface and reports in Azerbaijani, Russian and English."}}, {"icon": "heart", "t": {"az": "Uşaq mərkəzli", "ru": "Ориентир на ребёнка", "en": "Child-centered"}, "d": {"az": "Hər tövsiyə uşağın gündəlik həyatına və ailəsinə real fayda verməyə yönəlib.", "ru": "Каждая рекомендация направлена на реальную пользу для повседневной жизни ребёнка и семьи.", "en": "Every recommendation aims at real benefit for the child's daily life and family."}}], "tests": {"ados2": {"id": "ados2", "name": "ADOS-2", "full": {"az": "Otizm Diaqnostik Müşahidə Cədvəli, 2-ci nəşr", "ru": "План диагностического наблюдения аутизма, 2-е изд.", "en": "Autism Diagnostic Observation Schedule, 2nd ed."}, "age": {"az": "12 aylıqdan böyüklərə qədər (modullar üzrə)", "ru": "от 12 месяцев до взрослых (по модулям)", "en": "12 months to adult (by modules)"}, "summary": {"az": "Sosial ünsiyyət, qarşılıqlı təsir və oyunun strukturlaşdırılmış müşahidəsi. Otizm spektri əlamətlərinin qiymətləndirilməsində istinad alətidir.", "ru": "Структурированное наблюдение социальной коммуникации, взаимодействия и игры. Эталонный инструмент при оценке признаков аутистического спектра.", "en": "Structured observation of social communication, interaction and play. A reference tool in assessing autism spectrum signs."}, "advantages": [{"az": "Birbaşa müşahidəyə əsaslanır", "ru": "Основан на прямом наблюдении", "en": "Based on direct observation"}, {"az": "Yaşa və nitqə görə modulları var", "ru": "Имеет модули по возрасту и речи", "en": "Has modules by age and speech"}, {"az": "Oyun və qarşılıqlı təsir vasitəsilə təbii davranışı açır", "ru": "Раскрывает естественное поведение через игру и взаимодействие", "en": "Reveals natural behavior through play and interaction"}, {"az": "Komanda qərarı üçün güclü dayaq", "ru": "Прочная опора для командного решения", "en": "Strong support for team decision-making"}], "instruction": {"howto": [{"az": "Sakit, az qıcıqlandırıcı otaqda, uşaqla təkbətək keçirin.", "ru": "Проводите наедине с ребёнком в тихой комнате с малым числом раздражителей.", "en": "Conduct one-on-one in a quiet, low-distraction room."}, {"az": "Uşağın yaşına və nitq səviyyəsinə uyğun modulu seçin.", "ru": "Выберите модуль, соответствующий возрасту и уровню речи ребёнка.", "en": "Select the module matching the child's age and speech level."}, {"az": "Təqdim olunan oyun və tapşırıqlar zamanı təbii davranışı müşahidə edin.", "ru": "Наблюдайте естественное поведение во время предложенных игр и заданий.", "en": "Observe natural behavior during the presented games and tasks."}], "methods": [{"az": "Strukturlaşdırılmış oyun və sosial 'tələlər'", "ru": "Структурированная игра и социальные «пробы»", "en": "Structured play and social 'presses'"}, {"az": "Yarımstrukturlaşdırılmış söhbət (nitqi olanlar üçün)", "ru": "Полуструктурированная беседа (для говорящих)", "en": "Semi-structured conversation (for verbal children)"}, {"az": "Birgə fəaliyyət və müşahidə", "ru": "Совместная деятельность и наблюдение", "en": "Joint activity and observation"}], "scoring": [{"az": "Müşahidə kodları sosial təsir və ünsiyyət üzrə alqoritmə yığılır.", "ru": "Коды наблюдения сводятся в алгоритм по взаимодействию и коммуникации.", "en": "Observation codes feed an algorithm for interaction and communication."}, {"az": "Yekun kəsim balı yalnız rəsmi protokol üzrə hesablanır.", "ru": "Итоговый пороговый балл рассчитывается только по официальному протоколу.", "en": "The final cutoff score is computed only per the official protocol."}]}, "official": [{"label": {"az": "Sosial təsir (SA) balı", "ru": "Балл соц. взаимодействия (SA)", "en": "Social Affect (SA) score"}, "hint": {"az": "rəsmi protokoldan", "ru": "из официального протокола", "en": "from official protocol"}}, {"label": {"az": "Məhdud/təkrarlanan (RRB) balı", "ru": "Балл огранич./повтор. (RRB)", "en": "Restricted/Repetitive (RRB) score"}, "hint": {"az": "rəsmi protokoldan", "ru": "из официального протокола", "en": "from official protocol"}}, {"label": {"az": "Ümumi müqayisə balı (CSS)", "ru": "Сравнительный балл (CSS)", "en": "Comparison score (CSS)"}, "hint": {"az": "1–10", "ru": "1–10", "en": "1–10"}}, {"label": {"az": "Modul", "ru": "Модуль", "en": "Module"}, "hint": {"az": "məs. Modul 2", "ru": "напр. Модуль 2", "en": "e.g. Module 2"}}], "domains": [{"id": "d1", "title": {"az": "Göz təması və baxışla tənzimləmə", "ru": "Зрительный контакт и регуляция взглядом", "en": "Eye Contact and Gaze Regulation"}, "task": {"az": "Birgə oyun və söhbət zamanı (oyuncaqlar, baloncuk üfürmə) uşağın baxışına baxılır.", "ru": "Наблюдают за взглядом ребёнка во время совместной игры и беседы (игрушки, мыльные пузыри).", "en": "The child's gaze is observed during joint play and conversation (toys, bubble blowing)."}, "items": [{"id": "d1i1", "t": {"az": "Ünsiyyət zamanı göz təması qurmaqda və saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с установлением и поддержанием зрительного контакта при общении", "en": "Has difficulty establishing and maintaining eye contact during interaction"}}, {"id": "d1i2", "t": {"az": "Baxışı diqqəti yönəltmək üçün istifadə etməkdə çətinlik çəkir (məsələn, istədiyi şeyə baxıb sonra sizə baxmır)", "ru": "Испытывает трудности с использованием взгляда для направления внимания (например, смотрит на желаемое, но не переводит взгляд на вас)", "en": "Has difficulty using gaze to direct attention (for example, looks at the desired object but does not look back at you)"}}, {"id": "d1i3", "t": {"az": "Göz təmasını jest və ya nitqlə uyğunlaşdırmaqda çətinlik çəkir", "ru": "Испытывает трудности с согласованием зрительного контакта с жестами или речью", "en": "Has difficulty coordinating eye contact with gestures or speech"}}], "mean": {"az": "ünsiyyət zamanı göz təmasından istifadə", "ru": "использование зрительного контакта в общении", "en": "use of eye contact in communication"}, "means": {"az": "Göz təması insanla ünsiyyətin ilk vasitələrindən biridir. Danışarkən və oynayarkən baxış qarşı tərəfə diqqət və maraq göstərməyə kömək edir.", "ru": "Зрительный контакт — одно из первых средств общения. Во время разговора и игры взгляд помогает проявлять внимание и интерес к собеседнику.", "en": "Eye contact is one of the first means of communicating with people. During conversation and play, gaze shows attention to and interest in the other person."}, "looks": {"az": "Uşaq söhbət və ya oyun zamanı sizə az baxır, baxışı qısa olur və ya istədiyi şeyi göstərərkən sizə baxmır.", "ru": "Ребёнок мало смотрит на вас во время разговора или игры, взгляд кратковременный или он не смотрит на вас, когда показывает желаемое.", "en": "The child looks at you little during conversation or play, the gaze is brief, or the child does not look at you when showing what he or she wants."}, "support": {"az": "Baloncuk üfürmə, qıdıqlama kimi oyunlarda dayanıb gözləyin ki, uşaq sizə baxsın; baxanda dərhal oyunu davam etdirin.", "ru": "В играх с мыльными пузырями, щекоткой остановитесь и подождите, чтобы ребёнок посмотрел на вас; когда посмотрит, сразу продолжите игру.", "en": "In games such as blowing bubbles or tickling, pause and wait for the child to look at you; when the child does, resume the game at once."}}, {"id": "d2", "title": {"az": "Jest və işarələrdən istifadə", "ru": "Использование жестов", "en": "Use of Gestures"}, "task": {"az": "Uşağın əli çatmayan yerdə maraqlı oyuncaq və ya qab göstərilir, istəyini necə bildirdiyinə baxılır.", "ru": "Интересную игрушку или контейнер показывают так, чтобы ребёнок не мог до них дотянуться, и наблюдают, как он выражает желание.", "en": "An interesting toy or container is placed out of the child's reach and the examiner observes how the child expresses a wish."}, "items": [{"id": "d2i1", "t": {"az": "İstədiyini barmağı ilə göstərməkdə çətinlik çəkir", "ru": "Испытывает трудности с указанием на желаемое пальцем", "en": "Has difficulty pointing to what he or she wants"}}, {"id": "d2i2", "t": {"az": "Baş yelləmə, əl yellətmə kimi mənalı jestlərdən istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием значимых жестов, таких как кивок или помахивание рукой", "en": "Has difficulty using meaningful gestures such as nodding or waving"}}, {"id": "d2i3", "t": {"az": "Jesti söz və baxışla birləşdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с сочетанием жеста со словом и взглядом", "en": "Has difficulty combining a gesture with words and gaze"}}], "mean": {"az": "göstərmək, işarə etmək, baş-əl hərəkətləri ilə ünsiyyət", "ru": "общение с помощью указания, жестов и движений головы и рук", "en": "communicating by showing, pointing and gestures of the head and hands"}, "means": {"az": "Jestlər sözdən əvvəl ünsiyyətin əsasını təşkil edir. İstəyi, razılığı və ya imtinanı bildirməyə imkan verir.", "ru": "Жесты лежат в основе общения до появления слов. Они позволяют выразить желание, согласие или отказ.", "en": "Gestures form the basis of communication before words. They allow the child to express a wish, agreement or refusal."}, "looks": {"az": "Uşaq istədiyini göstərmək əvəzinə sizin əlinizdən tutub aparır, ağlayır və ya baş yelləmə, əl yellətmə kimi jestlərdən az istifadə edir.", "ru": "Вместо того чтобы показать желаемое, ребёнок берёт вас за руку и ведёт, плачет или редко использует жесты, например кивок и махание рукой.", "en": "Instead of pointing to what he or she wants, the child takes your hand and leads you, cries, or rarely uses gestures such as nodding or waving."}, "support": {"az": "Sevdiyi oyuncağı əli çatmayan yerə qoyun, göstərməsini gözləyin; gündəlik rutinlərdə «ver», «bax» jestlərini nümunə göstərin.", "ru": "Положите любимую игрушку в недоступное место и подождите, пока ребёнок покажет; в повседневных ситуациях демонстрируйте жесты «дай», «смотри».", "en": "Place a favorite toy out of reach and wait for the child to point; model the gestures \"give\" and \"look\" in daily routines."}}, {"id": "d3", "title": {"az": "Mimika və emosional ifadə", "ru": "Мимика и эмоциональное выражение", "en": "Facial Expressions and Emotional Expression"}, "task": {"az": "Oyun və gözlənilməz hadisələr zamanı (oyuncağın səs çıxarması, balonun partlaması) uşağın üz ifadəsinə baxılır.", "ru": "Наблюдают за выражением лица ребёнка во время игры и неожиданных событий (игрушка издаёт звук, лопается шарик).", "en": "The child's facial expression is observed during play and unexpected events (a toy makes a sound, a balloon pops)."}, "items": [{"id": "d3i1", "t": {"az": "Üz ifadəsi vəziyyətə uyğun gəlmir", "ru": "Выражение лица не соответствует ситуации", "en": "Facial expression does not match the situation"}}, {"id": "d3i2", "t": {"az": "Hisslərini başqasına yönəltməkdə çətinlik çəkir (məsələn, sevincini sizə baxıb göstərmir)", "ru": "Испытывает трудности с адресацией своих чувств другому человеку (например, радуясь, не смотрит на вас)", "en": "Has difficulty directing his or her feelings to another person (for example, does not look at you when happy)"}}, {"id": "d3i3", "t": {"az": "Qarşısındakının ifadəsinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на выражение лица собеседника", "en": "Has difficulty responding appropriately to the other person's facial expression"}}], "mean": {"az": "üz ifadəsi ilə hissləri bildirmək", "ru": "выражение чувств мимикой", "en": "expressing feelings through facial expressions"}, "means": {"az": "Üz ifadəsi hisslərimizi başqalarına çatdırır. Ünsiyyətin sözsüz hissəsidir və qarşılıqlı anlaşmaya kömək edir.", "ru": "Мимика передаёт наши чувства другим людям. Это невербальная часть общения, способствующая взаимопониманию.", "en": "Facial expressions convey our feelings to others. They are the nonverbal part of communication and support mutual understanding."}, "looks": {"az": "Üz ifadəsi az dəyişir və ya vəziyyətə uyğun gəlmir; sevincini və ya narazılığını üzü ilə göstərməkdə çətinlik çəkir.", "ru": "Выражение лица меняется мало или не соответствует ситуации; ребёнку трудно показать лицом радость или недовольство.", "en": "The child's facial expression changes little or does not fit the situation; the child has difficulty showing joy or displeasure on the face."}, "support": {"az": "Güzgü qarşısında və şəkil kartları ilə sevinc, kədər, təəccüb ifadələrini birlikdə təqlid edin.", "ru": "Вместе подражайте выражениям радости, грусти, удивления перед зеркалом и на карточках с картинками.", "en": "Imitate expressions of joy, sadness and surprise together in front of a mirror and with picture cards."}}, {"id": "d4", "title": {"az": "Birgə diqqət — cavab", "ru": "Совместное внимание: отклик", "en": "Joint Attention: Response"}, "task": {"az": "Mütəxəssis uzaqdakı oyuncağa baxır və ona barmağı ilə işarə edir, uşağın reaksiyasına baxılır.", "ru": "Специалист смотрит на далёкую игрушку и указывает на неё пальцем, наблюдают за реакцией ребёнка.", "en": "The examiner looks at a distant toy and points to it, and the child's response is observed."}, "items": [{"id": "d4i1", "t": {"az": "Başqasının baxışını və ya işarəsini izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с прослеживанием взгляда или указательного жеста другого человека", "en": "Has difficulty following another person's gaze or pointing gesture"}}, {"id": "d4i2", "t": {"az": "Göstərilən əşyaya diqqətini yönəltməkdə çətinlik çəkir", "ru": "Испытывает трудности с направлением внимания на указанный предмет", "en": "Has difficulty directing attention to the indicated object"}}, {"id": "d4i3", "t": {"az": "Diqqəti paylaşmaq üçün geri baxmaqda çətinlik çəkir", "ru": "Испытывает трудности с обратным взглядом на партнёра для разделения внимания", "en": "Has difficulty looking back at the partner to share attention"}}], "mean": {"az": "başqasının göstərdiyi şeyə baxmaq", "ru": "следование за взглядом и указанием другого человека", "en": "looking at what another person shows"}, "means": {"az": "Başqasının baxdığı və ya göstərdiyi şeyə baxmaq birgə diqqətin əsasıdır. Uşaq bu yolla yeni sözləri və əşyaları öyrənir.", "ru": "Умение посмотреть туда, куда смотрит или показывает другой человек, — основа совместного внимания. Так ребёнок узнаёт новые слова и предметы.", "en": "Looking at what another person looks at or points to is the basis of joint attention. Through this the child learns new words and objects."}, "looks": {"az": "Siz bir şeyi göstərəndə və ya adını çəkəndə uşaq o tərəfə baxmır, öz işi ilə məşğul olur.", "ru": "Когда вы показываете на предмет или называете его, ребёнок не смотрит в ту сторону и занимается своим делом.", "en": "When you point to or name something, the child does not look in that direction and keeps doing his or her own activity."}, "support": {"az": "Maraqlı oyuncağı göstərib adını deyin, əvvəlcə yaxından, sonra tədricən uzaqdan; şəkilli kitabda barmaqla göstərin.", "ru": "Покажите интересную игрушку и назовите её: сначала вблизи, затем постепенно издалека; указывайте пальцем в книге с картинками.", "en": "Show an interesting toy and name it, first up close, then gradually from a distance; point with a finger in a picture book."}}, {"id": "d5", "title": {"az": "Birgə diqqət — təşəbbüs", "ru": "Совместное внимание: инициация", "en": "Joint Attention: Initiation"}, "task": {"az": "Uşağın özü maraqlı bir şey tapanda (səs çıxaran oyuncaq, uçan baloncuk) nə etdiyinə baxılır.", "ru": "Наблюдают за действиями ребёнка, когда он сам находит что-то интересное (звучащая игрушка, летящий пузырь).", "en": "The examiner observes what the child does on finding something interesting (a noisy toy, a floating bubble)."}, "items": [{"id": "d5i1", "t": {"az": "Maraqlı şeyi göstərmək üçün özü təşəbbüs etməkdə çətinlik çəkir", "ru": "Испытывает трудности с самостоятельной инициативой показать интересный предмет", "en": "Has difficulty taking the initiative to show an interesting object"}}, {"id": "d5i2", "t": {"az": "Paylaşmaq üçün əşyanı gətirməkdə və ya uzatmaqda çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы принести или протянуть предмет, чтобы поделиться им", "en": "Has difficulty bringing or holding out an object to share it"}}, {"id": "d5i3", "t": {"az": "Baxışla sizin diqqətinizi cəlb etməkdə çətinlik çəkir", "ru": "Испытывает трудности с привлечением вашего внимания взглядом", "en": "Has difficulty attracting your attention with gaze"}}], "mean": {"az": "başqasının diqqətini özü bir şeyə yönəltmək", "ru": "привлечение внимания другого человека к предмету по собственной инициативе", "en": "directing another person's attention to something on his or her own initiative"}, "means": {"az": "Uşağın maraqlandığı şeyi başqasına göstərməsi sosial ünsiyyətin vacib hissəsidir. Bu, təkcə istək bildirmək deyil, paylaşmaqdır.", "ru": "Показывать другому то, что интересно самому, — важная часть социального общения. Это не только выражение желания, но и стремление поделиться.", "en": "Showing another person what interests the child is an important part of social communication. It is not only expressing a wish but sharing."}, "looks": {"az": "Uşaq maraqlı gördüyü şeyi sizə göstərmir, gətirmir; istəyi olmayanda sizə müraciət etməz.", "ru": "Ребёнок не показывает и не приносит вам то, что ему интересно; не обращается к вам, когда ему ничего не нужно.", "en": "The child does not show or bring you things he or she finds interesting and does not approach you when there is no request."}, "support": {"az": "Uşağın maraq göstərdiyi hər şeyə sevinclə cavab verin; onunla birlikdə baxıb şərh edin.", "ru": "С радостью реагируйте на всё, что вызывает у ребёнка интерес; рассматривайте и комментируйте вместе с ним.", "en": "Respond warmly to everything the child shows interest in; look at it and comment on it together."}}, {"id": "d6", "title": {"az": "Sosial təbəssüm və sevincin paylaşılması", "ru": "Социальная улыбка и разделение радости", "en": "Social Smile and Sharing of Enjoyment"}, "task": {"az": "Birgə oyun (baloncuk, qıdıqlama, top) zamanı uşağın sevincinə baxılır.", "ru": "Наблюдают за проявлением радости ребёнка во время совместной игры (пузыри, щекотка, мяч).", "en": "The child's enjoyment is observed during joint play (bubbles, tickling, a ball)."}, "items": [{"id": "d6i1", "t": {"az": "Sizin təbəssümünüzə təbəssümlə cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответной улыбкой на вашу улыбку", "en": "Has difficulty smiling back in response to your smile"}}, {"id": "d6i2", "t": {"az": "Sevincini başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с разделением радости с другим человеком", "en": "Has difficulty sharing enjoyment with another person"}}, {"id": "d6i3", "t": {"az": "Birgə fəaliyyətdən zövq almaqda çətinlik çəkir", "ru": "Испытывает трудности с получением удовольствия от совместной деятельности", "en": "Has difficulty enjoying joint activities"}}], "mean": {"az": "sevinci başqası ilə bölüşmək", "ru": "разделение радости с другим человеком", "en": "sharing enjoyment with another person"}, "means": {"az": "Sevinci başqası ilə bölüşmək uşağa münasibətlərdən zövq almağı öyrədir. Bu, birgə oyun və dostluğun əsasıdır.", "ru": "Разделение радости с другим человеком учит ребёнка получать удовольствие от отношений. Это основа совместной игры и дружбы.", "en": "Sharing enjoyment with another person teaches the child to take pleasure in relationships. It is the basis of joint play and friendship."}, "looks": {"az": "Uşaq sevindiyi anda sizə baxıb gülümsəmir, uğurunu göstərmir, birgə oyundan az zövq alır.", "ru": "В момент радости ребёнок не смотрит на вас с улыбкой, не показывает свой успех, меньше получает удовольствие от совместной игры.", "en": "At a moment of delight, the child does not look at you and smile, does not show achievements and enjoys joint play less."}, "support": {"az": "Sevdiyi oyunları (top, baloncuk, gizlənpaç) təkrarlayın, uşağın sevincinə sizin də sevincinizlə cavab verin.", "ru": "Повторяйте любимые игры (мяч, мыльные пузыри, прятки) и отвечайте на радость ребёнка собственной радостью.", "en": "Repeat favorite games (ball, bubbles, hide-and-seek) and respond to the child's joy with your own."}}, {"id": "d7", "title": {"az": "Sosial təşəbbüslərin keyfiyyəti", "ru": "Качество социальных инициатив", "en": "Quality of Social Overtures"}, "task": {"az": "Seans boyu uşağın sizinlə əlaqə qurmaq cəhdlərinə baxılır.", "ru": "На протяжении сессии наблюдают за попытками ребёнка установить с вами контакт.", "en": "Throughout the session the child's attempts to make contact with you are observed."}, "items": [{"id": "d7i1", "t": {"az": "Ünsiyyət cəhdləri aydın deyil və ya vəziyyətə uyğun gəlmir", "ru": "Попытки общения неясны или не соответствуют ситуации", "en": "Overtures are unclear or inappropriate to the situation"}}, {"id": "d7i2", "t": {"az": "Sizi ünsiyyətə dəvət etməkdə çətinlik çəkir (məsələn, oyuna çağırmır)", "ru": "Испытывает трудности с приглашением вас к общению (например, не зовёт играть)", "en": "Has difficulty inviting you to interact (for example, does not ask you to play)"}}, {"id": "d7i3", "t": {"az": "Təşəbbüsləri yersiz anda olur", "ru": "Инициативы возникают в неподходящий момент", "en": "Overtures occur at inappropriate moments"}}], "mean": {"az": "ünsiyyəti özü başlatmaq və davam etdirmək", "ru": "самостоятельное начало и поддержание общения", "en": "initiating and maintaining communication independently"}, "means": {"az": "Uşağın ünsiyyəti özü başlatması və davam etdirməsi sosial inkişafın göstəricisidir. Bu, dostluq qurmaq və kömək istəmək üçün lazımdır.", "ru": "Самостоятельное начало и поддержание общения — показатель социального развития. Оно необходимо, чтобы заводить друзей и просить о помощи.", "en": "Initiating and maintaining communication independently is an indicator of social development. It is needed to make friends and ask for help."}, "looks": {"az": "Uşaq özü oyun təklif etmir, ünsiyyət yalnız böyüyün təşəbbüsü ilə olur, bəzən də yersiz anda başlayır.", "ru": "Ребёнок сам не предлагает игру, общение возникает только по инициативе взрослого, а иногда начинается в неподходящий момент.", "en": "The child does not suggest play on his or her own, interaction occurs only on the adult's initiative, and sometimes it begins at an inappropriate moment."}, "support": {"az": "Uşağın ən kiçik cəhdinə də cavab verin; «birlikdə oynayaq?» kimi sadə dəvətləri nümunə göstərin.", "ru": "Отвечайте даже на самую маленькую попытку ребёнка; показывайте простые приглашения, например «давай поиграем вместе?».", "en": "Respond to even the smallest attempt by the child; model simple invitations such as \"shall we play together?\""}}, {"id": "d8", "title": {"az": "Qarşılıqlı ünsiyyət və söhbət", "ru": "Взаимное общение и беседа", "en": "Reciprocal Communication and Conversation"}, "task": {"az": "Şəkilli kitaba baxarkən və ya gündəlik mövzuda (məktəb, oyun, ailə) söhbət edilir.", "ru": "Беседа во время рассматривания книги с картинками или на бытовые темы (школа, игра, семья).", "en": "Conversation while looking at a picture book or about everyday topics (school, play, family)."}, "items": [{"id": "d8i1", "t": {"az": "Söhbətdə növbə gözləməkdə çətinlik çəkir", "ru": "Испытывает трудности с ожиданием своей очереди в беседе", "en": "Has difficulty waiting for a turn in conversation"}}, {"id": "d8i2", "t": {"az": "Söhbəti özü başlatmaqda və davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с самостоятельным началом и поддержанием беседы", "en": "Has difficulty initiating and maintaining a conversation"}}, {"id": "d8i3", "t": {"az": "Sualınıza uyğun cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответом, соответствующим вашему вопросу", "en": "Has difficulty giving an answer that fits your question"}}], "mean": {"az": "növbə ilə danışmaq", "ru": "очерёдность в разговоре", "en": "taking turns in conversation"}, "means": {"az": "Növbə ilə danışmaq qarşılıqlı söhbətin əsasıdır. Uşaq dinləməyi, cavab verməyi və mövzunu davam etdirməyi öyrənir.", "ru": "Очерёдность в разговоре — основа диалога. Ребёнок учится слушать, отвечать и продолжать тему.", "en": "Taking turns in conversation is the basis of dialogue. The child learns to listen, respond and continue the topic."}, "looks": {"az": "Söhbətdə növbə gözləmir, sualı cavabsız qoyur və ya fikrini davam etdirmir, mövzudan kənara çıxır.", "ru": "В разговоре не ждёт своей очереди, оставляет вопрос без ответа или не продолжает мысль, уходит от темы.", "en": "The child does not wait for a turn in conversation, leaves a question unanswered or does not continue a thought, and drifts off the topic."}, "support": {"az": "Növbəli oyunlarda (top ötürmə, kub qoyma) «mənim növbəm, sənin növbən» deyin; söhbətdə qısa sual verib gözləyin.", "ru": "В играх по очереди (передача мяча, укладывание кубиков) говорите «моя очередь, твоя очередь»; в разговоре задайте короткий вопрос и подождите.", "en": "In turn-taking games (passing a ball, stacking blocks) say \"my turn, your turn\"; in conversation ask a short question and wait."}}, {"id": "d9", "title": {"az": "Nitqin xüsusiyyətləri", "ru": "Особенности речи", "en": "Speech Characteristics"}, "task": {"az": "Seans boyu uşağın necə danışdığına qulaq asılır.", "ru": "На протяжении сессии прислушиваются к тому, как ребёнок говорит.", "en": "Throughout the session the examiner listens to how the child speaks."}, "items": [{"id": "d9i1", "t": {"az": "Səsi monoton, robot kimi və ya qeyri-adi tonda səslənir", "ru": "Голос монотонный, «роботизированный» или необычный по тону", "en": "Voice sounds monotone, robotic, or unusual in tone"}}, {"id": "d9i2", "t": {"az": "Eşitdiyi sözləri təkrar edir (exolaliya) və ya qəlibləşmiş ifadələr işlədir", "ru": "Повторяет услышанные слова (эхолалия) или использует шаблонные фразы", "en": "Repeats words heard (echolalia) or uses stereotyped phrases"}}, {"id": "d9i3", "t": {"az": "Nitqin sürəti və ucalığı vəziyyətə uyğun gəlmir", "ru": "Темп и громкость речи не соответствуют ситуации", "en": "Rate and volume of speech do not match the situation"}}], "mean": {"az": "səs tonu, tempi, intonasiya", "ru": "тон голоса, темп, интонация", "en": "tone of voice, pace, intonation"}, "means": {"az": "Səsin tonu, sürəti və intonasiyası nitqin duyğusunu çatdırır. Dinləyicinin mesajı düzgün anlamasına kömək edir.", "ru": "Тон, скорость и интонация голоса передают эмоциональную окраску речи. Они помогают слушателю правильно понять сообщение.", "en": "The tone, speed and intonation of the voice convey the emotion of speech. They help the listener understand the message correctly."}, "looks": {"az": "Nitqi monoton, çox sürətli, çox ucadan və ya qeyri-adi tonda səslənir.", "ru": "Речь звучит монотонно, слишком быстро, слишком громко или необычным тоном.", "en": "Speech sounds monotone, too fast, too loud or in an unusual tone."}, "support": {"az": "Nağıl və kukla oyunlarında müxtəlif səslərlə danışın, uşaqdan da sevinc, sual və təəccüb tonlarını təkrarlamasını xahiş edin.", "ru": "В сказках и кукольных играх говорите разными голосами, просите ребёнка повторить интонации радости, вопроса и удивления.", "en": "In stories and puppet play use different voices, and ask the child to repeat tones of joy, questioning and surprise."}}, {"id": "d10", "title": {"az": "Funksional və simvolik oyun", "ru": "Функциональная и символическая игра", "en": "Functional and Symbolic Play"}, "task": {"az": "Uşağa oyuncaqlar (kuklalar, qab-qacaq, maşın) verilir və necə oynadığına baxılır.", "ru": "Ребёнку дают игрушки (куклы, посуду, машинки) и наблюдают, как он играет.", "en": "The child is given toys (dolls, dishes, cars) and the examiner observes how he or she plays."}, "items": [{"id": "d10i1", "t": {"az": "Oyuncaqlardan təyinatına uyğun istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием игрушек по назначению", "en": "Has difficulty using toys for their intended purpose"}}, {"id": "d10i2", "t": {"az": "Uydurma oyuna keçməkdə çətinlik çəkir (məsələn, boş qabdan «içmək»)", "ru": "Испытывает трудности с переходом к воображаемой игре (например, «пить» из пустой чашки)", "en": "Has difficulty moving to pretend play (for example, \"drinking\" from an empty cup)"}}, {"id": "d10i3", "t": {"az": "Oyunda çeviklik və yaradıcılıq göstərməkdə çətinlik çəkir", "ru": "Испытывает трудности с проявлением гибкости и творчества в игре", "en": "Has difficulty showing flexibility and creativity in play"}}], "mean": {"az": "oyuncağı təyinatına uyğun və təsəvvürlə oynamaq", "ru": "игра с игрушкой по назначению и с воображением", "en": "playing with toys functionally and imaginatively"}, "means": {"az": "Oyun uşağın düşünməsini və təxəyyülünü göstərir. Oyuncağı təyinatına uyğun və təsəvvürlə işlətmək dil və sosial inkişafla bağlıdır.", "ru": "Игра отражает мышление и воображение ребёнка. Использование игрушки по назначению и с воображением связано с развитием речи и социальным развитием.", "en": "Play shows the child's thinking and imagination. Using toys as intended and imaginatively is linked to language and social development."}, "looks": {"az": "Oyuncaqları düzür, çevirir, yalnız bir hissəsi ilə oynayır; «çay içirik» kimi uydurma oyuna az keçir.", "ru": "Выстраивает и переворачивает игрушки, играет только с какой-то одной их частью; редко переходит к условной игре, например «пьём чай».", "en": "The child lines up or turns toys over and plays with only one part; rarely moves on to pretend play such as \"having tea\"."}, "support": {"az": "Kukla, qab-qacaq və maşınlarla sadə hərəkətləri birlikdə göstərin (yedirt, yat, sür), sonra uşağa növbə verin.", "ru": "Вместе показывайте простые действия с куклой, посудой и машинками (накорми, уложи спать, поезжай), затем уступайте очередь ребёнку.", "en": "Show simple actions together with a doll, dishes and cars (feed, put to sleep, drive), then give the child a turn."}}, {"id": "d11", "title": {"az": "Təxəyyül və yaradıcılıq", "ru": "Воображение и творчество", "en": "Imagination and Creativity"}, "task": {"az": "Doğum günü süfrəsi və ya mətbəx oyunu qurulur, uşağın süjet qurub-qurmadığına baxılır.", "ru": "Организуют игру в день рождения или кухню и наблюдают, строит ли ребёнок сюжет.", "en": "A birthday party or kitchen play scene is set up and the examiner observes whether the child builds a storyline."}, "items": [{"id": "d11i1", "t": {"az": "Özü yeni oyun süjeti qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с самостоятельным построением нового игрового сюжета", "en": "Has difficulty creating a new play storyline independently"}}, {"id": "d11i2", "t": {"az": "Bir əşyanı başqası yerinə istifadə etməkdə çətinlik çəkir (məsələn, kubu telefon kimi)", "ru": "Испытывает трудности с использованием одного предмета вместо другого (например, кубика как телефона)", "en": "Has difficulty using one object to stand for another (for example, a block as a phone)"}}, {"id": "d11i3", "t": {"az": "Rol oyununda iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в ролевой игре", "en": "Has difficulty taking part in role play"}}], "mean": {"az": "özünün hekayə və ssenarisini qurmaq", "ru": "придумывание собственных историй и сценариев", "en": "creating his or her own stories and scenarios"}, "means": {"az": "Öz hekayəsini qurmaq uşağın təxəyyülünü və yaradıcı düşüncəsini göstərir. Sosial rollarını anlamağa kömək edir.", "ru": "Придумывание собственной истории показывает воображение и творческое мышление ребёнка. Помогает понять социальные роли.", "en": "Creating one's own story shows the child's imagination and creative thinking. It helps in understanding social roles."}, "looks": {"az": "Oyunda yeni hadisə qurmur, eyni səhnəni təkrarlayır və ya yalnız göstərilən oyunu təqlid edir.", "ru": "Не создаёт в игре новых событий, повторяет одну и ту же сцену или только подражает показанной игре.", "en": "The child does not create new events in play, repeats the same scene or only imitates the play that was shown."}, "support": {"az": "Sadə ssenari təklif edin (ayı xəstələnib, həkimə aparaq), uşağın əlavə etdiyi hər ideyanı dəstəkləyin.", "ru": "Предложите простой сценарий (мишка заболел, отвезём его к врачу), поддерживайте каждую идею, которую добавляет ребёнок.", "en": "Suggest a simple scenario (the bear is sick, let's take him to the doctor) and support every idea the child adds."}}, {"id": "d12", "title": {"az": "Stereotip hərəkətlər və manerizmlər", "ru": "Стереотипные движения и манеризмы", "en": "Stereotyped Movements and Mannerisms"}, "task": {"az": "Seans boyu uşağın əl, barmaq və bədən hərəkətlərinə baxılır.", "ru": "На протяжении сессии наблюдают за движениями рук, пальцев и тела ребёнка.", "en": "Throughout the session the child's hand, finger, and body movements are observed."}, "items": [{"id": "d12i1", "t": {"az": "Əl və ya barmaqlarla təkrarlanan hərəkətlər edir", "ru": "Совершает повторяющиеся движения руками или пальцами", "en": "Makes repetitive hand or finger movements"}}, {"id": "d12i2", "t": {"az": "Bədənin təkrarlanan hərəkətləri var (yırğalanma, sıçrama)", "ru": "Совершает повторяющиеся движения телом (раскачивание, подпрыгивание)", "en": "Makes repetitive body movements (rocking, jumping)"}}, {"id": "d12i3", "t": {"az": "Həyəcan və ya gərginlik zamanı bu hərəkətlər artır", "ru": "Эти движения усиливаются при возбуждении или напряжении", "en": "These movements increase with excitement or tension"}}], "mean": {"az": "təkrarlanan bədən hərəkətləri", "ru": "повторяющиеся движения тела", "en": "repetitive body movements"}, "means": {"az": "Təkrarlanan bədən hərəkətləri uşağın özünü tənzimləmə yollarından ola bilər. Gündəlik fəaliyyətə təsiri olduqda diqqətlə izlənilir.", "ru": "Повторяющиеся движения тела могут быть одним из способов саморегуляции ребёнка. Если они влияют на повседневную деятельность, за ними внимательно наблюдают.", "en": "Repetitive body movements can be one of the child's ways of self-regulation. They are monitored carefully when they affect daily activities."}, "looks": {"az": "Əl-barmaq hərəkətləri, yırğalanma və ya sıçrama tez-tez təkrarlanır, həyəcan və gərginlik zamanı artır.", "ru": "Часто повторяются движения рук и пальцев, раскачивание или подпрыгивание; усиливаются при волнении и напряжении.", "en": "Hand and finger movements, rocking or jumping are repeated often and increase during excitement and tension."}, "support": {"az": "Hərəkətin nə vaxt artdığını qeyd edin; hərəkət ehtiyacı üçün təhlükəsiz alternativlər verin (top, sıxma oyuncağı, hərəkətli oyunlar).", "ru": "Отмечайте, когда движение усиливается; предлагайте безопасные альтернативы для потребности в движении (мяч, игрушка-антистресс, подвижные игры).", "en": "Note when the movement increases; offer safe alternatives for the need to move (ball, squeeze toy, active games)."}}, {"id": "d13", "title": {"az": "Predmetlərin təkrarlanan istifadəsi", "ru": "Повторяющееся использование предметов", "en": "Repetitive Use of Objects"}, "task": {"az": "Oyuncaqlar və kublar verilir, uşağın onları necə işlətdiyinə baxılır.", "ru": "Ребёнку дают игрушки и кубики и наблюдают, как он с ними обращается.", "en": "The child is given toys and blocks and the examiner observes how he or she handles them."}, "items": [{"id": "d13i1", "t": {"az": "Əşyaları təkrar sıralayır və ya fırladır", "ru": "Повторно выстраивает в ряд или вращает предметы", "en": "Repeatedly lines up or spins objects"}}, {"id": "d13i2", "t": {"az": "Oyuncağın yalnız bir hissəsi ilə məşğul olur (məsələn, maşının təkəri)", "ru": "Занимается только одной частью игрушки (например, колесом машинки)", "en": "Focuses on only one part of a toy (for example, a car wheel)"}}, {"id": "d13i3", "t": {"az": "Eyni hərəkəti dəfələrlə təkrarlayır", "ru": "Многократно повторяет одно и то же действие", "en": "Repeats the same action many times"}}], "mean": {"az": "əşyalarla eyni hərəkəti təkrar etmək", "ru": "повторение одного и того же действия с предметами", "en": "repeating the same action with objects"}, "means": {"az": "Əşyalarla təkrarlanan istifadə oyunun çeşidliliyini azalda bilər. Uşağın əşyaları necə işlətdiyi onun marağı və çevikliyi haqqında məlumat verir.", "ru": "Повторяющееся использование предметов может снижать разнообразие игры. То, как ребёнок обращается с предметами, даёт информацию о его интересах и гибкости.", "en": "Repetitive use of objects can reduce the variety of play. How the child handles objects gives information about interests and flexibility."}, "looks": {"az": "Əşyaları sıralayır, fırladır və ya eyni hərəkəti dəfələrlə təkrarlayır, oyuncağın yalnız bir hissəsi ilə məşğul olur.", "ru": "Выстраивает предметы в ряд, вращает их или многократно повторяет одно и то же действие, занимается только одной частью игрушки.", "en": "The child lines up objects, spins them or repeats the same action many times, and focuses on only one part of a toy."}, "support": {"az": "Uşağın seçdiyi əşya ilə yeni bir addım əlavə edin (sıraladığı kubdan qala qurun), tədricən oyunu genişləndirin.", "ru": "Добавьте новый шаг к выбранному ребёнком предмету (постройте башню из кубиков, которые он выстроил), постепенно расширяйте игру.", "en": "Add a new step to the object the child chose (build a tower from the blocks he or she lined up) and gradually expand the play."}}, {"id": "d14", "title": {"az": "Məhdud maraqlar və rituallar", "ru": "Ограниченные интересы и ритуалы", "en": "Restricted Interests and Rituals"}, "task": {"az": "Uşağın sevdiyi mövzuları söhbətdə və oyunda müşahidə edin, istəsəniz bir tapşırığı yarımçıq dayandırıb reaksiyasına baxın.", "ru": "Наблюдайте за любимыми темами ребёнка в беседе и игре; при желании прервите одно задание и посмотрите на реакцию.", "en": "Observe the child's favorite topics in conversation and play; if desired, stop one task partway and observe the reaction."}, "items": [{"id": "d14i1", "t": {"az": "Çox dar və qeyri-adi mövzuya intensiv bağlıdır", "ru": "Интенсивно увлечён очень узкой или необычной темой", "en": "Is intensely absorbed in a very narrow or unusual topic"}}, {"id": "d14i2", "t": {"az": "Eyni qaydaya və ya ardıcıllığa israrla ehtiyac duyur", "ru": "Настойчиво требует соблюдения одного и того же порядка или последовательности", "en": "Insists on the same routine or sequence"}}, {"id": "d14i3", "t": {"az": "Planın və ya yerin dəyişməsinə güclü müqavimət göstərir", "ru": "Сильно сопротивляется изменению плана или места", "en": "Strongly resists changes of plan or place"}}], "mean": {"az": "dar maraqlar, eyni qaydaya israr", "ru": "узкие интересы, настойчивое требование неизменности порядка", "en": "narrow interests, insistence on sameness"}, "means": {"az": "Maraqların dar olması və qaydaya israr uşağın əhatəsinə uyğunlaşmasını çətinləşdirə bilər. Dəyişikliyə dözümlülük gündəlik həyatda lazımdır.", "ru": "Узкий круг интересов и настойчивое требование одного и того же порядка могут затруднять адаптацию ребёнка к окружению. Терпимость к изменениям необходима в повседневной жизни.", "en": "Narrow interests and insistence on the same routine can make it harder for the child to adapt to the environment. Tolerance of change is needed in daily life."}, "looks": {"az": "Yalnız bir mövzudan danışır, ardıcıllığın pozulmasına və ya plan dəyişikliyinə güclü etiraz edir.", "ru": "Говорит только на одну тему, резко протестует против нарушения последовательности или изменения планов.", "en": "The child talks about only one topic and strongly protests when the sequence is disrupted or plans change."}, "support": {"az": "Gündəlik cədvəli şəkillərlə göstərin, dəyişiklikləri əvvəlcədən xəbərdar edin, kiçik dəyişikliklərə tədricən alışdırın.", "ru": "Показывайте распорядок дня в картинках, заранее предупреждайте об изменениях, постепенно приучайте к небольшим изменениям.", "en": "Show the daily schedule with pictures, warn about changes in advance and gradually accustom the child to small changes."}}, {"id": "d15", "title": {"az": "Sensor maraqlar", "ru": "Сенсорные интересы", "en": "Sensory Interests"}, "task": {"az": "Oyuncaq və əşyalarla oynayarkən uşağın onlara necə yanaşdığına baxılır.", "ru": "Наблюдают, как ребёнок обращается с игрушками и предметами во время игры.", "en": "The examiner observes how the child approaches toys and objects during play."}, "items": [{"id": "d15i1", "t": {"az": "Əşyaları qoxulayır, yalayır və ya çox yaxından baxır", "ru": "Обнюхивает, облизывает предметы или рассматривает их очень близко", "en": "Smells or licks objects, or looks at them from very close"}}, {"id": "d15i2", "t": {"az": "İşığa, səsə və ya toxunuşa qeyri-adi maraq göstərir", "ru": "Проявляет необычный интерес к свету, звуку или прикосновению", "en": "Shows unusual interest in light, sound, or touch"}}, {"id": "d15i3", "t": {"az": "Müəyyən sensor təsiri təkrar-təkrar axtarır", "ru": "Многократно ищет определённое сенсорное воздействие", "en": "Repeatedly seeks a particular sensory input"}}], "mean": {"az": "əşyaların səs, qoxu və toxunuşuna qeyri-adi maraq", "ru": "необычный интерес к звуку, запаху и тактильным свойствам предметов", "en": "unusual interest in the sounds, smells and feel of objects"}, "means": {"az": "Sensor maraq uşağın toxunuş, səs, qoxu və görüntülərə yanaşmasını göstərir. Bu, oyunu və diqqəti formalaşdıra bilər.", "ru": "Сенсорный интерес отражает отношение ребёнка к прикосновениям, звукам, запахам и зрительным образам. Он может влиять на игру и внимание.", "en": "Sensory interest reflects how the child responds to touch, sounds, smells and visual input. It can shape play and attention."}, "looks": {"az": "Əşyaları qoxulayır, yalayır, çox yaxından baxır, işığa və ya səsə qeyri-adi maraq göstərir.", "ru": "Обнюхивает и облизывает предметы, рассматривает их очень близко, проявляет необычный интерес к свету или звуку.", "en": "The child sniffs and licks objects, looks at them very closely and shows unusual interest in light or sound."}, "support": {"az": "Təhlükəsiz sensor oyunlar təklif edin (qum, su, hamar və kobud materiallar), maraqlandığı hissi oyunda istifadə edin.", "ru": "Предложите безопасные сенсорные игры (песок, вода, гладкие и шершавые материалы), используйте интересующее ощущение в игре.", "en": "Offer safe sensory play (sand, water, smooth and rough materials) and use the sensation of interest within play."}}], "specialist": [{"az": "ADOS-2 müşahidələrini inkişaf tarixçəsi və digər mənbələrlə birlikdə qiymətləndirin.", "ru": "Оценивайте наблюдения ADOS-2 вместе с историей развития и другими источниками.", "en": "Interpret ADOS-2 observations together with developmental history and other sources."}, {"az": "Sosial-ünsiyyət çətinlikləri davamlıdırsa, ADI-R müsahibəsi ilə tamamlayın.", "ru": "При устойчивых социально-коммуникативных трудностях дополните интервью ADI-R.", "en": "If social-communication difficulties persist, complement with the ADI-R interview."}, {"az": "Komanda müzakirəsi və klinik mülahizə ilə yekunlaşdırın.", "ru": "Завершите командным обсуждением и клиническим суждением.", "en": "Conclude with team discussion and clinical judgment."}], "parentIntro": {"az": "Aşağıdakılar diaqnoz deyil — uşağınıza gündəlik həyatda dəstək olmaq üçün sadə addımlardır.", "ru": "Ниже — не диагноз, а простые шаги поддержки ребёнка в повседневной жизни.", "en": "The following is not a diagnosis — these are simple steps to support your child day to day."}, "parentTips": [{"az": "Göz təması üçün uşağın sevdiyi oyuncağı öz üzünüzün yanında tutun.", "ru": "Для зрительного контакта держите любимую игрушку у своего лица.", "en": "For eye contact, hold a favorite toy near your face."}, {"az": "Qısa, aydın cümlələrlə danışın və cavab üçün vaxt verin.", "ru": "Говорите короткими ясными фразами и давайте время на ответ.", "en": "Speak in short, clear sentences and allow time to respond."}, {"az": "Gündəlik rejimi sabit saxlayın — bu, təhlükəsizlik hissi verir.", "ru": "Поддерживайте стабильный распорядок — это даёт чувство безопасности.", "en": "Keep a steady daily routine — it provides a sense of security."}], "games": [{"az": "'Növbə ilə' oyunu: topu bir-birinizə yuvarlayın, hər dəfə ad deyin.", "ru": "Игра «по очереди»: катайте мяч друг другу, называя имя.", "en": "'Take turns' game: roll a ball to each other, saying the name each time."}, {"az": "Köpük üfürmək: birgə diqqət və paylaşılan sevinc üçün.", "ru": "Пускание пузырей: для совместного внимания и общей радости.", "en": "Blowing bubbles: for joint attention and shared joy."}, {"az": "Güzgü oyunu: uşağın hərəkət və səslərini təkrarlayın.", "ru": "Игра в зеркало: повторяйте движения и звуки ребёнка.", "en": "Mirror game: imitate the child's movements and sounds."}]}, "adir": {"id": "adir", "name": "ADI-R", "full": {"az": "Otizm Diaqnostik Müsahibə — Yenidən işlənmiş", "ru": "Диагностическое интервью при аутизме — переработанное", "en": "Autism Diagnostic Interview — Revised"}, "age": {"az": "Zehni yaşı ~2 ildən yuxarı uşaq və böyüklər üçün", "ru": "Дети и взрослые с умственным возрастом ~от 2 лет", "en": "Children and adults with mental age ~2 years and above"}, "summary": {"az": "Valideyn/qəyyumla aparılan strukturlaşdırılmış müsahibə. Uşağın inkişaf tarixçəsini və cari davranışını dərindən araşdırır.", "ru": "Структурированное интервью с родителем/опекуном. Глубоко исследует историю развития и текущее поведение ребёнка.", "en": "A structured interview with the parent/caregiver. Explores the child's developmental history and current behavior in depth."}, "advantages": [{"az": "Dərin inkişaf tarixçəsi verir", "ru": "Даёт глубокую историю развития", "en": "Provides a deep developmental history"}, {"az": "ADOS-2 müşahidəsini güclü tamamlayır", "ru": "Хорошо дополняет наблюдение ADOS-2", "en": "Strongly complements ADOS-2 observation"}, {"az": "Erkən əlamətlərin vaxtını dəqiqləşdirir", "ru": "Уточняет время появления ранних признаков", "en": "Clarifies the timing of early signs"}, {"az": "Ailə kontekstini nəzərə alır", "ru": "Учитывает семейный контекст", "en": "Takes family context into account"}], "instruction": {"howto": [{"az": "Uşağı yaxşı tanıyan valideyn/qəyyumla aparın.", "ru": "Проводите с родителем/опекуном, хорошо знающим ребёнка.", "en": "Conduct with a parent/caregiver who knows the child well."}, {"az": "Həm keçmiş (4–5 yaş), həm cari davranışı soruşun.", "ru": "Спрашивайте и о прошлом (4–5 лет), и о текущем поведении.", "en": "Ask about both the past (ages 4–5) and current behavior."}, {"az": "Konkret nümunələr və tezlik üzərində dayanın.", "ru": "Сосредоточьтесь на конкретных примерах и частоте.", "en": "Focus on concrete examples and frequency."}], "methods": [{"az": "Yarımstrukturlaşdırılmış müsahibə", "ru": "Полуструктурированное интервью", "en": "Semi-structured interview"}, {"az": "Davranış nümunələrinin toplanması", "ru": "Сбор примеров поведения", "en": "Collection of behavior examples"}], "scoring": [{"az": "Cavablar üç sahə üzrə kodlanır və alqoritmə yığılır.", "ru": "Ответы кодируются по трём областям и сводятся в алгоритм.", "en": "Responses are coded across three domains and combined into an algorithm."}, {"az": "Kəsim balları yalnız rəsmi protokol üzrə tətbiq olunur.", "ru": "Пороговые баллы применяются только по официальному протоколу.", "en": "Cutoff scores apply only per the official protocol."}]}, "official": [{"label": {"az": "Sosial təsir sahəsi balı", "ru": "Балл области соц. взаимодействия", "en": "Social interaction domain score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}, {"label": {"az": "Ünsiyyət sahəsi balı", "ru": "Балл области коммуникации", "en": "Communication domain score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}, {"label": {"az": "Təkrarlanan davranış balı", "ru": "Балл повторяющегося поведения", "en": "Repetitive behavior score"}, "hint": {"az": "rəsmi alqoritmdən", "ru": "из официального алгоритма", "en": "from official algorithm"}}], "domains": [{"id": "d1", "title": {"az": "Erkən inkişaf və mərhələlər", "ru": "Раннее развитие и вехи", "en": "Early Development and Milestones"}, "task": {"az": "Valideynə sual: uşaq neçə aylıqda oturdu, yeridi? İlk narahatlığı nə vaxt və nədən hiss etdiniz?", "ru": "Вопрос родителю: в каком возрасте ребёнок начал сидеть, ходить? Когда и по какому поводу вы впервые почувствовали беспокойство?", "en": "Question to the parent: at what age did the child sit and walk? When, and about what, did you first feel concerned?"}, "items": [{"id": "d1i1", "t": {"az": "Əsas inkişaf mərhələləri (oturma, yeriş) yaşa görə gecikib", "ru": "Основные вехи развития (сидение, ходьба) наступили позже возрастной нормы", "en": "Key developmental milestones (sitting, walking) were delayed for age"}}, {"id": "d1i2", "t": {"az": "Körpəlikdə sosial maraq və cavab (gülümsəmə, baxış) zəif olub", "ru": "В младенчестве социальный интерес и отклик (улыбка, взгляд) были слабыми", "en": "In infancy, social interest and responsiveness (smiling, gaze) were weak"}}, {"id": "d1i3", "t": {"az": "Valideyn ilk dəfə nə vaxtsa inkişafla bağlı narahatlıq hiss edib", "ru": "Родитель в какой-то момент почувствовал беспокойство по поводу развития", "en": "The parent at some point felt concerned about the child's development"}}], "mean": {"az": "ilk illərdə inkişaf mərhələləri", "ru": "этапы развития в первые годы жизни", "en": "developmental milestones in the early years"}, "means": {"az": "Oturma və yeriş kimi ilk mərhələlər uşağın ümumi inkişaf gedişini göstərir. Valideynin yadda qalan məlumatı vacib başlanğıc nöqtəsidir.", "ru": "Ранние этапы, такие как сидение и ходьба, показывают общий ход развития ребёнка. Информация, которую помнит родитель, — важная отправная точка.", "en": "Early milestones such as sitting and walking show the child's overall course of development. What the parent remembers is an important starting point."}, "looks": {"az": "Valideyn oturma, yeriş və ya ilk narahatlıq anının uşaq yaşıdlarından fərqləndiyini xatırlaya bilər.", "ru": "Родитель может вспомнить, что сидение, ходьба или первые поводы для беспокойства отличались от сверстников.", "en": "The parent may recall that sitting, walking or the first moment of concern differed from peers."}, "support": {"az": "Uşaq həkiminin qeydlərini, şəkil və videoları toplayın; tarixləri yaxın aylarla qeyd edin.", "ru": "Соберите записи педиатра, фотографии и видео; отметьте даты с точностью до ближайших месяцев.", "en": "Gather the pediatrician's notes, photos and videos; record dates to the nearest month."}}, {"id": "d2", "title": {"az": "Dilin yaranması və itkisi", "ru": "Появление и утрата речи", "en": "Language Onset and Loss"}, "task": {"az": "Valideynə sual: ilk söz və ilk cümləni nə vaxt dedi? Əvvəl danışdığı sözləri sonra tərk etdimi?", "ru": "Вопрос родителю: когда ребёнок произнёс первое слово и первую фразу? Переставал ли он говорить слова, которые произносил раньше?", "en": "Question to the parent: when did the child say the first word and the first sentence? Did the child stop using words he or she used before?"}, "items": [{"id": "d2i1", "t": {"az": "İlk sözlər və cümlələr yaşa görə gec yaranıb", "ru": "Первые слова и фразы появились позже возрастной нормы", "en": "First words and phrases appeared later than expected for age"}}, {"id": "d2i2", "t": {"az": "Əvvəl qazanılmış nitq və ya bacarıq sonradan itib", "ru": "Ранее приобретённая речь или навык впоследствии были утрачены", "en": "Previously acquired speech or skills were later lost"}}, {"id": "d2i3", "t": {"az": "Dil inkişafında dayanma və ya geriləmə dövrü olub", "ru": "Был период остановки или регресса в развитии речи", "en": "There was a period of plateau or regression in language development"}}], "mean": {"az": "nitqin başlaması, ləngiməsi və ya itməsi", "ru": "начало, задержка или утрата речи", "en": "onset, delay or loss of speech"}, "means": {"az": "Nitqin nə vaxt başlaması və ya dəyişməsi gələcək ünsiyyət inkişafı üçün əhəmiyyətlidir. Tarixçə mütəxəssisə dəstək planı qurmağa kömək edir.", "ru": "Время начала или изменения речи важно для дальнейшего развития общения. История помогает специалисту выстроить план поддержки.", "en": "When speech begins or changes is important for later communication development. The history helps the specialist plan support."}, "looks": {"az": "Valideyn ilk sözlərin gec gəldiyini və ya əvvəl deyilən sözlərin sonradan azaldığını görmüş ola bilər.", "ru": "Родитель мог заметить, что первые слова появились поздно или что ранее произносимые слова позже стали встречаться реже.", "en": "The parent may have noticed that first words came late or that words said earlier became less frequent later."}, "support": {"az": "Uşağın dediyi sözləri gündəlik rutinlərdə (yemək, çimmə) təkrarlayın və yeni söz əlavə edin; şəkil kartları ilə dəstəkləyin.", "ru": "Повторяйте слова ребёнка в повседневных ситуациях (еда, купание) и добавляйте новое слово; поддерживайте карточками с картинками.", "en": "Repeat the words the child says during daily routines (meals, bath) and add a new word; support with picture cards."}}, {"id": "d3", "title": {"az": "Reseptiv dil", "ru": "Импрессивная речь", "en": "Receptive Language"}, "task": {"az": "Valideynə sual: sadə göstərişləri («gətir», «otur») başa düşür? Adını çağıranda dönür?", "ru": "Вопрос родителю: понимает ли ребёнок простые просьбы («принеси», «садись»)? Оборачивается ли, когда его зовут по имени?", "en": "Question to the parent: does the child understand simple instructions (\"bring it\", \"sit down\")? Does the child turn when called by name?"}, "items": [{"id": "d3i1", "t": {"az": "Sadə göstəriş və əşya adlarını başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием простых инструкций и названий предметов", "en": "Has difficulty understanding simple instructions and object names"}}, {"id": "d3i2", "t": {"az": "Adı çağırılanda cavab verməyib və ya gec cavab verib", "ru": "Не откликался или откликался с задержкой, когда его звали по имени", "en": "Did not respond, or responded late, when called by name"}}, {"id": "d3i3", "t": {"az": "Bir neçə addımlı şifahi göstərişi izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с выполнением многошаговых устных инструкций", "en": "Has difficulty following multi-step verbal instructions"}}], "mean": {"az": "başqasının nitqini anlamaq", "ru": "понимание речи других людей", "en": "understanding other people's speech"}, "means": {"az": "Başqasının nitqini anlamaq öyrənməyin və gündəlik həyatın əsasıdır. Anlama çətinliyi davranışda da özünü göstərə bilər.", "ru": "Понимание речи других — основа обучения и повседневной жизни. Трудности понимания могут проявляться и в поведении.", "en": "Understanding other people's speech is the basis of learning and daily life. Difficulty understanding can also show up in behavior."}, "looks": {"az": "Valideyn uşağın adını çağıranda dönmədiyini, sadə göstərişləri izləmədiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок не оборачивается на своё имя и не выполняет простые указания.", "en": "The parent may notice that the child does not turn when called by name and does not follow simple directions."}, "support": {"az": "Göstərişi qısa verin və jestlə dəstəkləyin («ver» deyib əlinizi açın); sevdiyi əşyaların adını təkrar edin.", "ru": "Давайте указания коротко и подкрепляйте жестом (скажите «дай» и откройте ладонь); повторяйте названия любимых предметов.", "en": "Give directions briefly and support them with a gesture (say \"give\" and open your hand); repeat the names of favorite objects."}}, {"id": "d4", "title": {"az": "Ekspressiv dil və söhbət", "ru": "Экспрессивная речь и беседа", "en": "Expressive Language and Conversation"}, "task": {"az": "Valideynə sual: istəyini sözlə necə bildirir? Sizinlə qarşılıqlı söhbət edə bilir?", "ru": "Вопрос родителю: как ребёнок выражает желания словами? Может ли он вести с вами диалог?", "en": "Question to the parent: how does the child express wishes in words? Can the child carry on a back-and-forth conversation with you?"}, "items": [{"id": "d4i1", "t": {"az": "İstəklərini sözlə ifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выражением желаний словами", "en": "Has difficulty expressing wishes in words"}}, {"id": "d4i2", "t": {"az": "Qarşılıqlı söhbəti davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с поддержанием диалога", "en": "Has difficulty sustaining a reciprocal conversation"}}, {"id": "d4i3", "t": {"az": "Dildən sosial məqsədlə (salamlaşma, soruşma) istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием речи в социальных целях (приветствие, вопросы)", "en": "Has difficulty using language for social purposes (greeting, asking questions)"}}], "mean": {"az": "öz fikrini ifadə etmək və söhbət aparmaq", "ru": "выражение своих мыслей и ведение беседы", "en": "expressing ideas and holding a conversation"}, "means": {"az": "Fikrini ifadə etmək və söhbət etmək uşağa istəyini bildirmək və münasibət qurmaq imkanı verir.", "ru": "Выражение мыслей и беседа дают ребёнку возможность сообщить о своих желаниях и выстраивать отношения.", "en": "Expressing ideas and conversing give the child the chance to communicate wishes and build relationships."}, "looks": {"az": "Valideyn uşağın istəyini söz əvəzinə ağlamaqla, çəkməklə və ya yalnız qısa sözlərlə bildirdiyini görə bilər.", "ru": "Родитель может замечать, что вместо слов ребёнок выражает желание плачем, тягой или только короткими словами.", "en": "The parent may notice that instead of words the child expresses wishes by crying, pulling or using only short words."}, "support": {"az": "Seçim verin («su, yoxsa şirə?»), uşağın cavabını gözləyin və hər cəhdə sevinclə cavab verin.", "ru": "Предлагайте выбор («вода или сок?»), ждите ответа ребёнка и радостно реагируйте на каждую попытку.", "en": "Offer a choice (\"water or juice?\"), wait for the child's answer and respond warmly to every attempt."}}, {"id": "d5", "title": {"az": "Stereotip və təkrarlanan nitq", "ru": "Стереотипная и повторяющаяся речь", "en": "Stereotyped and Repetitive Speech"}, "task": {"az": "Valideynə sual: eşitdiyi sözləri və ya çizgi filmindən cümlələri təkrar edir? «Mən» və «sən» sözlərini qarışdırır?", "ru": "Вопрос родителю: повторяет ли ребёнок услышанные слова или фразы из мультфильма? Путает ли «я» и «ты»?", "en": "Question to the parent: does the child repeat words heard, or sentences from cartoons? Does the child confuse \"I\" and \"you\"?"}, "items": [{"id": "d5i1", "t": {"az": "Eşitdiyi sözləri dərhal və ya sonradan təkrar edir (exolaliya)", "ru": "Повторяет услышанные слова сразу или спустя время (эхолалия)", "en": "Repeats words heard, immediately or later (echolalia)"}}, {"id": "d5i2", "t": {"az": "Eyni qəlibləşmiş cümlələri dəfələrlə işlədir", "ru": "Многократно использует одни и те же шаблонные фразы", "en": "Repeatedly uses the same stereotyped phrases"}}, {"id": "d5i3", "t": {"az": "«Mən» və «sən» əvəzliklərini qarışdırır", "ru": "Путает местоимения «я» и «ты»", "en": "Reverses the pronouns \"I\" and \"you\""}}], "mean": {"az": "eyni söz və cümlələri təkrar demək", "ru": "повторение одних и тех же слов и фраз", "en": "repeating the same words and phrases"}, "means": {"az": "Eyni söz və cümlələrin təkrarı nitqin inkişafının bir mərhələsi ola bilər. Mütəxəssis bu təkrarların məqsədini anlamağa çalışır.", "ru": "Повторение одних и тех же слов и фраз может быть одним из этапов речевого развития. Специалист стремится понять цель этих повторов.", "en": "Repeating the same words and phrases can be one stage of language development. The specialist tries to understand the purpose of these repetitions."}, "looks": {"az": "Valideyn uşağın çizgi filmindən cümlələri və ya eşitdiyi sözləri dəfələrlə təkrarladığını görə bilər.", "ru": "Родитель может замечать, что ребёнок многократно повторяет фразы из мультфильма или услышанные слова.", "en": "The parent may notice that the child repeats lines from a cartoon or words heard many times."}, "support": {"az": "Təkrar edilən cümləni vəziyyətə bağlayın və yanına yeni söz əlavə edin; birgə oxumada qısa cümlələrdən istifadə edin.", "ru": "Свяжите повторяемую фразу с ситуацией и добавьте к ней новое слово; при совместном чтении используйте короткие фразы.", "en": "Link the repeated phrase to the situation and add a new word beside it; use short sentences during shared reading."}}, {"id": "d6", "title": {"az": "Qeyri-verbal ünsiyyət (tarixçə)", "ru": "Невербальное общение (анамнез)", "en": "Nonverbal Communication (history)"}, "task": {"az": "Valideynə sual: kiçik yaşda barmağı ilə göstərirdi? Baş yelləmə kimi jestlərdən istifadə edirdi?", "ru": "Вопрос родителю: показывал ли ребёнок пальцем в раннем возрасте? Использовал ли жесты, например кивок?", "en": "Question to the parent: did the child point at an early age? Did the child use gestures such as nodding?"}, "items": [{"id": "d6i1", "t": {"az": "Jest və mimikadan ünsiyyətdə istifadə etməkdə çətinlik çəkib", "ru": "Испытывал трудности с использованием жестов и мимики для общения", "en": "Had difficulty using gestures and facial expression to communicate"}}, {"id": "d6i2", "t": {"az": "Barmaqla göstərmə və baş yelləmə kimi işarələr zəif olub", "ru": "Указательный жест и кивок были выражены слабо", "en": "Pointing and nodding were weak"}}, {"id": "d6i3", "t": {"az": "Bədən dilini sosial məqsədlə istifadə etməkdə çətinlik çəkib", "ru": "Испытывал трудности с использованием языка тела в социальных целях", "en": "Had difficulty using body language for social purposes"}}], "mean": {"az": "jest və mimika ilə ünsiyyətin keçmişi", "ru": "история использования жестов и мимики", "en": "history of using gestures and facial expressions"}, "means": {"az": "Jest və mimika sözdən əvvəl ünsiyyətin əsas vasitələridir. Kiçik yaşdakı tarixçə inkişaf yolunu anlamağa kömək edir.", "ru": "Жесты и мимика — основные средства общения до появления слов. История раннего возраста помогает понять путь развития.", "en": "Gestures and facial expressions are the main means of communication before words. The history from early childhood helps clarify the developmental path."}, "looks": {"az": "Valideyn uşağın kiçik yaşda barmaqla göstərmədiyini, baş yelləmə kimi jestləri az işlətdiyini xatırlaya bilər.", "ru": "Родитель может вспомнить, что в раннем возрасте ребёнок не показывал пальцем и мало пользовался жестами, например кивком.", "en": "The parent may recall that at an early age the child did not point and used gestures such as nodding little."}, "support": {"az": "Gündəlik rutinlərdə sadə jestləri nümunə göstərin («bax», «ver», «bəli»), uşağın hər jestinə cavab verin.", "ru": "Показывайте простые жесты в повседневных ситуациях («смотри», «дай», «да»), отвечайте на каждый жест ребёнка.", "en": "Model simple gestures in daily routines (\"look\", \"give\", \"yes\") and respond to each of the child's gestures."}}, {"id": "d7", "title": {"az": "Göz təması və sosial təbəssüm", "ru": "Зрительный контакт и социальная улыбка", "en": "Eye Contact and Social Smile"}, "task": {"az": "Valideynə sual: körpəykən sizin üzünüzə baxıb gülümsəyirdi? İndi danışarkən sizə baxır?", "ru": "Вопрос родителю: в младенчестве ребёнок смотрел вам в лицо и улыбался? Смотрит ли он на вас, когда говорит?", "en": "Question to the parent: as an infant, did the child look at your face and smile? Does the child look at you when speaking?"}, "items": [{"id": "d7i1", "t": {"az": "Kiçik yaşda və ya indi göz təması zəif olub", "ru": "В раннем возрасте или сейчас зрительный контакт был слабым", "en": "Eye contact was poor in early childhood or is poor now"}}, {"id": "d7i2", "t": {"az": "Sosial təbəssüm gec yaranıb və ya az olub", "ru": "Социальная улыбка появилась поздно или проявлялась редко", "en": "Social smile appeared late or was infrequent"}}, {"id": "d7i3", "t": {"az": "Baxışı ünsiyyət məqsədilə istifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с использованием взгляда для общения", "en": "Has difficulty using gaze to communicate"}}], "mean": {"az": "insanla qarşılıqlı baxış və gülümsəmə", "ru": "взаимный взгляд и улыбка в общении с человеком", "en": "mutual gaze and smiling with another person"}, "means": {"az": "Baxış və təbəssüm insanlar arasında ilk əlaqəni yaradır. Bu, uşağın sosial maraqlarını göstərir.", "ru": "Взгляд и улыбка создают первую связь между людьми. Они отражают социальный интерес ребёнка.", "en": "Gaze and smiling create the first connection between people. They reflect the child's social interest."}, "looks": {"az": "Valideyn uşağın körpəlikdə və ya indi sizin üzünüzə az baxdığını, gülümsəməyə az cavab verdiyini görə bilər.", "ru": "Родитель может замечать, что в младенчестве или сейчас ребёнок мало смотрит вам в лицо и слабо отвечает на улыбку.", "en": "The parent may notice that in infancy or now the child looks little at your face and responds little to smiles."}, "support": {"az": "Üz-üzə, uşağın göz səviyyəsində oynayın; gülüşmə və kuku-oyunlarını təkrarlayın.", "ru": "Играйте лицом к лицу, на уровне глаз ребёнка; повторяйте игры со смехом и «ку-ку».", "en": "Play face to face at the child's eye level; repeat laughing games and peekaboo."}}, {"id": "d8", "title": {"az": "Yaşıdlarla münasibətlər", "ru": "Отношения со сверстниками", "en": "Peer Relationships"}, "task": {"az": "Valideynə sual: həyətdə, bağçada və ya məktəbdə uşaqlarla necə oynayır? Dostu var?", "ru": "Вопрос родителю: как ребёнок играет с детьми во дворе, в саду или в школе? Есть ли у него друг?", "en": "Question to the parent: how does the child play with other children in the yard, at kindergarten, or at school? Does the child have a friend?"}, "items": [{"id": "d8i1", "t": {"az": "Yaşıdları ilə oyun və dostluq qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с игрой и дружбой со сверстниками", "en": "Has difficulty playing and forming friendships with peers"}}, {"id": "d8i2", "t": {"az": "Qrup oyununda iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в групповой игре", "en": "Has difficulty taking part in group play"}}, {"id": "d8i3", "t": {"az": "Yaşıdlara maraq göstərmir və ya təkbaşına oynamağı üstün tutur", "ru": "Не проявляет интереса к сверстникам или предпочитает играть один", "en": "Shows no interest in peers or prefers to play alone"}}], "mean": {"az": "yaşıdlarla əlaqə və dostluq", "ru": "отношения со сверстниками и дружба", "en": "relationships with peers and friendship"}, "means": {"az": "Yaşıdlarla münasibət uşağın sosial inkişafı üçün vacibdir. Birgə oyun və dostluq təcrübə qazandırır.", "ru": "Отношения со сверстниками важны для социального развития ребёнка. Совместная игра и дружба дают опыт.", "en": "Relationships with peers are important for the child's social development. Joint play and friendship provide experience."}, "looks": {"az": "Valideyn uşağın həyətdə, bağçada və ya məktəbdə digər uşaqlarla az oynadığını, tək qaldığını görə bilər.", "ru": "Родитель может замечать, что ребёнок мало играет с другими детьми во дворе, в саду или в школе и остаётся один.", "en": "The parent may notice that the child plays little with other children in the yard, kindergarten or school and stays alone."}, "support": {"az": "Kiçik qrupda (bir-iki uşaq) sadə oyunlar qurun, qaydaları əvvəlcədən şəkillərlə izah edin.", "ru": "Организуйте простые игры в малой группе (один-два ребёнка), заранее объясняйте правила с помощью картинок.", "en": "Set up simple games in a small group (one or two children) and explain the rules in advance with pictures."}}, {"id": "d9", "title": {"az": "Sevinc və maraqların paylaşılması", "ru": "Разделение радости и интересов", "en": "Sharing Enjoyment and Interests"}, "task": {"az": "Valideynə sual: sevdiyi şeyi sizə göstərir? Uğur qazananda sizə baxıb sevinir?", "ru": "Вопрос родителю: показывает ли ребёнок вам то, что любит? Радуется ли, глядя на вас, когда у него что-то получается?", "en": "Question to the parent: does the child show you things he or she likes? When successful, does the child look at you and share the joy?"}, "items": [{"id": "d9i1", "t": {"az": "Maraqlı şeyləri başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы делиться интересным с другими", "en": "Has difficulty sharing interesting things with others"}}, {"id": "d9i2", "t": {"az": "Sevincini valideyni ilə paylaşmaqda çətinlik çəkir", "ru": "Испытывает трудности с разделением радости с родителем", "en": "Has difficulty sharing enjoyment with the parent"}}, {"id": "d9i3", "t": {"az": "Nailiyyətini göstərmək istəmir", "ru": "Не стремится показывать свои достижения", "en": "Does not seek to show his or her achievements"}}], "mean": {"az": "nəyi sevdiyini başqasına göstərmək", "ru": "показывание другому того, что нравится", "en": "showing others what he or she likes"}, "means": {"az": "Sevdiyi şeyi başqasına göstərmək uşağın paylaşmaq və əlaqə qurmaq istəyini göstərir.", "ru": "Показывать другому то, что нравится, отражает стремление ребёнка делиться и устанавливать контакт.", "en": "Showing others what one likes reflects the child's wish to share and connect."}, "looks": {"az": "Valideyn uşağın maraqlı şeyi və ya uğurunu özünə göstərmədiyini, yalnız tək baxdığını görə bilər.", "ru": "Родитель может замечать, что ребёнок не показывает ему интересные вещи или свои успехи и рассматривает их один.", "en": "The parent may notice that the child does not show interesting things or achievements and looks at them alone."}, "support": {"az": "Uşağın gətirdiyi hər şeyə maraq göstərin, ona ad verin və birgə baxın.", "ru": "Проявляйте интерес ко всему, что приносит ребёнок, называйте это и рассматривайте вместе.", "en": "Show interest in everything the child brings, name it and look at it together."}}, {"id": "d10", "title": {"az": "Emosional qarşılıqlılıq", "ru": "Эмоциональная взаимность", "en": "Emotional Reciprocity"}, "task": {"az": "Valideynə sual: ağlayanda və ya bərk narahat olanda uşaq necə reaksiya verir? Özü sizdən təsəlli axtarır?", "ru": "Вопрос родителю: как ребёнок реагирует, когда вы плачете или сильно расстроены? Ищет ли он утешения сам?", "en": "Question to the parent: how does the child react when you cry or are very upset? Does the child seek comfort on his or her own?"}, "items": [{"id": "d10i1", "t": {"az": "Başqasının hissinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на чувства другого человека", "en": "Has difficulty responding appropriately to another person's feelings"}}, {"id": "d10i2", "t": {"az": "Təsəlli axtarmaqda və ya təklif etməkdə çətinlik çəkir", "ru": "Испытывает трудности с поиском утешения или попытками утешить", "en": "Has difficulty seeking or offering comfort"}}, {"id": "d10i3", "t": {"az": "Hissi qarşılıqlı bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с взаимным разделением чувств", "en": "Has difficulty sharing feelings reciprocally"}}], "mean": {"az": "başqasının hissinə cavab vermək", "ru": "реакция на чувства другого человека", "en": "responding to another person's feelings"}, "means": {"az": "Başqasının hissinə cavab vermək empatiya və yaxın münasibətin əsasıdır. Uşaq bu bacarığı tədricən öyrənir.", "ru": "Реакция на чувства другого — основа эмпатии и близких отношений. Ребёнок осваивает это умение постепенно.", "en": "Responding to another person's feelings is the basis of empathy and close relationships. The child learns this skill gradually."}, "looks": {"az": "Valideyn kimsə ağlayanda və ya narahat olanda uşağın az reaksiya verdiyini ya da qeyri-adi reaksiya göstərdiyini görə bilər.", "ru": "Родитель может замечать, что когда кто-то плачет или расстроен, ребёнок мало реагирует или реагирует необычно.", "en": "The parent may notice that when someone cries or is upset, the child shows little reaction or an unusual one."}, "support": {"az": "Hissləri adlandırın («ağlayır, kədərlidir»), şəkil kartları və kukla ilə hissləri nümayiş etdirin.", "ru": "Называйте чувства («плачет, ему грустно»), показывайте чувства с помощью карточек с картинками и кукол.", "en": "Name feelings (\"he is crying, he is sad\") and demonstrate feelings with picture cards and dolls."}}, {"id": "d11", "title": {"az": "Təxəyyül və rol oyunu (tarixçə)", "ru": "Воображение и ролевая игра (анамнез)", "en": "Imagination and Role Play (history)"}, "task": {"az": "Valideynə sual: kiçikliyində oyuncaqla «yemək yedirmək», «çay içmək» kimi uydurma oyun oynayırdı?", "ru": "Вопрос родителю: играл ли ребёнок в раннем возрасте в воображаемые игры, например «кормить» игрушку или «пить чай»?", "en": "Question to the parent: in early childhood, did the child engage in pretend play, such as \"feeding\" a toy or \"having tea\"?"}, "items": [{"id": "d11i1", "t": {"az": "Uydurma oyun yaşa görə gec yaranıb və ya heç yaranmayıb", "ru": "Воображаемая игра появилась позже возрастной нормы или не появилась вовсе", "en": "Pretend play appeared later than expected for age or did not appear at all"}}, {"id": "d11i2", "t": {"az": "Rol və süjetli oyunda çətinlik çəkib", "ru": "Испытывал трудности с ролевой и сюжетной игрой", "en": "Had difficulty with role play and storyline play"}}, {"id": "d11i3", "t": {"az": "Oyunda çeviklik və yaradıcılıq zəif olub", "ru": "В игре было мало гибкости и творчества", "en": "Play showed little flexibility and creativity"}}], "mean": {"az": "rollu və təsəvvür oyunlarının keçmişi", "ru": "история ролевых игр и игр воображения", "en": "history of role play and pretend play"}, "means": {"az": "Təxəyyül oyunu uşağın dünyanı anlamasını və yaradıcı düşüncəsini göstərir. Kiçik yaşda necə oynadığı vacib məlumatdır.", "ru": "Игра воображения отражает понимание ребёнком мира и творческое мышление. Важно, как ребёнок играл в раннем возрасте.", "en": "Imaginative play reflects the child's understanding of the world and creative thinking. How the child played at an early age is important information."}, "looks": {"az": "Valideyn uşağın kiçik yaşda oyuncaqla «yemək yedirmə» kimi uydurma oyunlar oynamadığını xatırlaya bilər.", "ru": "Родитель может вспомнить, что в раннем возрасте ребёнок не играл в условные игры, например «кормил» игрушку.", "en": "The parent may recall that at an early age the child did not play pretend games such as \"feeding\" a toy."}, "support": {"az": "Oyuncaq qab-qacaq, kukla və maşınla sadə hərəkətləri birlikdə göstərin, sonra uşağa təqlid imkanı verin.", "ru": "Вместе показывайте простые действия с игрушечной посудой, куклой и машинкой, затем дайте ребёнку возможность подражать.", "en": "Show simple actions together with toy dishes, a doll and a car, then give the child a chance to imitate."}}, {"id": "d12", "title": {"az": "Məhdud, dar maraqlar", "ru": "Ограниченные узкие интересы", "en": "Restricted, Narrow Interests"}, "task": {"az": "Valideynə sual: uşağın xüsusi maraq sahəsi var (məsələn, yalnız qatarlar)? Nə qədər vaxt ayırır?", "ru": "Вопрос родителю: есть ли у ребёнка особая область интересов (например, только поезда)? Сколько времени он ей уделяет?", "en": "Question to the parent: does the child have a special area of interest (for example, only trains)? How much time does he or she devote to it?"}, "items": [{"id": "d12i1", "t": {"az": "Qeyri-adi və ya çox dar maraq sahəsi var", "ru": "Имеет необычную или очень узкую область интересов", "en": "Has an unusual or very narrow area of interest"}}, {"id": "d12i2", "t": {"az": "Bu maraqla həddindən artıq məşğul olur", "ru": "Чрезмерно занят этим интересом", "en": "Is excessively preoccupied with this interest"}}, {"id": "d12i3", "t": {"az": "Maraq gündəlik həyata mane olur", "ru": "Интерес мешает повседневной жизни", "en": "The interest interferes with daily life"}}], "mean": {"az": "bir mövzuya həddindən artıq bağlılıq", "ru": "чрезмерная привязанность к одной теме", "en": "excessive attachment to a single topic"}, "means": {"az": "Bir mövzuya çox bağlılıq uşağın diqqətini və gündəlik fəaliyyətini məhdudlaşdıra bilər. Mütəxəssis bu marağın yer və vaxtını öyrənir.", "ru": "Чрезмерная привязанность к одной теме может ограничивать внимание и повседневную деятельность ребёнка. Специалист выясняет, где и когда проявляется этот интерес.", "en": "Excessive attachment to one topic can limit the child's attention and daily activities. The specialist explores where and when this interest occurs."}, "looks": {"az": "Valideyn uşağın bütün gününü bir mövzuya (qatar, rəqəm) həsr etdiyini və başqa fəaliyyətə keçməkdə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок посвящает весь день одной теме (поезда, цифры) и с трудом переключается на другое.", "en": "The parent may notice that the child devotes the whole day to one topic (trains, numbers) and has difficulty switching to other activities."}, "support": {"az": "Marağı sevindirici fəaliyyət kimi qəbul edin, onun üzərində yeni oyun qurun və vaxt limitini vizual saatla göstərin.", "ru": "Воспринимайте интерес как приятное занятие, стройте на нём новые игры и показывайте ограничение по времени на наглядных часах.", "en": "Treat the interest as an enjoyable activity, build new games around it and show the time limit with a visual clock."}}, {"id": "d13", "title": {"az": "Rituallar və gündəlik qaydalar", "ru": "Ритуалы и бытовые правила", "en": "Rituals and Routines"}, "task": {"az": "Valideynə sual: hər gün eyni qaydada etməli olduğu şeylər var? Dəyişiklik olanda nə baş verir?", "ru": "Вопрос родителю: есть ли действия, которые ребёнок должен каждый день выполнять в одном и том же порядке? Что происходит при изменении?", "en": "Question to the parent: are there things the child must do in the same way every day? What happens when something changes?"}, "items": [{"id": "d13i1", "t": {"az": "Müəyyən ritualları mütləq yerinə yetirməyə ehtiyac duyur", "ru": "Испытывает потребность обязательно выполнять определённые ритуалы", "en": "Feels a need to carry out certain rituals without fail"}}, {"id": "d13i2", "t": {"az": "Gündəlik qaydanın pozulmasına güclü narahatlıq göstərir", "ru": "Выраженно тревожится при нарушении привычного порядка", "en": "Shows marked distress when the daily routine is disrupted"}}, {"id": "d13i3", "t": {"az": "Eyniliyə güclü tələbat var", "ru": "Сильная потребность в неизменности", "en": "Has a strong need for sameness"}}], "mean": {"az": "eyni qaydanın pozulmasına dözməmək", "ru": "непереносимость нарушения привычного порядка", "en": "difficulty tolerating changes to a usual routine"}, "means": {"az": "Eyni qaydanın pozulmasına dözmək gündəlik rutin dəyişikliklərinə uyğunlaşmaq üçün lazımdır.", "ru": "Способность переносить нарушение привычного порядка необходима для адаптации к изменениям в повседневном распорядке.", "en": "Tolerating changes to a usual routine is needed to adapt to changes in the daily schedule."}, "looks": {"az": "Valideyn gündəlik qaydanın (marşrut, yemək ardıcıllığı) dəyişəndə uşağın çox narahat olduğunu görə bilər.", "ru": "Родитель может замечать, что при изменении привычного порядка (маршрут, последовательность в еде) ребёнок очень тревожится.", "en": "The parent may notice that when the usual order changes (route, order of meals) the child becomes very distressed."}, "support": {"az": "Gündəlik cədvəli şəkillərlə göstərin, dəyişiklikləri əvvəlcədən xəbərdar edin və kiçik fərqlərə tədricən alışdırın.", "ru": "Показывайте распорядок дня в картинках, заранее предупреждайте об изменениях и постепенно приучайте к небольшим отличиям.", "en": "Show the daily schedule with pictures, warn about changes in advance and gradually accustom the child to small differences."}}, {"id": "d14", "title": {"az": "Motor manerizmlər və sensor", "ru": "Моторные манеризмы и сенсорные особенности", "en": "Motor Mannerisms and Sensory Features"}, "task": {"az": "Valideynə sual: əl-barmaq hərəkətləri, yırğalanma var? Səs, toxunuş və qoxuya qeyri-adi reaksiyası var? Əlamətlər neçə yaşından başlayıb?", "ru": "Вопрос родителю: бывают ли движения рук и пальцев, раскачивание? Необычно ли ребёнок реагирует на звуки, прикосновения, запахи? С какого возраста появились эти признаки?", "en": "Question to the parent: are there hand or finger movements or rocking? Does the child react unusually to sounds, touch, or smells? At what age did these signs begin?"}, "items": [{"id": "d14i1", "t": {"az": "Təkrarlanan motor hərəkətlər (əl çalma, yırğalanma) var", "ru": "Повторяющиеся двигательные действия (хлопанье руками, раскачивание)", "en": "Repetitive motor movements (hand flapping, rocking)"}}, {"id": "d14i2", "t": {"az": "Səs, toxunuş və ya qoxuya qeyri-adi reaksiya verir", "ru": "Необычно реагирует на звуки, прикосновения или запахи", "en": "Reacts unusually to sounds, touch, or smells"}}, {"id": "d14i3", "t": {"az": "Əlamətlər erkən yaşdan başlayıb və ya əvvəlki bacarıqlar geriləyib", "ru": "Признаки появились в раннем возрасте или ранее приобретённые навыки регрессировали", "en": "Signs began at an early age, or previously acquired skills regressed"}}], "mean": {"az": "təkrarlanan hərəkətlər və hissiyyat reaksiyaları", "ru": "повторяющиеся движения и сенсорные реакции", "en": "repetitive movements and sensory responses"}, "means": {"az": "Təkrarlanan hərəkətlər və hissiyyat reaksiyaları uşağın özünü tənzimləmə üsulu ola bilər. Mütəxəssis bunların gündəlik həyata təsirini öyrənir.", "ru": "Повторяющиеся движения и сенсорные реакции могут быть способом саморегуляции ребёнка. Специалист выясняет, как они влияют на повседневную жизнь.", "en": "Repetitive movements and sensory responses can be a way for the child to self-regulate. The specialist explores how they affect daily life."}, "looks": {"az": "Valideyn uşağın əl-barmaq hərəkətlərini, yırğalanmanı və ya səs, toxunuş, qoxuya qeyri-adi reaksiyasını görə bilər.", "ru": "Родитель может замечать у ребёнка движения рук и пальцев, раскачивание или необычную реакцию на звук, прикосновение, запах.", "en": "The parent may notice hand and finger movements, rocking, or unusual reactions to sound, touch or smell."}, "support": {"az": "Hərəkətlərin nə zaman artdığını qeyd edin, sensor ehtiyaclar üçün təhlükəsiz oyunlar (su, qum, top) verin.", "ru": "Отмечайте, когда движения усиливаются, предлагайте безопасные игры для сенсорных потребностей (вода, песок, мяч).", "en": "Note when the movements increase and offer safe games for sensory needs (water, sand, ball)."}}], "specialist": [{"az": "ADI-R tarixçəsini ADOS-2 birbaşa müşahidəsi ilə tutuşdurun.", "ru": "Сопоставьте историю ADI-R с прямым наблюдением ADOS-2.", "en": "Cross-check the ADI-R history against direct ADOS-2 observation."}, {"az": "Tarixçə ilə cari davranış arasında uyğunsuzluğu qeyd edin.", "ru": "Отметьте расхождения между историей и текущим поведением.", "en": "Note discrepancies between history and current behavior."}, {"az": "Tibbi və genetik amilləri istisna etmək üçün əlavə müayinə tövsiyə edin.", "ru": "Рекомендуйте доп. обследование для исключения медицинских и генетических факторов.", "en": "Recommend further evaluation to rule out medical and genetic factors."}], "parentIntro": {"az": "Bu müsahibə uşağınızın tarixçəsini anlamağa kömək edir. Cavablarınız nə qədər dəqiq olsa, dəstək bir o qədər uyğun olar.", "ru": "Это интервью помогает понять историю вашего ребёнка. Чем точнее ответы, тем точнее поддержка.", "en": "This interview helps understand your child's history. The more precise your answers, the more fitting the support."}, "parentTips": [{"az": "Uşağın kiçik yaş videolarına baxmaq xatırlamağa kömək edə bilər.", "ru": "Просмотр видео раннего возраста помогает вспомнить.", "en": "Watching early-age videos can help you remember."}, {"az": "Müsbət bacarıqları da qeyd edin — onlar dəstəyin əsasıdır.", "ru": "Отмечайте и сильные навыки — они основа поддержки.", "en": "Note strengths too — they are the basis of support."}, {"az": "Çətinlik gördüyünüz anları konkret nümunələrlə yazın.", "ru": "Записывайте трудные моменты конкретными примерами.", "en": "Write down difficult moments with concrete examples."}], "games": [{"az": "Birgə şəkil albomu: keçmiş anları danışaraq nitqi və yaddaşı dəstəkləyin.", "ru": "Совместный фотоальбом: проговаривая прошлое, поддерживайте речь и память.", "en": "Shared photo album: talk through past moments to support speech and memory."}, {"az": "Növbəli nağıl: bir cümləni siz, birini uşaq deyir.", "ru": "Сказка по очереди: одно предложение вы, одно ребёнок.", "en": "Turn-taking story: you say one sentence, the child the next."}]}, "wiscv": {"id": "wiscv", "name": "WISC-V", "full": {"az": "Wechsler Uşaqlar üçün İntellekt Şkalası, 5-ci nəşr", "ru": "Шкала интеллекта Векслера для детей, 5-е изд.", "en": "Wechsler Intelligence Scale for Children, 5th ed."}, "age": {"az": "6 yaş 0 ay – 16 yaş 11 ay", "ru": "6 лет 0 мес. – 16 лет 11 мес.", "en": "6 years 0 months – 16 years 11 months"}, "summary": {"az": "Koqnitiv qabiliyyətləri beş əsas indeks üzrə ölçən geniş istifadə olunan intellekt şkalası. Güclü və zəif tərəfləri profil şəklində göstərir.", "ru": "Широко используемая шкала интеллекта, измеряющая когнитивные способности по пяти основным индексам. Показывает профиль сильных и слабых сторон.", "en": "A widely used intelligence scale measuring cognitive ability across five primary indices. Shows a profile of strengths and weaknesses."}, "advantages": [{"az": "Beş ayrı koqnitiv indeks verir", "ru": "Даёт пять отдельных когнитивных индексов", "en": "Provides five distinct cognitive indices"}, {"az": "Öyrənmə çətinliklərinin profilini açır", "ru": "Раскрывает профиль трудностей обучения", "en": "Reveals the profile of learning difficulties"}, {"az": "Təhsil planlaması üçün dəyərli", "ru": "Ценна для планирования обучения", "en": "Valuable for educational planning"}, {"az": "Güclü tərəflərə əsaslanan dəstəyə imkan verir", "ru": "Позволяет опираться на сильные стороны", "en": "Enables strength-based support"}], "instruction": {"howto": [{"az": "Sakit, fasiləsiz mühitdə təkbətək keçirin.", "ru": "Проводите наедине, без перерывов, в тихой обстановке.", "en": "Administer one-on-one in a quiet, uninterrupted setting."}, {"az": "Standart ardıcıllıq və təlimatlara dəqiq əməl edin.", "ru": "Точно следуйте стандартному порядку и инструкциям.", "en": "Follow the standard order and instructions precisely."}, {"az": "Uşağın yorğunluğunu izləyin, lazımda fasilə verin.", "ru": "Следите за утомлением ребёнка, делайте перерывы.", "en": "Watch for fatigue; allow breaks as needed."}], "methods": [{"az": "Subtestlər üzrə birbaşa tapşırıqlar", "ru": "Прямые задания по субтестам", "en": "Direct subtest tasks"}, {"az": "Şifahi və performans tapşırıqlarının birləşməsi", "ru": "Сочетание вербальных и performance-заданий", "en": "A mix of verbal and performance tasks"}], "scoring": [{"az": "Xam ballar normalara görə standart ballara çevrilir.", "ru": "Сырые баллы переводятся в стандартные по нормам.", "en": "Raw scores convert to standard scores per norms."}, {"az": "İndeks və ümumi IQ yalnız rəsmi cədvəllərlə hesablanır.", "ru": "Индексы и общий IQ рассчитываются только по официальным таблицам.", "en": "Index and Full Scale IQ are computed only with official tables."}]}, "official": [{"label": {"az": "Şifahi Dərketmə (VCI)", "ru": "Вербальное понимание (VCI)", "en": "Verbal Comprehension (VCI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Vizual-Məkan (VSI)", "ru": "Зрительно-пространственный (VSI)", "en": "Visual Spatial (VSI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Məntiqi Mühakimə (FRI)", "ru": "Подвижный интеллект (FRI)", "en": "Fluid Reasoning (FRI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "İşlək Yaddaş (WMI)", "ru": "Рабочая память (WMI)", "en": "Working Memory (WMI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Emal Sürəti (PSI)", "ru": "Скорость обработки (PSI)", "en": "Processing Speed (PSI)"}, "hint": {"az": "indeks balı", "ru": "индексный балл", "en": "index score"}}, {"label": {"az": "Ümumi IQ (FSIQ)", "ru": "Общий IQ (FSIQ)", "en": "Full Scale IQ (FSIQ)"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Söz ehtiyatı (VCI)", "ru": "Словарный запас (VCI)", "en": "Vocabulary (VCI)"}, "task": {"az": "Mütəxəssis uşağa söz deyir, uşaq onun mənasını izah edir. Məsələn, «alma nədir?»", "ru": "Специалист называет слово, ребёнок объясняет его значение. Например: «Что такое яблоко?»", "en": "The examiner says a word and the child explains its meaning. For example, \"What is an apple?\""}, "items": [{"id": "d1i1", "t": {"az": "Sözün mənasını izah edərkən doğru sözləri tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с подбором нужных слов при объяснении значения", "en": "Has difficulty finding the right words when explaining a meaning"}}, {"id": "d1i2", "t": {"az": "İzahı çox qısa və ya qeyri-dəqiq olur (məsələn, yalnız «yeyirik»)", "ru": "Объяснение слишком краткое или неточное (например, только «едим»)", "en": "Gives explanations that are too brief or imprecise (for example, only \"we eat it\")"}}, {"id": "d1i3", "t": {"az": "Yaşına uyğun gündəlik sözlərin mənasını bilmir", "ru": "Не знает значения обычных слов, соответствующих возрасту", "en": "Does not know the meaning of everyday words appropriate for age"}}], "mean": {"az": "sözlərin mənasını bilmək və izah etmək", "ru": "знание и объяснение значений слов", "en": "knowing and explaining word meanings"}, "means": {"az": "Sözlərin mənasını bilmək və izah etmək. Dərsi anlamaq, sual vermək və fikri ifadə etmək üçün əsasdır.", "ru": "Знание и объяснение значений слов. Основа для понимания материала, постановки вопросов и выражения мыслей.", "en": "Knowing and explaining the meanings of words. Basis for understanding lessons, asking questions and expressing ideas."}, "looks": {"az": "Uşaq tanış sözləri izah edə bilmir, «bilmirəm» və ya bir sözlük cavab verir.", "ru": "Ребёнок не может объяснить знакомые слова, отвечает «не знаю» или одним словом.", "en": "The child cannot explain familiar words and answers \"I don't know\" or with a single word."}, "support": {"az": "Gündəlik əşyaları birlikdə təsvir edin, yeni sözü cümlədə işlədin.", "ru": "Описывайте вместе предметы повседневного обихода, употребляйте новое слово в предложении.", "en": "Describe everyday objects together and use the new word in a sentence."}}, {"id": "d2", "title": {"az": "Oxşarlıqlar (VCI)", "ru": "Сходства (VCI)", "en": "Similarities (VCI)"}, "task": {"az": "İki əşya deyilir (məsələn, alma və banan), uşaq onların nəyə görə oxşar olduğunu söyləyir.", "ru": "Называются два предмета (например, яблоко и банан), ребёнок говорит, чем они похожи.", "en": "Two items are named (for example, apple and banana) and the child says how they are alike."}, "items": [{"id": "d2i1", "t": {"az": "İki əşyanın ümumi qrupunu (məsələn, «meyvə») tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с определением общей категории двух предметов (например, «фрукты»)", "en": "Has difficulty identifying the shared category of two items (for example, \"fruit\")"}}, {"id": "d2i2", "t": {"az": "Ortaq cəhət əvəzinə fərqi deyir və ya yalnız bir əşyanı təsvir edir", "ru": "Называет различие вместо общего признака или описывает только один предмет", "en": "Names a difference instead of a shared feature, or describes only one item"}}, {"id": "d2i3", "t": {"az": "Cavabı ümumi anlayışla deyil, konkret xüsusiyyətlə verir («hər ikisi sarıdır»)", "ru": "Отвечает конкретным признаком, а не обобщающим понятием («оба жёлтые»)", "en": "Answers with a concrete feature rather than a general concept (\"both are yellow\")"}}], "mean": {"az": "iki əşya arasında ortaq cəhət tapmaq", "ru": "нахождение общего признака у двух предметов", "en": "finding what two things have in common"}, "means": {"az": "İki əşya və ya anlayış arasında ümumi cəhət tapmaq. Təsnif etmək və ümumiləşdirmək bacarığının əsasıdır.", "ru": "Нахождение общего признака у двух предметов или понятий. Основа умения классифицировать и обобщать.", "en": "Finding a common feature between two objects or concepts. Basis of the ability to classify and generalize."}, "looks": {"az": "Ümumi qrupu tapmır, yalnız fərqi və ya bir əşyanın xüsusiyyətini deyir.", "ru": "Не находит общую группу, называет только различие или одно свойство предмета.", "en": "The child does not find the shared category and names only a difference or a single property of one object."}, "support": {"az": "Əşyaları qruplara ayırma oyunları, «bunlar niyə eynidir?» sualı.", "ru": "Игры на сортировку предметов по группам, вопрос «почему они одинаковые?».", "en": "Sorting games that group objects, and the question \"why are these the same?\""}}, {"id": "d3", "title": {"az": "Anlama (VCI)", "ru": "Понимание (VCI)", "en": "Comprehension (VCI)"}, "task": {"az": "Gündəlik həyat və sosial qaydalarla bağlı suallar verilir. Məsələn, «niyə əlləri yuyuruq?»", "ru": "Задаются вопросы о повседневной жизни и социальных правилах. Например: «Почему мы моем руки?»", "en": "Questions are asked about everyday life and social rules. For example, \"Why do we wash our hands?\""}, "items": [{"id": "d3i1", "t": {"az": "Qaydanın və ya hərəkətin səbəbini izah etməkdə çətinlik çəkir", "ru": "Испытывает трудности с объяснением причины правила или действия", "en": "Has difficulty explaining the reason for a rule or an action"}}, {"id": "d3i2", "t": {"az": "Sosial vəziyyətə uyğun cavab tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с подбором ответа, соответствующего социальной ситуации", "en": "Has difficulty finding an answer that fits the social situation"}}, {"id": "d3i3", "t": {"az": "Cavabı çox qısa olur və ya mövzudan kənara çıxır", "ru": "Ответ слишком краткий или не относится к теме", "en": "Gives answers that are too brief or off topic"}}], "mean": {"az": "gündəlik qaydaların və vəziyyətlərin səbəbini başa düşmək", "ru": "понимание причин повседневных правил и ситуаций", "en": "understanding the reasons for everyday rules and situations"}, "means": {"az": "Gündəlik qaydaların və sosial vəziyyətlərin səbəbini başa düşmək.", "ru": "Понимание причин повседневных правил и социальных ситуаций.", "en": "Understanding the reasons behind everyday rules and social situations."}, "looks": {"az": "Qaydanın niyə olduğunu izah etmir, cavab qısa və ya mövzudan kənar olur.", "ru": "Не объясняет, почему существует правило; ответ короткий или не по теме.", "en": "The child does not explain why a rule exists; the answer is short or off topic."}, "support": {"az": "Gündəlik hadisələrdə «niyə belə edirik?» söhbəti, sosial vəziyyət şəkilləri.", "ru": "Беседы «почему мы так делаем?» на примерах из повседневной жизни, картинки социальных ситуаций.", "en": "Talk about \"why do we do it this way?\" in daily events, and use pictures of social situations."}}, {"id": "d4", "title": {"az": "Blok dizayn (VSI)", "ru": "Кубики Коса (VSI)", "en": "Block Design (VSI)"}, "task": {"az": "Uşaq kublardan rəsmdəki naxışı qurur. Vaxt məhduddur, sekundomer lazımdır.", "ru": "Ребёнок собирает из кубиков узор по рисунку. Время ограничено, нужен секундомер.", "en": "The child builds the pattern shown in the picture with blocks. The task is timed; a stopwatch is needed."}, "items": [{"id": "d4i1", "t": {"az": "Rəsmdəki naxışı kublarla düzgün qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с построением узора из кубиков по рисунку", "en": "Has difficulty building the pattern from the picture with blocks"}}, {"id": "d4i2", "t": {"az": "Kubun üzünü və ya yerini səhv seçir, səhvi düzəltməkdə çətinlik çəkir", "ru": "Выбирает не ту грань или не то место для кубика и с трудом исправляет ошибку", "en": "Chooses the wrong block face or position and has difficulty correcting the error"}}, {"id": "d4i3", "t": {"az": "Vaxt məhdudiyyətində tapşırığı bitirməkdə çətinlik çəkir", "ru": "Испытывает трудности с завершением задания в пределах времени", "en": "Has difficulty completing the task within the time limit"}}], "mean": {"az": "kublardan nümunəyə uyğun naxış qurmaq", "ru": "построение узора из кубиков по образцу", "en": "building a pattern from blocks to match a model"}, "means": {"az": "Rəsmə baxıb kublardan eyni naxışı qurmaq. Hissələri bütövə çevirmək, məkan təsəvvürü.", "ru": "Построение из кубиков такого же узора по рисунку. Складывание частей в целое, пространственное представление.", "en": "Looking at a picture and building the same pattern from blocks. Combining parts into a whole; spatial visualization."}, "looks": {"az": "Naxışı qura bilmir, kubları səhv çevirir, vaxt çatmır.", "ru": "Не может построить узор, неправильно поворачивает кубики, не хватает времени.", "en": "The child cannot build the pattern, turns the blocks incorrectly or runs out of time."}, "support": {"az": "Kublarla və Lego ilə nümunə üzrə qurma, tədricən mürəkkəbləşdirmə.", "ru": "Построение по образцу из кубиков и Lego, постепенное усложнение.", "en": "Building from a model with blocks and Lego, increasing difficulty gradually."}}, {"id": "d5", "title": {"az": "Vizual tapmaca (VSI)", "ru": "Зрительные пазлы (VSI)", "en": "Visual Puzzles (VSI)"}, "task": {"az": "Uşaq bir şəklə baxır və hansı hissələrin onu düzgün qurduğunu seçir.", "ru": "Ребёнок смотрит на картинку и выбирает части, из которых она собирается.", "en": "The child looks at a picture and selects the pieces that would make it."}, "items": [{"id": "d5i1", "t": {"az": "Hissələri zehnində birləşdirib bütöv şəkli təsəvvür etməkdə çətinlik çəkir", "ru": "Испытывает трудности с мысленным объединением частей в целое изображение", "en": "Has difficulty mentally combining pieces into a whole picture"}}, {"id": "d5i2", "t": {"az": "Çevrilmiş və ya fırlanmış hissələri tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с узнаванием перевёрнутых или повёрнутых частей", "en": "Has difficulty recognizing flipped or rotated pieces"}}, {"id": "d5i3", "t": {"az": "Seçim edərkən tələsir və ya çox uzun tərəddüd edir", "ru": "Выбирает поспешно или слишком долго колеблется", "en": "Chooses hastily or hesitates for too long"}}], "mean": {"az": "şəkli hissələrə ayırıb zehnən təsəvvür etmək", "ru": "мысленное разделение изображения на части", "en": "mentally dividing a picture into parts"}, "means": {"az": "Şəkil və ya fiqurun hansı hissələrdən ibarət olduğunu zehnən görmək.", "ru": "Мысленное видение того, из каких частей состоит картинка или фигура.", "en": "Mentally seeing which parts a picture or figure is made of."}, "looks": {"az": "Parçalardan bütöv şəkli təsəvvür etməkdə çətinlik, uyğun olmayan hissələri seçir.", "ru": "Трудно представить целую картинку из фрагментов, выбирает неподходящие части.", "en": "The child has difficulty picturing the whole image from pieces and selects parts that do not fit."}, "support": {"az": "Tapmaca, tangram, şəkli hissələrə ayırıb birləşdirmə.", "ru": "Пазлы, танграм, разбор картинки на части и сборка.", "en": "Puzzles, tangrams, taking a picture apart into pieces and putting it together."}}, {"id": "d6", "title": {"az": "Matris mühakimə (FRI)", "ru": "Матрицы (FRI)", "en": "Matrix Reasoning (FRI)"}, "task": {"az": "Naxışlı şəkildə boş yer var, uşaq çatışmayan hissəni seçir.", "ru": "В узоре есть пропуск, ребёнок выбирает недостающую часть.", "en": "A pattern has a missing part and the child selects the piece that completes it."}, "items": [{"id": "d6i1", "t": {"az": "Naxışın qaydasını (rəng, forma, ölçü) görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности узора (цвет, форма, размер)", "en": "Has difficulty seeing the rule of the pattern (color, shape, size)"}}, {"id": "d6i2", "t": {"az": "Çatışmayan hissəni seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с выбором недостающей части", "en": "Has difficulty selecting the missing piece"}}, {"id": "d6i3", "t": {"az": "Cavabı düşünmədən, təxmini seçir", "ru": "Выбирает ответ наугад, не обдумывая", "en": "Picks an answer at random without thinking it through"}}], "mean": {"az": "naxışdakı qanunauyğunluğu tapmaq", "ru": "нахождение закономерности в узоре", "en": "finding the rule in a pattern"}, "means": {"az": "Naxışda qanunauyğunluğu tapıb çatışmayan hissəni müəyyən etmək. Yeni vəziyyətdə məntiqi mühakimə.", "ru": "Нахождение закономерности в узоре и определение недостающей части. Логическое рассуждение в новой ситуации.", "en": "Finding the rule in a pattern and identifying the missing part. Logical reasoning in a new situation."}, "looks": {"az": "Qaydanı görmür, təsadüfi seçir, naxış davam etdirmə tapşırığında tez təslim olur.", "ru": "Не видит правила, выбирает наугад, быстро сдаётся при продолжении узора.", "en": "The child does not see the rule, chooses at random and gives up quickly on pattern-continuation tasks."}, "support": {"az": "Muncuq düzmə, ardıcıllıq kartları, «sonra nə gəlir?» sualı.", "ru": "Нанизывание бусин, карточки с последовательностями, вопрос «что будет дальше?».", "en": "Stringing beads, sequence cards, and the question \"what comes next?\""}}, {"id": "d7", "title": {"az": "Kəmiyyət mühakimə (FRI)", "ru": "Количественное рассуждение (FRI)", "en": "Quantitative Reasoning (FRI)"}, "task": {"az": "Uşağa kublar və ya say kartları göstərilir: «hansı qrupda çoxdur?», «bərabər olmaq üçün neçə kub əlavə etmək lazımdır?» kimi sadə müqayisələr və 2, 4, 6, … kimi say sırasının davamı istənir.", "ru": "Ребёнку показывают кубики или карточки с числами: простые сравнения вроде «где больше?», «сколько кубиков добавить, чтобы стало поровну?» и продолжение ряда 2, 4, 6, …", "en": "The child is shown blocks or number cards: simple comparisons such as \"which group has more?\" and \"how many blocks must be added to make them equal?\", and is asked to continue a series such as 2, 4, 6, …"}, "items": [{"id": "d7i1", "t": {"az": "İki qrupu say baxımından müqayisə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с количественным сравнением двух групп", "en": "Has difficulty comparing two groups by quantity"}}, {"id": "d7i2", "t": {"az": "Say sırasının qaydasını tapıb davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности числового ряда и его продолжением", "en": "Has difficulty finding the rule of a number series and continuing it"}}, {"id": "d7i3", "t": {"az": "Tapşırıq bir az dəyişəndə yeni üsul tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском нового способа, когда задание немного меняется", "en": "Has difficulty finding a new approach when the task changes slightly"}}], "mean": {"az": "miqdar və say əlaqələrini müqayisə etmək", "ru": "сравнение количественных отношений", "en": "comparing quantitative relationships"}, "means": {"az": "Kəmiyyət əlaqələrini kublar və say kartları ilə müqayisə etmək, «çox-az», «bərabər» mühakiməsi.", "ru": "Сравнение количественных отношений с помощью кубиков и карточек с числами, суждения «больше–меньше», «поровну».", "en": "Comparing quantitative relationships using blocks and number cards; judgments of \"more\", \"less\" and \"equal\"."}, "looks": {"az": "Say və miqdar müqayisəsində səhv edir, qaydanı tətbiq edə bilmir.", "ru": "Ошибается при сравнении чисел и количества, не может применить правило.", "en": "The child makes errors when comparing numbers and quantities and cannot apply the rule."}, "support": {"az": "Kublarla bərabərləşdirmə və bölüşdürmə oyunları.", "ru": "Игры на уравнивание и раздел кубиков.", "en": "Games of equalizing and sharing blocks."}}, {"id": "d8", "title": {"az": "Rəqəm ardıcıllığı (WMI)", "ru": "Повторение цифр (WMI)", "en": "Digit Span (WMI)"}, "task": {"az": "Mütəxəssis rəqəmləri bir-bir deyir, uşaq əvvəl eşitdiyi kimi, sonra tərsinə və sıralayaraq təkrarlayır.", "ru": "Специалист называет цифры по одной, ребёнок повторяет их так, как услышал, затем в обратном порядке и в порядке возрастания.", "en": "The examiner reads digits one at a time and the child repeats them as heard, then in reverse order and in sequence order."}, "items": [{"id": "d8i1", "t": {"az": "Eşitdiyi rəqəmləri eyni ardıcıllıqla təkrarlamaqda çətinlik çəkir", "ru": "Испытывает трудности с повторением услышанных цифр в том же порядке", "en": "Has difficulty repeating the digits heard in the same order"}}, {"id": "d8i2", "t": {"az": "Rəqəmləri tərs sırada və ya sıralayaraq deməkdə çətinlik çəkir", "ru": "Испытывает трудности с называнием цифр в обратном порядке или по возрастанию", "en": "Has difficulty saying digits in reverse order or in ascending order"}}, {"id": "d8i3", "t": {"az": "Rəqəmlərin sayı artanda ardıcıllığı itirir", "ru": "Теряет последовательность, когда количество цифр увеличивается", "en": "Loses the sequence as the number of digits increases"}}], "mean": {"az": "eşitdiyi rəqəmləri yadda saxlayıb təkrar etmək", "ru": "запоминание и повторение услышанных цифр", "en": "remembering and repeating digits heard"}, "means": {"az": "Eşitdiyi rəqəmləri yadda saxlayıb təkrar etmək. Qısa müddətli eşitmə yaddaşı və diqqət.", "ru": "Запоминание и повторение услышанных цифр. Слуховая кратковременная память и внимание.", "en": "Remembering and repeating digits heard. Short-term auditory memory and attention."}, "looks": {"az": "Rəqəm sırasını itirir, tapşırığı verən kimi unudur, uzun təlimatları izləyə bilmir.", "ru": "Теряет порядок цифр, забывает задание сразу после инструкции, не может выполнять длинные инструкции.", "en": "The child loses the order of digits, forgets the task right after it is given and cannot follow long instructions."}, "support": {"az": "Telefon nömrəsi, kiçik rəqəm sıraları, təlimatı tədricən uzatmaq.", "ru": "Номер телефона, короткие ряды цифр, постепенное удлинение инструкции.", "en": "Phone numbers, short digit sequences, and gradually lengthening instructions."}}, {"id": "d9", "title": {"az": "Şəkil ardıcıllığı (WMI)", "ru": "Запоминание картинок (WMI)", "en": "Picture Span (WMI)"}, "task": {"az": "Uşağa bir neçə saniyə şəkillər göstərilir, sonra o, həmin şəkilləri cavab səhifəsindən eyni sıra ilə seçir.", "ru": "Ребёнку на несколько секунд показывают картинки, затем он выбирает их на странице ответов в том же порядке.", "en": "The child is shown pictures for a few seconds and then selects them from the response page in the same order."}, "items": [{"id": "d9i1", "t": {"az": "Şəkillərin sırasını yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием порядка картинок", "en": "Has difficulty remembering the order of the pictures"}}, {"id": "d9i2", "t": {"az": "Şəkillərin sayı artanda sıranı qarışdırır", "ru": "Путает порядок, когда количество картинок увеличивается", "en": "Mixes up the order as the number of pictures increases"}}, {"id": "d9i3", "t": {"az": "Cavab səhifəsində artıq şəkillər olanda doğrusunu seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с выбором правильных картинок, когда на странице ответов есть лишние", "en": "Has difficulty choosing the correct pictures when the response page contains extra ones"}}], "mean": {"az": "gördüyü şəkilləri eyni sıra ilə xatırlamaq", "ru": "запоминание увиденных картинок в том же порядке", "en": "remembering pictures seen in the same order"}, "means": {"az": "Gördüyü şəkilləri eyni sıra ilə xatırlamaq. Vizual işlək yaddaş.", "ru": "Запоминание увиденных картинок в том же порядке. Зрительная рабочая память.", "en": "Remembering pictures seen in the same order. Visual working memory."}, "looks": {"az": "Şəkilləri qarışdırır, sıranı yadda saxlaya bilmir.", "ru": "Путает картинки, не удерживает порядок.", "en": "The child mixes up the pictures and cannot hold the order."}, "support": {"az": "Yaddaş kartları, əşyaları göstərib gizlədib sıranı soruşmaq.", "ru": "Карточки на память; показать предметы, спрятать и спросить о порядке.", "en": "Memory cards; show objects, hide them and ask about the order."}}, {"id": "d10", "title": {"az": "Kodlaşdırma (PSI)", "ru": "Шифровка (PSI)", "en": "Coding (PSI)"}, "task": {"az": "Uşaq vaxt məhdud olduqda hər rəqəmə uyğun simvolu cədvələ yazır. Qələm və sekundomer lazımdır.", "ru": "Ребёнок вписывает в таблицу символ, соответствующий каждой цифре, с ограничением по времени. Нужны карандаш и секундомер.", "en": "Within a time limit, the child writes in the table the symbol that matches each digit. A pencil and a stopwatch are needed."}, "items": [{"id": "d10i1", "t": {"az": "Simvolları düzgün və səliqəli köçürməkdə çətinlik çəkir", "ru": "Испытывает трудности с правильным и аккуратным копированием символов", "en": "Has difficulty copying symbols accurately and neatly"}}, {"id": "d10i2", "t": {"az": "Tapşırığı vaxtında bitirməkdə çətinlik çəkir", "ru": "Испытывает трудности с завершением задания в отведённое время", "en": "Has difficulty finishing the task in the allotted time"}}, {"id": "d10i3", "t": {"az": "Tempi sabit saxlamaqda çətinlik çəkir: əvvəl sürətli, sonra yavaşlayır", "ru": "Испытывает трудности с поддержанием постоянного темпа: сначала быстро, затем замедляется", "en": "Has difficulty keeping a steady pace: fast at first, then slows down"}}], "mean": {"az": "simvolları qaydaya görə sürətlə köçürmək", "ru": "быстрое копирование символов по правилу", "en": "quickly copying symbols according to a rule"}, "means": {"az": "Qələmlə simvolları sürətlə və səliqəli köçürmək. Emal sürəti, vizual-motor koordinasiya.", "ru": "Быстрое и аккуратное копирование символов карандашом. Скорость обработки информации, зрительно-моторная координация.", "en": "Copying symbols quickly and neatly with a pencil. Processing speed and visual-motor coordination."}, "looks": {"az": "Çox yavaş işləyir, simvolları səhv köçürür, yazı tempi yaşıdlardan geri qalır.", "ru": "Работает очень медленно, копирует символы с ошибками, темп письма отстаёт от сверстников.", "en": "The child works very slowly, copies symbols incorrectly and writes more slowly than peers."}, "support": {"az": "Nöqtələri birləşdirmə, labirint, yazı tempinə rahat vaxt verilməsi.", "ru": "Соединение точек, лабиринты, предоставление достаточного времени для письма.", "en": "Connect-the-dots, mazes, and allowing comfortable time for writing."}}, {"id": "d11", "title": {"az": "Simvol axtarışı (PSI)", "ru": "Поиск символов (PSI)", "en": "Symbol Search (PSI)"}, "task": {"az": "Uşaq hədəf simvolun cərgədə olub-olmadığını vaxt məhdud olduqda işarələyir.", "ru": "Ребёнок отмечает, есть ли целевой символ в ряду, с ограничением по времени.", "en": "Within a time limit, the child marks whether the target symbol appears in the row."}, "items": [{"id": "d11i1", "t": {"az": "Hədəf simvolu cərgədə tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском целевого символа в ряду", "en": "Has difficulty finding the target symbol in the row"}}, {"id": "d11i2", "t": {"az": "Tələsəndə səhv işarələyir", "ru": "Ошибается в отметках, когда торопится", "en": "Makes marking errors when rushing"}}, {"id": "d11i3", "t": {"az": "Tapşırıq davam etdikcə diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания по ходу задания", "en": "Has difficulty sustaining attention as the task continues"}}], "mean": {"az": "cərgədə eyni simvolu sürətlə tapmaq", "ru": "быстрый поиск одинакового символа в ряду", "en": "quickly finding the same symbol in a row"}, "means": {"az": "Cərgədə verilmiş simvolu gözlə tez tapmaq. Vizual diqqət və qərar sürəti.", "ru": "Быстрый поиск глазами заданного символа в ряду. Зрительное внимание и скорость принятия решения.", "en": "Quickly locating a given symbol in a row by eye. Visual attention and decision speed."}, "looks": {"az": "Axtarışda yavaşdır, tələsik səhv edir, tapşırığı tamamlamır.", "ru": "Медленно ищет, спешит и ошибается, не завершает задание.", "en": "The child searches slowly, makes hasty errors and does not complete the task."}, "support": {"az": "«Fərqi tap» oyunları, qısa vaxtlı oyunlar.", "ru": "Игры «найди отличия», игры с ограничением времени.", "en": "\"Spot the difference\" games and short timed games."}}, {"id": "d12", "title": {"az": "Əqli hesab", "ru": "Устный счёт", "en": "Arithmetic"}, "task": {"az": "Mütəxəssis hesab məsələsini səslə oxuyur, uşaq kağız-qələmsiz zehnində həll edir.", "ru": "Специалист читает вслух арифметическую задачу, ребёнок решает её в уме, без бумаги и карандаша.", "en": "The examiner reads an arithmetic problem aloud and the child solves it mentally, without paper or pencil."}, "items": [{"id": "d12i1", "t": {"az": "Məsələni eşidib mənasını başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием смысла задачи на слух", "en": "Has difficulty understanding the meaning of the problem when heard"}}, {"id": "d12i2", "t": {"az": "Rəqəmləri yadda saxlayıb zehnində hesablamaqda çətinlik çəkir", "ru": "Испытывает трудности с удержанием чисел в памяти и вычислением в уме", "en": "Has difficulty holding numbers in mind and calculating mentally"}}, {"id": "d12i3", "t": {"az": "Vaxt məhdudiyyətində cavab verməkdə çətinlik çəkir", "ru": "Испытывает трудности с ответом в пределах времени", "en": "Has difficulty answering within the time limit"}}], "mean": {"az": "ağılda hesablama aparmaq", "ru": "счёт в уме", "en": "mental arithmetic"}, "means": {"az": "Ağlında sadə hesablama aparmaq. İşlək yaddaş və diqqət.", "ru": "Простые вычисления в уме. Рабочая память и внимание.", "en": "Doing simple calculations in the head. Working memory and attention."}, "looks": {"az": "Ağlında hesablamır, barmaqla və ya kağızla sayır, məsələnin şərtini unudur.", "ru": "Не считает в уме, считает на пальцах или на бумаге, забывает условие задачи.", "en": "The child does not calculate mentally, counts on fingers or paper and forgets the conditions of the problem."}, "support": {"az": "Gündəlik həyatda ağılda hesab (alış-veriş, sayma oyunları).", "ru": "Счёт в уме в повседневной жизни (покупки, игры со счётом).", "en": "Mental arithmetic in daily life (shopping, counting games)."}}, {"id": "d13", "title": {"az": "Eşitmə işlək yaddaşı", "ru": "Слуховая рабочая память", "en": "Letter-Number Sequencing"}, "task": {"az": "Mütəxəssis qarışıq rəqəm və hərflər deyir, uşaq onları müəyyən qaydada (əvvəl rəqəmlər, sonra hərflər) yenidən sıralayır.", "ru": "Специалист называет вперемешку цифры и буквы, ребёнок переставляет их в заданном порядке (сначала цифры, затем буквы).", "en": "The examiner reads a mixed series of digits and letters and the child reorders them in a set sequence (digits first, then letters)."}, "items": [{"id": "d13i1", "t": {"az": "Eşitdiyi məlumatı qaydaya salıb yenidən düzməkdə çətinlik çəkir", "ru": "Испытывает трудности с упорядочением и перестановкой услышанной информации", "en": "Has difficulty organizing and reordering the information heard"}}, {"id": "d13i2", "t": {"az": "Uzun göstərişi bir dəfə eşidib yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием длинной инструкции после однократного предъявления", "en": "Has difficulty remembering a long instruction after hearing it once"}}, {"id": "d13i3", "t": {"az": "Tapşırıq davam etdikcə diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания по ходу задания", "en": "Has difficulty sustaining attention as the task continues"}}], "mean": {"az": "eşitdiyi məlumatı yadda saxlayıb onunla işləmək", "ru": "запоминание услышанной информации и работа с ней", "en": "holding heard information in mind and working with it"}, "means": {"az": "Eşitdiyi məlumatı yadda saxlayıb onunla işləmək.", "ru": "Запоминание услышанной информации и работа с ней.", "en": "Holding heard information in mind and working with it."}, "looks": {"az": "Təlimatın yalnız bir hissəsini yerinə yetirir.", "ru": "Выполняет только часть инструкции.", "en": "The child carries out only part of the instruction."}, "support": {"az": "Təlimatı qısa və mərhələ-mərhələ vermək.", "ru": "Давать инструкцию коротко и по этапам.", "en": "Give instructions briefly and step by step."}}, {"id": "d14", "title": {"az": "Test davranışı (bütün seansa aid)", "ru": "Поведение при тестировании (вся сессия)", "en": "Test Behavior (whole session)"}, "task": {"az": "Ayrıca tapşırıq yoxdur. Mütəxəssis seans boyu uşağın davranışına baxır.", "ru": "Отдельного задания нет. Специалист наблюдает за поведением ребёнка на протяжении всей сессии.", "en": "There is no separate task. The examiner observes the child's behavior throughout the session."}, "items": [{"id": "d14i1", "t": {"az": "Tapşırıqlara cəhd etməkdə və davam etməkdə çətinlik çəkir", "ru": "Испытывает трудности с началом выполнения заданий и их продолжением", "en": "Has difficulty attempting tasks and persisting with them"}}, {"id": "d14i2", "t": {"az": "Çətin tapşırıqda əsəbiləşməni və ya imtinanı idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с управлением раздражением или отказом при трудном задании", "en": "Has difficulty managing frustration or refusal on a hard task"}}, {"id": "d14i3", "t": {"az": "Göstərişi dinləməkdə və ona əməl etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выслушиванием инструкции и следованием ей", "en": "Has difficulty listening to instructions and following them"}}], "mean": {"az": "diqqət, əməkdaşlıq və motivasiya", "ru": "внимание, сотрудничество и мотивация", "en": "attention, cooperation and motivation"}, "means": {"az": "Test zamanı diqqət, motivasiya və əməkdaşlıq. Nəticələrin nə dərəcədə etibarlı olduğunu göstərir.", "ru": "Внимание, мотивация и сотрудничество во время тестирования. Показывает, насколько надёжны результаты.", "en": "Attention, motivation and cooperation during testing. Indicates how reliable the results are."}, "looks": {"az": "Tez yorulur, təslim olur, əməkdaşlıq etmir; nəticələr uşağın real imkanını az göstərə bilər.", "ru": "Быстро устаёт, сдаётся, не сотрудничает; результаты могут занижать реальные возможности ребёнка.", "en": "The child tires quickly, gives up and does not cooperate; results may underestimate the child's real abilities."}, "support": {"az": "Qısa fasilələr, təşviq, rahat mühit.", "ru": "Короткие перерывы, поощрение, спокойная обстановка.", "en": "Short breaks, encouragement and a comfortable environment."}}], "specialist": [{"az": "İndekslər arasındakı fərqi (profil) şərh edin, təkcə ümumi IQ-ya baxmayın.", "ru": "Интерпретируйте различия между индексами (профиль), а не только общий IQ.", "en": "Interpret the differences between indices (the profile), not just Full Scale IQ."}, {"az": "Zəif indeksləri öyrənmə dəstəyi planına çevirin.", "ru": "Превратите слабые индексы в план учебной поддержки.", "en": "Translate weak indices into a learning-support plan."}, {"az": "Nəticələri məktəb və ailə müşahidələri ilə birləşdirin.", "ru": "Соедините результаты с наблюдениями школы и семьи.", "en": "Combine results with school and family observations."}], "parentIntro": {"az": "Bu test uşağınızın necə öyrəndiyini göstərir — 'ağıllı/ağılsız' deyil, güclü və dəstək lazım olan sahələri.", "ru": "Этот тест показывает, как ваш ребёнок учится — не «умный/неумный», а сильные стороны и зоны поддержки.", "en": "This test shows how your child learns — not 'smart/not smart', but strengths and areas needing support."}, "parentTips": [{"az": "Güclü sahələri tərifləyin və onlara söykənərək yeni şeylər öyrədin.", "ru": "Хвалите сильные стороны и через них обучайте новому.", "en": "Praise strengths and teach new things by building on them."}, {"az": "Tapşırıqları kiçik addımlara bölün.", "ru": "Разбивайте задания на маленькие шаги.", "en": "Break tasks into small steps."}, {"az": "Yaddaş üçün şəkil və rəng kimi vizual ipucları istifadə edin.", "ru": "Для памяти используйте визуальные подсказки — картинки, цвета.", "en": "Use visual cues like pictures and colors to aid memory."}], "games": [{"az": "Yaddaş kartları: cüt şəkilləri tapmaq işlək yaddaşı gücləndirir.", "ru": "Карточки памяти: поиск пар укрепляет рабочую память.", "en": "Memory cards: finding pairs strengthens working memory."}, {"az": "Tapmaca və naxış davam etdirmə oyunları məntiqi inkişaf etdirir.", "ru": "Пазлы и продолжение узоров развивают логику.", "en": "Puzzles and pattern-continuation games develop reasoning."}, {"az": "'Nə dəyişdi?' oyunu: əşyaları gizlədib soruşun — diqqəti gücləndirir.", "ru": "Игра «что изменилось?»: прячьте предметы и спрашивайте — развивает внимание.", "en": "'What changed?' game: hide items and ask — builds attention."}]}, "vineland3": {"id": "vineland3", "name": "Vineland-3", "full": {"az": "Vineland Adaptiv Davranış Şkalaları, 3-cü nəşr", "ru": "Шкалы адаптивного поведения Вайнленд, 3-е изд.", "en": "Vineland Adaptive Behavior Scales, 3rd ed."}, "age": {"az": "Doğuşdan böyük yaşlara qədər", "ru": "От рождения до взрослого возраста", "en": "Birth through adulthood"}, "summary": {"az": "Uşağın gündəlik həyatda real funksional bacarıqlarını — adaptiv davranışı — ölçür. Bilik deyil, gündəlik tətbiqi qiymətləndirir.", "ru": "Измеряет реальные функциональные навыки ребёнка в повседневной жизни — адаптивное поведение. Оценивает не знания, а применение.", "en": "Measures the child's real-world functional skills in daily life — adaptive behavior. Assesses application, not knowledge."}, "advantages": [{"az": "Gündəlik real bacarıqlara fokuslanır", "ru": "Сфокусирован на реальных повседневных навыках", "en": "Focuses on real daily skills"}, {"az": "Müdaxilə hədəfləri qoymağa kömək edir", "ru": "Помогает ставить цели вмешательства", "en": "Helps set intervention targets"}, {"az": "İrəliləyişi izləmək üçün əla", "ru": "Отлично подходит для отслеживания прогресса", "en": "Excellent for tracking progress"}, {"az": "Müxtəlif yaş və səviyyələrə uyğun", "ru": "Подходит для разных возрастов и уровней", "en": "Suitable for varied ages and levels"}], "instruction": {"howto": [{"az": "Uşağı yaxşı tanıyan valideyn/baxıcı ilə doldurun.", "ru": "Заполняйте с родителем/опекуном, хорошо знающим ребёнка.", "en": "Complete with a parent/caregiver who knows the child well."}, {"az": "Uşağın 'edə bildiyi' deyil, 'adətən etdiyi' davranışı qeyd edin.", "ru": "Отмечайте то, что ребёнок «обычно делает», а не «может».", "en": "Record what the child 'usually does', not what they 'can do'."}, {"az": "Bütün sahələri ardıcıl əhatə edin.", "ru": "Последовательно охватите все области.", "en": "Cover all domains systematically."}], "methods": [{"az": "Müsahibə və ya valideyn anketi formatı", "ru": "Формат интервью или анкеты для родителя", "en": "Interview or parent questionnaire format"}, {"az": "Müşahidə ilə dəstəklənən hesabat", "ru": "Отчёт, подкреплённый наблюдением", "en": "Report supported by observation"}], "scoring": [{"az": "Bənd cavabları sahə üzrə standart ballara çevrilir.", "ru": "Ответы по пунктам переводятся в стандартные баллы по областям.", "en": "Item responses convert to domain standard scores."}, {"az": "Adaptiv Davranış Kompoziti yalnız rəsmi norma ilə hesablanır.", "ru": "Композит адаптивного поведения рассчитывается только по официальным нормам.", "en": "The Adaptive Behavior Composite is computed only with official norms."}]}, "official": [{"label": {"az": "Ünsiyyət sahəsi balı", "ru": "Балл области коммуникации", "en": "Communication domain score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Gündəlik yaşam balı", "ru": "Балл повседневных навыков", "en": "Daily Living score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Sosiallaşma balı", "ru": "Балл социализации", "en": "Socialization score"}, "hint": {"az": "standart bal", "ru": "стандартный балл", "en": "standard score"}}, {"label": {"az": "Motor bacarıqlar balı", "ru": "Балл моторики", "en": "Motor Skills score"}, "hint": {"az": "varsa", "ru": "если применимо", "en": "if applicable"}}, {"label": {"az": "Adaptiv Davranış Kompoziti (ABC)", "ru": "Композит адаптивного поведения (ABC)", "en": "Adaptive Behavior Composite (ABC)"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Ünsiyyət — reseptiv (anlama)", "ru": "Коммуникация: рецептивная (понимание)", "en": "Communication: Receptive"}, "task": {"az": "Valideynə sual: uşaq sadə göstərişləri («su gətir») və sualları başa düşür? Uzun izahı izləyir?", "ru": "Вопрос родителю: понимает ли ребёнок простые просьбы («принеси воды») и вопросы? Следит ли за длинным объяснением?", "en": "Question to the parent: does the child understand simple requests (\"bring water\") and questions? Can the child follow a long explanation?"}, "items": [{"id": "d1i1", "t": {"az": "Sadə göstəriş və sualları başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием простых инструкций и вопросов", "en": "Has difficulty understanding simple instructions and questions"}}, {"id": "d1i2", "t": {"az": "Uzun və ya mürəkkəb izahı izləməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием длинных или сложных объяснений", "en": "Has difficulty following long or complex explanations"}}, {"id": "d1i3", "t": {"az": "Eşitdiyinə uyğun reaksiya verməkdə çətinlik çəkir", "ru": "Испытывает трудности с адекватной реакцией на услышанное", "en": "Has difficulty responding appropriately to what is heard"}}], "mean": {"az": "başqasının nitqini anlamaq", "ru": "понимание речи других людей", "en": "understanding other people's speech"}, "means": {"az": "Anlama başqalarının dediklərini başa düşməkdir. Uşağın göstərişləri və izahı anlaması gündəlik həyat və öyrənmənin əsasıdır.", "ru": "Рецептивная речь — это понимание сказанного другими. Понимание ребёнком указаний и объяснений лежит в основе повседневной жизни и обучения.", "en": "Receptive communication is understanding what others say. A child's understanding of directions and explanations is the basis of daily life and learning."}, "looks": {"az": "Valideyn uşağın sadə göstərişi təkrar tələb etdiyini və ya uzun izahı izləməkdə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок требует повторения простого указания или с трудом следит за длинным объяснением.", "en": "The parent may notice that the child needs a simple direction repeated or has difficulty following a long explanation."}, "support": {"az": "Göstərişi qısa və tək addımla verin, jest və şəkillə dəstəkləyin.", "ru": "Давайте указание коротко, в один шаг, подкрепляйте жестом и картинкой.", "en": "Give the direction briefly, in one step, and support it with a gesture and a picture."}}, {"id": "d2", "title": {"az": "Ünsiyyət — ekspressiv (danışma)", "ru": "Коммуникация: экспрессивная (речь)", "en": "Communication: Expressive"}, "task": {"az": "Valideynə sual: istəyini necə bildirir? Gün ərzində nə olduğunu danışıb izah edir?", "ru": "Вопрос родителю: как ребёнок выражает желания? Рассказывает ли, что было в течение дня?", "en": "Question to the parent: how does the child express wishes? Does the child tell what happened during the day?"}, "items": [{"id": "d2i1", "t": {"az": "İstək və ehtiyaclarını ifadə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с выражением желаний и потребностей", "en": "Has difficulty expressing wants and needs"}}, {"id": "d2i2", "t": {"az": "Söhbətdə qarşılıqlı iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в беседе", "en": "Has difficulty taking part in conversation"}}, {"id": "d2i3", "t": {"az": "Hadisələri danışıb təsvir etməkdə çətinlik çəkir", "ru": "Испытывает трудности с рассказом о событиях и их описанием", "en": "Has difficulty telling about and describing events"}}], "mean": {"az": "öz fikrini söz və cümlələrlə demək", "ru": "выражение мыслей словами и фразами", "en": "expressing ideas in words and sentences"}, "means": {"az": "İfadə etmək fikrini söz və cümlələrlə demək bacarığıdır. Uşaq bununla istəyini, hissini və təcrübəsini paylaşır.", "ru": "Экспрессивная речь — это умение выражать мысли словами и фразами. С её помощью ребёнок делится желаниями, чувствами и опытом.", "en": "Expressive communication is the ability to express ideas in words and sentences. The child uses it to share wishes, feelings and experiences."}, "looks": {"az": "Valideyn uşağın istəyini sözlə bildirmədiyini, jest, ağlama və ya bir-iki sözlə kifayətləndiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок не выражает желание словами, обходится жестом, плачем или одним-двумя словами.", "en": "The parent may notice that the child does not state wishes in words and gets by with gestures, crying or one or two words."}, "support": {"az": "Gündəlik rutinlərdə seçim verin, cavabı gözləyin və uşağın dediyini bir qədər genişləndirin.", "ru": "В повседневных ситуациях предлагайте выбор, ждите ответа и немного расширяйте сказанное ребёнком.", "en": "Offer choices in daily routines, wait for the answer and slightly expand what the child says."}}, {"id": "d3", "title": {"az": "Ünsiyyət — yazılı (oxu və yazı)", "ru": "Коммуникация: письменная (чтение и письмо)", "en": "Communication: Written"}, "task": {"az": "Valideynə sual: hərfləri tanıyır, oxuyur, öz adını yazır? Yazılı tapşırığı başa düşür?", "ru": "Вопрос родителю: узнаёт ли ребёнок буквы, читает ли, пишет ли своё имя? Понимает ли письменное задание?", "en": "Question to the parent: does the child recognize letters, read, and write his or her own name? Does the child understand written instructions?"}, "items": [{"id": "d3i1", "t": {"az": "Yaşına uyğun oxumaqda çətinlik çəkir", "ru": "Испытывает трудности с чтением, соответствующим возрасту", "en": "Has difficulty reading at an age-appropriate level"}}, {"id": "d3i2", "t": {"az": "Hərf və yazı bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками букв и письма", "en": "Has difficulty with letter and writing skills"}}, {"id": "d3i3", "t": {"az": "Yazılı təlimatı başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием письменных инструкций", "en": "Has difficulty understanding written instructions"}}], "mean": {"az": "oxumaq və yazmaq", "ru": "чтение и письмо", "en": "reading and writing"}, "means": {"az": "Oxumaq və yazmaq məktəb öyrənməsinin əsasıdır. Hərf tanıma, söz oxuma və öz adını yazma bu sahəyə daxildir.", "ru": "Чтение и письмо — основа школьного обучения. В эту область входят узнавание букв, чтение слов и написание своего имени.", "en": "Reading and writing are the basis of school learning. This domain includes recognizing letters, reading words and writing one's own name."}, "looks": {"az": "Valideyn uşağın hərfləri tanımadığını, öz adını yazmadığını və ya oxumağa maraq göstərmədiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок не узнаёт буквы, не пишет своё имя или не проявляет интереса к чтению.", "en": "The parent may notice that the child does not recognize letters, does not write his or her name or shows no interest in reading."}, "support": {"az": "Hərf kartları, şəkilli kitablar və uşağın adını yazma oyunları ilə maraqlı şəkildə məşğul olun.", "ru": "Занимайтесь в увлекательной форме: карточки с буквами, книги с картинками, игры по написанию имени ребёнка.", "en": "Engage in an enjoyable way with letter cards, picture books and games of writing the child's name."}}, {"id": "d4", "title": {"az": "Gündəlik — şəxsi qulluq", "ru": "Повседневные навыки: личная гигиена и уход", "en": "Daily Living Skills: Personal"}, "task": {"az": "Valideynə sual: özü geyinir, yeyir, əl-üzünü yuyur, tualetə gedir?", "ru": "Вопрос родителю: одевается ли ребёнок сам, ест, умывается, ходит в туалет?", "en": "Question to the parent: does the child dress, eat, wash hands and face, and use the toilet independently?"}, "items": [{"id": "d4i1", "t": {"az": "Geyinmə, yemək və gigiyena bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками одевания, приёма пищи и гигиены", "en": "Has difficulty with dressing, eating, and hygiene skills"}}, {"id": "d4i2", "t": {"az": "Tualet bacarıqlarında çətinlik çəkir", "ru": "Испытывает трудности с навыками пользования туалетом", "en": "Has difficulty with toileting skills"}}, {"id": "d4i3", "t": {"az": "Şəxsi əşyalarına qulluq etməkdə çətinlik çəkir", "ru": "Испытывает трудности с уходом за личными вещами", "en": "Has difficulty looking after personal belongings"}}], "mean": {"az": "yemək, geyinmək, gigiyena", "ru": "еда, одевание, гигиена", "en": "eating, dressing, hygiene"}, "means": {"az": "Şəxsi qulluq yemək, geyinmək və gigiyena bacarıqlarını əhatə edir. Müstəqil olmağa və özünə güvənə yol açır.", "ru": "Личная самостоятельность включает навыки приёма пищи, одевания и гигиены. Она ведёт к независимости и уверенности в себе.", "en": "Personal skills include eating, dressing and hygiene. They lead to independence and self-confidence."}, "looks": {"az": "Valideyn uşağın geyinmək, yemək, əl yumaq və ya tualetdən istifadədə hələ kömək tələb etdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнку всё ещё нужна помощь при одевании, еде, мытье рук или пользовании туалетом.", "en": "The parent may notice that the child still needs help with dressing, eating, washing hands or using the toilet."}, "support": {"az": "Bacarığı kiçik addımlara bölün və hər addımı şəkil cədvəli ilə göstərin, uğurları təriflə.", "ru": "Разделите навык на маленькие шаги и показывайте каждый шаг в картинном расписании; хвалите успехи.", "en": "Break the skill into small steps and show each step on a picture schedule; praise successes."}}, {"id": "d5", "title": {"az": "Gündəlik — ev və məişət", "ru": "Повседневные навыки: дом и быт", "en": "Daily Living Skills: Domestic"}, "task": {"az": "Valideynə sual: evdə hansı işlərə kömək edir (süfrə qurmaq, oyuncaqları yığmaq)?", "ru": "Вопрос родителю: в каких домашних делах ребёнок помогает (накрывает на стол, убирает игрушки)?", "en": "Question to the parent: what household tasks does the child help with (setting the table, putting away toys)?"}, "items": [{"id": "d5i1", "t": {"az": "Sadə ev işlərində iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в простых домашних делах", "en": "Has difficulty taking part in simple household tasks"}}, {"id": "d5i2", "t": {"az": "Əşyaları öz yerinə qoymaqda çətinlik çəkir", "ru": "Испытывает трудности с тем, чтобы класть вещи на место", "en": "Has difficulty putting things away"}}, {"id": "d5i3", "t": {"az": "Sadə hazırlıq işlərinə kömək etməkdə çətinlik çəkir", "ru": "Испытывает трудности с помощью в простой подготовке (например, к приёму пищи)", "en": "Has difficulty helping with simple preparations (for example, for meals)"}}], "mean": {"az": "ev işlərində iştirak", "ru": "участие в домашних делах", "en": "helping with household tasks"}, "means": {"az": "Ev işlərində iştirak məsuliyyət və müstəqillik bacarığını inkişaf etdirir. Uşaq ailənin bir üzvü kimi hiss edir.", "ru": "Участие в домашних делах развивает ответственность и самостоятельность. Ребёнок чувствует себя членом семьи.", "en": "Taking part in household tasks develops responsibility and independence. The child feels like a member of the family."}, "looks": {"az": "Valideyn uşağın süfrə qurma və ya oyuncaq yığma kimi sadə işlərdə iştirak etmədiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок не участвует в простых делах, например накрывании на стол или уборке игрушек.", "en": "The parent may notice that the child does not take part in simple tasks such as setting the table or putting toys away."}, "support": {"az": "Yaşa uyğun sadə tapşırıqlar verin (qaşıq qoymaq, oyuncaqları qutuya yığmaq), birlikdə edin.", "ru": "Давайте простые поручения по возрасту (положить ложку, убрать игрушки в коробку) и выполняйте их вместе.", "en": "Give simple, age-appropriate tasks (put out a spoon, put toys in a box) and do them together."}}, {"id": "d6", "title": {"az": "Gündəlik — icma", "ru": "Повседневные навыки: социум", "en": "Daily Living Skills: Community"}, "task": {"az": "Valideynə sual: pulu və saatı yaşına görə başa düşür? Küçədə təhlükəsizlik qaydalarına əməl edir? Mağaza, nəqliyyatda necə davranır?", "ru": "Вопрос родителю: понимает ли ребёнок деньги и время в соответствии с возрастом? Соблюдает ли правила безопасности на улице? Как ведёт себя в магазине и транспорте?", "en": "Question to the parent: does the child understand money and time for his or her age? Does the child follow safety rules outdoors? How does the child behave in shops and on public transport?"}, "items": [{"id": "d6i1", "t": {"az": "Pul və vaxt anlayışını (yaşa uyğun) başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием денег и времени (в соответствии с возрастом)", "en": "Has difficulty understanding money and time (for age)"}}, {"id": "d6i2", "t": {"az": "Təhlükəsizlik qaydalarını bilməkdə və tətbiq etməkdə çətinlik çəkir", "ru": "Испытывает трудности с усвоением и применением правил безопасности", "en": "Has difficulty learning and applying safety rules"}}, {"id": "d6i3", "t": {"az": "İctimai yerlərdə uyğun davranmaqda çətinlik çəkir", "ru": "Испытывает трудности с адекватным поведением в общественных местах", "en": "Has difficulty behaving appropriately in public places"}}], "mean": {"az": "pul, vaxt, təhlükəsizlik, ictimai yerlərdə davranış", "ru": "деньги, время, безопасность, поведение в общественных местах", "en": "money, time, safety, behavior in public places"}, "means": {"az": "Pul, vaxt, təhlükəsizlik və ictimai yerdə davranış uşağın evdən kənarda uyğunlaşmasını göstərir.", "ru": "Деньги, время, безопасность и поведение в общественном месте показывают, как ребёнок приспосабливается за пределами дома.", "en": "Money, time, safety and behavior in public places show how the child adapts outside the home."}, "looks": {"az": "Valideyn uşağın pul və vaxt anlayışını başa düşmədiyini, küçədə təhlükəsizlik qaydalarına əməl etmədiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок не понимает понятий денег и времени, не соблюдает правила безопасности на улице.", "en": "The parent may notice that the child does not understand the concepts of money and time and does not follow safety rules on the street."}, "support": {"az": "Oyun mağazası, oyuncaq pul və saat modeli ilə rolları oynayın, küçə qaydalarını şəkillərlə izah edin.", "ru": "Играйте в магазин с игрушечными деньгами и моделью часов, объясняйте правила улицы с помощью картинок.", "en": "Role-play a shop with toy money and a clock model, and explain street rules with pictures."}}, {"id": "d7", "title": {"az": "Sosiallaşma — münasibətlər", "ru": "Социализация: межличностные отношения", "en": "Socialization: Interpersonal Relationships"}, "task": {"az": "Valideynə sual: tanışlarla və yaşıdları ilə münasibət qura bilir? Başqasının hissini tanıyır? Dostu var?", "ru": "Вопрос родителю: может ли ребёнок выстраивать отношения со знакомыми и сверстниками? Распознаёт ли чувства других? Есть ли у него друг?", "en": "Question to the parent: can the child build relationships with familiar people and peers? Does the child recognize others' feelings? Does the child have a friend?"}, "items": [{"id": "d7i1", "t": {"az": "Başqaları ilə münasibət qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с построением отношений с другими людьми", "en": "Has difficulty building relationships with others"}}, {"id": "d7i2", "t": {"az": "Başqasının emosiyasını tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с распознаванием эмоций других людей", "en": "Has difficulty recognizing other people's emotions"}}, {"id": "d7i3", "t": {"az": "Dostluğu saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с поддержанием дружбы", "en": "Has difficulty maintaining friendships"}}], "mean": {"az": "başqaları ilə əlaqə qurmaq", "ru": "установление отношений с другими людьми", "en": "building relationships with other people"}, "means": {"az": "Başqaları ilə əlaqə qurmaq tanışlarla, yaşıdlarla və ailə üzvləri ilə münasibətdir. Dostluq və dəstək buradan başlayır.", "ru": "Установление отношений с другими — это общение со знакомыми, сверстниками и членами семьи. С этого начинаются дружба и поддержка.", "en": "Building relationships with others means interacting with acquaintances, peers and family members. Friendship and support begin here."}, "looks": {"az": "Valideyn uşağın tanışlarla və yaşıdlarla münasibət qurmaqda çətinlik çəkdiyini, dostu az olduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнку трудно выстраивать отношения со знакомыми и сверстниками, у него мало друзей.", "en": "The parent may notice that the child has difficulty forming relationships with acquaintances and peers and has few friends."}, "support": {"az": "Kiçik qrupda sadə oyunlar qurun, salamlaşma və tanış olma addımlarını rol oyunu ilə məşq edin.", "ru": "Организуйте простые игры в малой группе, отрабатывайте приветствие и знакомство в ролевой игре.", "en": "Set up simple games in a small group and practice greeting and introducing oneself through role play."}}, {"id": "d8", "title": {"az": "Sosiallaşma — oyun və asudə vaxt", "ru": "Социализация: игра и досуг", "en": "Socialization: Play and Leisure Time"}, "task": {"az": "Valideynə sual: uşaqlarla oynayanda növbə gözləyir, oyuncağı bölüşür? Qrup fəaliyyətində iştirak edir?", "ru": "Вопрос родителю: ждёт ли ребёнок очереди, делится ли игрушками в игре с другими детьми? Участвует ли в групповых занятиях?", "en": "Question to the parent: does the child take turns and share toys when playing with other children? Does the child join group activities?"}, "items": [{"id": "d8i1", "t": {"az": "Oyun və asudə vaxtı başqası ilə bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с совместной игрой и проведением досуга с другими", "en": "Has difficulty sharing play and leisure with others"}}, {"id": "d8i2", "t": {"az": "Növbə gözləməkdə və bölüşməkdə çətinlik çəkir", "ru": "Испытывает трудности с ожиданием очереди и с тем, чтобы делиться", "en": "Has difficulty taking turns and sharing"}}, {"id": "d8i3", "t": {"az": "Qrup fəaliyyətində iştirak etməkdə çətinlik çəkir", "ru": "Испытывает трудности с участием в групповых занятиях", "en": "Has difficulty taking part in group activities"}}], "mean": {"az": "birgə oyun, boş vaxtı təşkil etmək", "ru": "совместная игра, организация досуга", "en": "joint play, organizing leisure time"}, "means": {"az": "Birgə oyun və boş vaxtın təşkili uşağın sosial bacarıqlarını və əylənməyi göstərir.", "ru": "Совместная игра и организация досуга отражают социальные навыки ребёнка и умение получать удовольствие.", "en": "Joint play and organizing leisure time reflect the child's social skills and capacity for enjoyment."}, "looks": {"az": "Valideyn uşağın oyunda növbə gözləmədiyini, oyuncağı bölüşmədiyini və ya qrup oyunlarından kənarda qaldığını görə bilər.", "ru": "Родитель может замечать, что ребёнок не ждёт очереди в игре, не делится игрушкой или остаётся в стороне от групповых игр.", "en": "The parent may notice that the child does not wait for a turn in play, does not share toys or stays out of group games."}, "support": {"az": "Növbəli oyunlar (top, lotolar) qurun, qaydaları əvvəlcədən göstərin, iştirakını təriflə.", "ru": "Организуйте игры по очереди (мяч, лото), заранее показывайте правила, хвалите за участие.", "en": "Set up turn-taking games (ball, lotto), show the rules in advance and praise participation."}}, {"id": "d9", "title": {"az": "Sosiallaşma — uyğunlaşma", "ru": "Социализация: навыки совладания", "en": "Socialization: Coping Skills"}, "task": {"az": "Valideynə sual: qaydalara əməl edir? Qəzəbləndikdə özünü idarə edir? Xətasını görəndə üzr istəyir?", "ru": "Вопрос родителю: соблюдает ли ребёнок правила? Справляется ли с собой, когда сердится? Извиняется ли, увидев свою ошибку?", "en": "Question to the parent: does the child follow rules? Does the child control himself or herself when angry? Does the child apologize on seeing a mistake?"}, "items": [{"id": "d9i1", "t": {"az": "Sosial qaydalara uyğunlaşmaqda çətinlik çəkir", "ru": "Испытывает трудности с приспособлением к социальным правилам", "en": "Has difficulty adapting to social rules"}}, {"id": "d9i2", "t": {"az": "Emosiyalarını idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с управлением эмоциями", "en": "Has difficulty managing emotions"}}, {"id": "d9i3", "t": {"az": "Məsuliyyət daşımaqda və üzr istəməkdə çətinlik çəkir", "ru": "Испытывает трудности с принятием ответственности и принесением извинений", "en": "Has difficulty taking responsibility and apologizing"}}], "mean": {"az": "qaydalara riayət, hissləri idarə etmək", "ru": "соблюдение правил, управление чувствами", "en": "following rules, managing feelings"}, "means": {"az": "Qaydalara riayət və hissləri idarə etmək sosial uyğunlaşmanın əsasıdır. Uşaq bu bacarıqla qrupda rahat olur.", "ru": "Соблюдение правил и управление чувствами — основа социальной адаптации. С этим умением ребёнку комфортнее в группе.", "en": "Following rules and managing feelings are the basis of social adjustment. With this skill the child is more comfortable in a group."}, "looks": {"az": "Valideyn uşağın qaydaya əməl etməkdə və qəzəbləndikdə özünü idarə etməkdə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнку трудно соблюдать правила и сдерживать себя в гневе.", "en": "The parent may notice that the child has difficulty following rules and controlling himself or herself when angry."}, "support": {"az": "Qaydaları şəkillərlə göstərin, hisslərini adlandırmağı və sakitləşmə üsulları (dərin nəfəs) məşq edin.", "ru": "Показывайте правила в картинках, учите называть чувства и отрабатывайте способы успокоения (глубокое дыхание).", "en": "Show the rules with pictures, practice naming feelings and rehearse calming methods (deep breathing)."}}, {"id": "d10", "title": {"az": "Motor bacarıqlar — iri", "ru": "Моторные навыки: крупная моторика", "en": "Motor Skills: Gross"}, "task": {"az": "Valideynə sual: qaçır, tullanır, pilləkən çıxır, topla oynayır? Tez-tez yıxılır?", "ru": "Вопрос родителю: бегает ли ребёнок, прыгает, поднимается по лестнице, играет в мяч? Часто ли падает?", "en": "Question to the parent: does the child run, jump, climb stairs, and play ball? Does the child fall often?"}, "items": [{"id": "d10i1", "t": {"az": "Qaçma, tullanma və tarazlıqda çətinlik çəkir", "ru": "Испытывает трудности с бегом, прыжками и равновесием", "en": "Has difficulty with running, jumping, and balance"}}, {"id": "d10i2", "t": {"az": "Hərəkətlərinin koordinasiyasında çətinlik çəkir", "ru": "Испытывает трудности с координацией движений", "en": "Has difficulty coordinating movements"}}, {"id": "d10i3", "t": {"az": "Pilləkən və maneələri keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с преодолением лестниц и препятствий", "en": "Has difficulty managing stairs and obstacles"}}], "mean": {"az": "qaçmaq, tullanmaq, tarazlıq", "ru": "бег, прыжки, равновесие", "en": "running, jumping, balance"}, "means": {"az": "İri motor bacarıqlar qaçmaq, tullanmaq və tarazlığı saxlamaqdır. Fiziki fəallıq və oyun üçün lazımdır.", "ru": "Крупная моторика — это бег, прыжки и удержание равновесия. Она нужна для физической активности и игры.", "en": "Gross motor skills are running, jumping and maintaining balance. They are needed for physical activity and play."}, "looks": {"az": "Valideyn uşağın tez-tez yıxıldığını, topla və pilləkənlə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок часто падает, испытывает трудности с мячом и лестницей.", "en": "The parent may notice that the child falls often and has difficulty with a ball and with stairs."}, "support": {"az": "Maneə yolu, top oyunları və tarazlıq üçün xətt boyunca yeriş oyunları təşkil edin.", "ru": "Организуйте полосу препятствий, игры с мячом и ходьбу по линии для тренировки равновесия.", "en": "Set up an obstacle course, ball games and walking along a line to practice balance."}}, {"id": "d11", "title": {"az": "Motor bacarıqlar — incə", "ru": "Моторные навыки: мелкая моторика", "en": "Motor Skills: Fine"}, "task": {"az": "Valideynə sual: qələm tutur, düymə bağlayır, qayçı ilə kəsir, kiçik əşyaları götürür?", "ru": "Вопрос родителю: держит ли ребёнок карандаш, застёгивает ли пуговицы, режет ли ножницами, берёт ли мелкие предметы?", "en": "Question to the parent: does the child hold a pencil, fasten buttons, cut with scissors, and pick up small objects?"}, "items": [{"id": "d11i1", "t": {"az": "Qələm, düymə və ya qayçıdan istifadədə çətinlik çəkir", "ru": "Испытывает трудности с использованием карандаша, пуговиц или ножниц", "en": "Has difficulty using a pencil, buttons, or scissors"}}, {"id": "d11i2", "t": {"az": "Əl-göz koordinasiyasında çətinlik çəkir", "ru": "Испытывает трудности с координацией глаз и рук", "en": "Has difficulty with eye-hand coordination"}}, {"id": "d11i3", "t": {"az": "Kiçik əşyaları idarə etməkdə çətinlik çəkir", "ru": "Испытывает трудности с манипулированием мелкими предметами", "en": "Has difficulty manipulating small objects"}}], "mean": {"az": "qələm tutmaq, düymələmək, kiçik əşyalarla iş", "ru": "удерживание карандаша, застёгивание пуговиц, работа с мелкими предметами", "en": "holding a pencil, buttoning, handling small objects"}, "means": {"az": "İncə motor bacarıqlar qələm tutmaq, düymələmək və kiçik əşyalarla işləməkdir. Yazı və özünəxidmət üçün lazımdır.", "ru": "Мелкая моторика — это удерживание карандаша, застёгивание пуговиц и работа с мелкими предметами. Она нужна для письма и самообслуживания.", "en": "Fine motor skills are holding a pencil, buttoning and handling small objects. They are needed for writing and self-care."}, "looks": {"az": "Valideyn uşağın qələm tutmaqda, düymə bağlamaqda və ya qayçıdan istifadədə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнку трудно держать карандаш, застёгивать пуговицы или пользоваться ножницами.", "en": "The parent may notice that the child has difficulty holding a pencil, fastening buttons or using scissors."}, "support": {"az": "Muncuq düzmə, plastilin, kublar və iri düymələrlə məşqlər edin.", "ru": "Выполняйте упражнения с нанизыванием бусин, пластилином, кубиками и крупными пуговицами.", "en": "Do exercises with stringing beads, modeling clay, blocks and large buttons."}}, {"id": "d12", "title": {"az": "Problemli davranış — daxilə yönəlmiş", "ru": "Дезадаптивное поведение: интернализированное", "en": "Maladaptive Behavior: Internalizing"}, "task": {"az": "Valideynə sual: uşaq qapanır, çox narahat olur, qorxur, kədərli görünür? Bu, gündəlik işlərinə mane olur?", "ru": "Вопрос родителю: замыкается ли ребёнок в себе, сильно тревожится, боится, выглядит печальным? Мешает ли это повседневной деятельности?", "en": "Question to the parent: does the child withdraw, worry a great deal, seem fearful or sad? Does this interfere with daily activities?"}, "items": [{"id": "d12i1", "t": {"az": "Qapanır və ya çox narahat olur", "ru": "Замыкается в себе или сильно тревожится", "en": "Withdraws or is very anxious"}}, {"id": "d12i2", "t": {"az": "Kədər və ya qorxu əlamətləri göstərir", "ru": "Проявляет признаки печали или страха", "en": "Shows signs of sadness or fear"}}, {"id": "d12i3", "t": {"az": "Bu hallar gündəlik fəaliyyətinə mane olur", "ru": "Эти состояния мешают повседневной деятельности", "en": "These states interfere with daily activities"}}], "mean": {"az": "qorxu, həyəcan, geri çəkilmə", "ru": "страх, тревога, замкнутость", "en": "fear, anxiety, withdrawal"}, "means": {"az": "Daxilə yönəlmiş davranış qorxu, həyəcan və geri çəkilmə kimi hissləri əhatə edir. Uşağın emosional rifahı üçün diqqət tələb edir.", "ru": "Интернализованное поведение включает такие переживания, как страх, тревога и замкнутость. Оно требует внимания с точки зрения эмоционального благополучия ребёнка.", "en": "Internalizing behavior includes feelings such as fear, anxiety and withdrawal. It needs attention for the child's emotional well-being."}, "looks": {"az": "Valideyn uşağın qapandığını, çox narahat olduğunu və ya qorxuları səbəbilə gündəlik işlərdən çəkindiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок замыкается, сильно тревожится или избегает повседневных дел из-за страхов.", "en": "The parent may notice that the child withdraws, is very anxious or avoids daily activities because of fears."}, "support": {"az": "Təhlükəsiz və proqnozlaşdırıla bilən mühit yaradın, hissləri sakit şəkildə dinləyin və qorxulu vəziyyətlərə tədricən yaxınlaşdırın.", "ru": "Создайте безопасную, предсказуемую обстановку, спокойно выслушивайте чувства и постепенно приближайте к пугающим ситуациям.", "en": "Create a safe and predictable environment, listen calmly to feelings and approach frightening situations gradually."}}, {"id": "d13", "title": {"az": "Problemli davranış — xaricə yönəlmiş", "ru": "Дезадаптивное поведение: экстернализированное", "en": "Maladaptive Behavior: Externalizing"}, "task": {"az": "Valideynə sual: vurur, dişləyir, qışqırır, ani hərəkət edir? Qaydalara qarşı çıxır?", "ru": "Вопрос родителю: бьёт ли ребёнок, кусается, кричит, действует импульсивно? Противится ли правилам?", "en": "Question to the parent: does the child hit, bite, shout, or act impulsively? Does the child oppose rules?"}, "items": [{"id": "d13i1", "t": {"az": "Aqressiv və ya impulsiv davranış göstərir", "ru": "Проявляет агрессивное или импульсивное поведение", "en": "Shows aggressive or impulsive behavior"}}, {"id": "d13i2", "t": {"az": "Qaydalara qarşı çıxır", "ru": "Противится правилам", "en": "Opposes rules"}}, {"id": "d13i3", "t": {"az": "Fəaliyyətə mane olan davranış göstərir", "ru": "Проявляет поведение, мешающее деятельности", "en": "Shows behavior that disrupts activities"}}], "mean": {"az": "aqressiya, qaydanı pozma", "ru": "агрессия, нарушение правил", "en": "aggression, rule-breaking"}, "means": {"az": "Xaricə yönəlmiş davranış vurma, qışqırma, impulsivlik və qaydalara qarşı çıxmadır. Bu, uşağın hissini idarə etmək çətinliyi ola bilər.", "ru": "Экстернализованное поведение — это удары, крики, импульсивность и противодействие правилам. Это может быть трудностью управления чувствами.", "en": "Externalizing behavior is hitting, shouting, impulsivity and opposing rules. It may reflect difficulty managing feelings."}, "looks": {"az": "Valideyn uşağın vurduğunu, qışqırdığını, ani hərəkət etdiyini və ya qaydaya qarşı çıxdığını görə bilər.", "ru": "Родитель может замечать, что ребёнок бьёт, кричит, действует импульсивно или противится правилам.", "en": "The parent may notice that the child hits, shouts, acts impulsively or opposes rules."}, "support": {"az": "Davranışın səbəbini və vaxtını qeyd edin, sakit künc və müsbət davranışa tərif ilə dəstəkləyin.", "ru": "Отмечайте причину и время поведения, поддерживайте спокойным уголком и похвалой за положительное поведение.", "en": "Note the cause and timing of the behavior, and support with a calm corner and praise for positive behavior."}}], "specialist": [{"az": "Ən aşağı sahələri ilkin müdaxilə hədəfi seçin.", "ru": "Выберите самые слабые области как первичные цели вмешательства.", "en": "Select the lowest domains as primary intervention targets."}, {"az": "Bacarıqları kiçik, ölçülə bilən addımlara bölün.", "ru": "Разбейте навыки на маленькие измеримые шаги.", "en": "Break skills into small, measurable steps."}, {"az": "3–6  aydan bir təkrar ölçməklə irəliləyişi izləyin.", "ru": "Отслеживайте прогресс повторной оценкой каждые 3–6 мес.", "en": "Track progress with re-assessment every 3–6 months."}], "parentIntro": {"az": "Bu sahələr uşağınızın gündəlik müstəqilliyini göstərir. Kiçik gündəlik təcrübə böyük fərq yaradır.", "ru": "Эти области показывают повседневную самостоятельность ребёнка. Маленькая ежедневная практика даёт большую разницу.", "en": "These areas show your child's daily independence. Small daily practice makes a big difference."}, "parentTips": [{"az": "Gündəlik işləri (geyinmə, süfrə) birlikdə addım-addım öyrədin.", "ru": "Учите повседневным делам (одевание, стол) вместе, шаг за шагом.", "en": "Teach daily tasks (dressing, table) together, step by step."}, {"az": "Bacarığı göstərib sonra uşağa cəhd imkanı verin.", "ru": "Покажите навык, затем дайте ребёнку попробовать.", "en": "Demonstrate the skill, then let the child try."}, {"az": "Hər kiçik uğuru tərifləyin — təkrar motivasiya gətirir.", "ru": "Хвалите каждый маленький успех — повторение даёт мотивацию.", "en": "Praise every small success — repetition builds motivation."}], "games": [{"az": "'Köməkçi' oyunu: süfrə düzmək, paltar qatlamaq kimi real işlər.", "ru": "Игра «помощник»: реальные дела — накрыть стол, сложить одежду.", "en": "'Helper' game: real tasks like setting the table, folding clothes."}, {"az": "Geyinmə yarışı: düymə və zəncirləri əyləncəli şəkildə məşq edin.", "ru": "Гонка одевания: тренируйте пуговицы и молнии играючи.", "en": "Dressing race: practice buttons and zippers playfully."}, {"az": "Rollu oyun (mağaza, həkim) sosial bacarıqları gücləndirir.", "ru": "Ролевая игра (магазин, доктор) укрепляет социальные навыки.", "en": "Role-play (shop, doctor) strengthens social skills."}]}, "leiter3": {"id": "leiter3", "name": "Leiter-3", "full": {"az": "Leiter Beynəlxalq Performans Şkalası, 3-cü nəşr", "ru": "Международная шкала производительности Лейтер, 3-е изд.", "en": "Leiter International Performance Scale, 3rd ed."}, "age": {"az": "3 yaşdan böyük (uşaq və böyüklər)", "ru": "От 3 лет (дети и взрослые)", "en": "Ages 3 and up (children and adults)"}, "summary": {"az": "Tamamilə qeyri-verbal idrak testi — danışıq tələb etmir. Dil və ya eşitmə çətinliyi olan uşaqlar üçün ideal idrak qiymətləndirməsidir.", "ru": "Полностью невербальный когнитивный тест — не требует речи. Идеален для детей с трудностями речи или слуха.", "en": "A fully nonverbal cognitive test — requires no speech. Ideal cognitive assessment for children with speech or hearing difficulties."}, "advantages": [{"az": "Danışıq tələb etmir", "ru": "Не требует речи", "en": "Requires no speech"}, {"az": "Dil maneəsini aradan qaldırır", "ru": "Устраняет языковой барьер", "en": "Removes the language barrier"}, {"az": "Eşitmə çətinliyi olanlar üçün uyğundur", "ru": "Подходит при трудностях слуха", "en": "Suitable for those with hearing difficulties"}, {"az": "Saf idrak qabiliyyətini açır", "ru": "Раскрывает чистую когнитивную способность", "en": "Reveals pure cognitive ability"}], "instruction": {"howto": [{"az": "Göstəriş və nümunələri jest və modelləşdirmə ilə verin.", "ru": "Давайте инструкции жестами и показом.", "en": "Give instructions through gesture and modeling."}, {"az": "Sakit mühitdə, vizual material ilə təkbətək işləyin.", "ru": "Работайте наедине в тихой среде с визуальным материалом.", "en": "Work one-on-one in a quiet setting with visual material."}, {"az": "Uşağın yanaşma tərzini və səbrini müşahidə edin.", "ru": "Наблюдайте подход и терпение ребёнка.", "en": "Observe the child's approach and patience."}], "methods": [{"az": "Vizual uyğunlaşdırma və ardıcıllıq tapşırıqları", "ru": "Зрительное сопоставление и задания на последовательность", "en": "Visual matching and sequencing tasks"}, {"az": "Jestlə verilən qeyri-verbal göstərişlər", "ru": "Невербальные инструкции жестами", "en": "Nonverbal gesture-based instructions"}], "scoring": [{"az": "Performans xam balları normaya görə çevrilir.", "ru": "Сырые баллы производительности переводятся по нормам.", "en": "Performance raw scores convert per norms."}, {"az": "IQ ekvivalenti yalnız rəsmi cədvəllərlə hesablanır.", "ru": "Эквивалент IQ рассчитывается только по официальным таблицам.", "en": "The IQ equivalent is computed only with official tables."}]}, "official": [{"label": {"az": "Vizuallaşdırma/Mühakimə balı", "ru": "Балл визуализации/рассуждения", "en": "Visualization/Reasoning score"}, "hint": {"az": "kompozit", "ru": "композит", "en": "composite"}}, {"label": {"az": "Diqqət/Yaddaş balı", "ru": "Балл внимания/памяти", "en": "Attention/Memory score"}, "hint": {"az": "kompozit", "ru": "композит", "en": "composite"}}, {"label": {"az": "Qeyri-verbal IQ", "ru": "Невербальный IQ", "en": "Nonverbal IQ"}, "hint": {"az": "ümumi bal", "ru": "общий балл", "en": "composite"}}], "domains": [{"id": "d1", "title": {"az": "Fiqur-fon", "ru": "Фигура и фон", "en": "Figure Ground"}, "task": {"az": "Uşağa kartda qarışıq şəkil göstərilir, o, göstərilən fiquru çərçivədə tapıb qoyur. Leiter-3 dəsti lazımdır.", "ru": "Ребёнку показывают карточку со сложным изображением, он находит и вставляет в рамку указанную фигуру. Нужен набор Leiter-3.", "en": "The child is shown a card with a complex picture and finds and places the target figure in the frame. The Leiter-3 kit is needed."}, "items": [{"id": "d1i1", "t": {"az": "Göstərilən fiquru qarışıq fonda tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском указанной фигуры на сложном фоне", "en": "Has difficulty finding the target figure against a complex background"}}, {"id": "d1i2", "t": {"az": "Lazımsız detallara yayınır", "ru": "Отвлекается на ненужные детали", "en": "Is distracted by irrelevant details"}}, {"id": "d1i3", "t": {"az": "Tapşırıq çətinləşəndə axtarışı sistemli aparmır", "ru": "Не ищет систематически, когда задание усложняется", "en": "Does not search systematically when the task becomes harder"}}], "mean": {"az": "qarışıq fonda lazımi fiquru seçmək", "ru": "выбор нужной фигуры на фоне помех", "en": "selecting the target figure against a cluttered background"}, "means": {"az": "Fiqur-fon fərqləndirmə qarışıq görüntüdə lazımi şeyi seçməkdir. Rəsmdə, kitabda və gündəlik axtarışda lazımdır.", "ru": "Различение фигуры и фона — это выделение нужного на сложном изображении. Необходимо при рисовании, чтении и повседневном поиске.", "en": "Figure-ground discrimination is picking out the relevant item in a cluttered image. It is needed in drawing, reading and everyday searching."}, "looks": {"az": "Uşaq qarışıq şəkildə lazım olan fiquru tapmır, diqqətsiz seçim edir.", "ru": "Ребёнок не находит нужную фигуру среди помех, выбирает невнимательно.", "en": "The child does not find the needed figure in a cluttered picture and chooses carelessly."}, "support": {"az": "«Gizli şəkil» və «tap və göstər» oyunları, əşya qarışığında müəyyən oyuncağı axtarmaq.", "ru": "Игры «скрытая картинка» и «найди и покажи», поиск определённой игрушки среди множества предметов.", "en": "\"Hidden picture\" and \"find and point\" games, and searching for a particular toy among many objects."}}, {"id": "d2", "title": {"az": "Forma tamamlama", "ru": "Завершение формы", "en": "Form Completion"}, "task": {"az": "Uşaq parçalanmış şəkilin hissələrini yerinə qoyub bütövləşdirir.", "ru": "Ребёнок складывает части разрезанного изображения в целое.", "en": "The child puts together the parts of a fragmented picture to make a whole."}, "items": [{"id": "d2i1", "t": {"az": "Hissələri birləşdirib bütöv forma qurmaqda çətinlik çəkir", "ru": "Испытывает трудности с объединением частей в целую форму", "en": "Has difficulty combining parts into a whole form"}}, {"id": "d2i2", "t": {"az": "Natamam formanı tanımaqda çətinlik çəkir", "ru": "Испытывает трудности с узнаванием незавершённой формы", "en": "Has difficulty recognizing an incomplete form"}}, {"id": "d2i3", "t": {"az": "Hissəni qoyarkən çox sınaq-səhv edir", "ru": "Много действует методом проб и ошибок при размещении части", "en": "Relies heavily on trial and error when placing a piece"}}], "mean": {"az": "parçalardan bütöv forma yığmaq", "ru": "сборка целой формы из частей", "en": "assembling a whole shape from parts"}, "means": {"az": "Forma tamamlama hissələrdən bütöv obraz yığmaqdır. Məkan təsəvvürü və tapmaca bacarığı ilə bağlıdır.", "ru": "Завершение формы — это сборка целого образа из частей. Связано с пространственным представлением и умением собирать пазлы.", "en": "Form completion is assembling a whole image from parts. It is linked to spatial visualization and puzzle-solving skill."}, "looks": {"az": "Uşaq parçaları birləşdirməkdə çətinlik çəkir, hissələri yerinə qoya bilmir.", "ru": "Ребёнку трудно соединять фрагменты, он не может поставить части на место.", "en": "The child has difficulty joining pieces and cannot put the parts in place."}, "support": {"az": "Sadə tapmaca, kəsilmiş şəkil və tangram oyunları ilə tədricən məşq edin.", "ru": "Постепенно тренируйтесь на простых пазлах, разрезных картинках и в играх с танграмом.", "en": "Practice gradually with simple puzzles, cut-up pictures and tangram games."}}, {"id": "d3", "title": {"az": "Təsnifat və analogiya", "ru": "Классификация и аналогии", "en": "Classification and Analogies"}, "task": {"az": "Uşaq kartları oxşarlığına görə qruplara ayırır və «bu nə kimidir, bu da onun kimi» tipli cütləri tamamlayır.", "ru": "Ребёнок группирует карточки по сходству и дополняет пары по принципу «это относится к тому так же, как это к тому».", "en": "The child sorts cards into groups by similarity and completes pairs of the type \"this goes with that as this goes with what?\""}, "items": [{"id": "d3i1", "t": {"az": "Əşyaları qrupa ayırmaqda çətinlik çəkir", "ru": "Испытывает трудности с группировкой предметов", "en": "Has difficulty grouping objects"}}, {"id": "d3i2", "t": {"az": "İki cütün eyni qaydaya uyğun olduğunu görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением того, что две пары подчиняются одному правилу", "en": "Has difficulty seeing that two pairs follow the same rule"}}, {"id": "d3i3", "t": {"az": "Ortaq cəhəti tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с поиском общего признака", "en": "Has difficulty finding the shared feature"}}], "mean": {"az": "qruplaşdırmaq və oxşar əlaqəni tapmaq", "ru": "группировка и нахождение сходной связи", "en": "grouping and finding a similar relationship"}, "means": {"az": "Qruplaşdırma və analogiya oxşar əlaqəni tapmaqdır. Təsnifat bacarığı öyrənmə və düşüncənin əsasıdır.", "ru": "Классификация и аналогия — нахождение сходной связи. Умение классифицировать лежит в основе обучения и мышления.", "en": "Classification and analogy involve finding a similar relationship. Classification skill is the basis of learning and thinking."}, "looks": {"az": "Uşaq əşyaları qruplara ayırmır, oxşarlığı görmür.", "ru": "Ребёнок не разделяет предметы на группы, не видит сходства.", "en": "The child does not sort objects into groups and does not see similarity."}, "support": {"az": "Şəkil kartları ilə rəng, forma, heyvan-meyvə kimi qruplara ayırma oyunları.", "ru": "Игры на сортировку карточек с картинками по группам: цвет, форма, животные и фрукты.", "en": "Sorting games with picture cards by groups such as color, shape, animals and fruit."}}, {"id": "d4", "title": {"az": "Ardıcıl sıralama", "ru": "Последовательный порядок", "en": "Sequential Order"}, "task": {"az": "Uşaq kartları məntiqi sıra ilə düzür və çatışmayan növbəti kartı seçir.", "ru": "Ребёнок раскладывает карточки в логическом порядке и выбирает недостающую следующую карточку.", "en": "The child arranges cards in logical order and selects the missing next card."}, "items": [{"id": "d4i1", "t": {"az": "Kartları məntiqi sıra ilə düzməkdə çətinlik çəkir", "ru": "Испытывает трудности с раскладыванием карточек в логическом порядке", "en": "Has difficulty arranging cards in logical order"}}, {"id": "d4i2", "t": {"az": "Sıranın qaydasını tapmaqda çətinlik çəkir", "ru": "Испытывает трудности с выявлением закономерности последовательности", "en": "Has difficulty finding the rule of the sequence"}}, {"id": "d4i3", "t": {"az": "Növbəti kartı proqnozlaşdırmaqda çətinlik çəkir", "ru": "Испытывает трудности с предсказанием следующей карточки", "en": "Has difficulty predicting the next card"}}], "mean": {"az": "ardıcıllıqda növbəti elementi tapmaq", "ru": "нахождение следующего элемента в последовательности", "en": "finding the next element in a sequence"}, "means": {"az": "Ardıcıllıq növbəti elementi tapmaqdır. Məntiqi düşünmə və proqnozlaşdırma bacarığı ilə bağlıdır.", "ru": "Последовательность — это нахождение следующего элемента. Связана с логическим мышлением и способностью к прогнозированию.", "en": "Sequencing is finding the next element. It is linked to logical thinking and the ability to predict."}, "looks": {"az": "Uşaq ardıcıllığı görmür, növbəti kartı təsadüfi seçir.", "ru": "Ребёнок не видит последовательности, выбирает следующую карточку наугад.", "en": "The child does not see the sequence and picks the next card at random."}, "support": {"az": "Kartlarla hekayə ardıcıllığı qurma, «sonra nə gəlir?» sualı.", "ru": "Составление последовательности событий из карточек, вопрос «что будет дальше?».", "en": "Building story sequences with cards, and the question \"what comes next?\""}}, {"id": "d5", "title": {"az": "Vizual naxışlar", "ru": "Зрительные паттерны", "en": "Visual Patterns"}, "task": {"az": "Uşaq təkrarlanan naxışın davamını kartlarla qurur.", "ru": "Ребёнок продолжает повторяющийся узор с помощью карточек.", "en": "The child continues a repeating pattern with cards."}, "items": [{"id": "d5i1", "t": {"az": "Naxışın təkrar qaydasını görməkdə çətinlik çəkir", "ru": "Испытывает трудности с выявлением правила повторения узора", "en": "Has difficulty seeing the repeating rule of the pattern"}}, {"id": "d5i2", "t": {"az": "Naxışı doğru davam etdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с правильным продолжением узора", "en": "Has difficulty continuing the pattern correctly"}}, {"id": "d5i3", "t": {"az": "Naxışın bir neçə cəhətini birlikdə nəzərə almaqda çətinlik çəkir", "ru": "Испытывает трудности с одновременным учётом нескольких признаков узора", "en": "Has difficulty attending to several features of the pattern at once"}}], "mean": {"az": "naxışı tanımaq və davam etdirmək", "ru": "узнавание и продолжение узора", "en": "recognizing and continuing a pattern"}, "means": {"az": "Naxışı tanımaq və davam etdirmək qanunauyğunluğu görməkdir. Riyaziyyatın əsasıdır.", "ru": "Узнавание и продолжение узора — это видение закономерности. Основа математики.", "en": "Recognizing and continuing a pattern is seeing a regularity. It is a foundation of mathematics."}, "looks": {"az": "Uşaq təkrar edən naxışı görmür, davamını qura bilmir.", "ru": "Ребёнок не видит повторяющийся узор, не может построить его продолжение.", "en": "The child does not see the repeating pattern and cannot build its continuation."}, "support": {"az": "Muncuq və kubları rəng və forma sırası ilə düzmə oyunları.", "ru": "Игры с выкладыванием бусин и кубиков в последовательности цвета и формы.", "en": "Games of arranging beads and blocks in sequences of color and shape."}}, {"id": "d6", "title": {"az": "Davamlı diqqət", "ru": "Устойчивое внимание", "en": "Attention Sustained"}, "task": {"az": "Uşaq kartda hədəf şəkilləri vaxt məhdud olduqda cərgələr üzrə işarələyir. Sekundomer lazımdır.", "ru": "Ребёнок отмечает на карточке целевые изображения по рядам с ограничением по времени. Нужен секундомер.", "en": "Within a time limit, the child marks the target pictures row by row on a card. A stopwatch is needed."}, "items": [{"id": "d6i1", "t": {"az": "Tapşırıq boyu diqqətini saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением внимания на протяжении задания", "en": "Has difficulty sustaining attention throughout the task"}}, {"id": "d6i2", "t": {"az": "Hədəfləri ardıcıl seçməkdə çətinlik çəkir", "ru": "Испытывает трудности с последовательным выбором целей", "en": "Has difficulty selecting targets consistently"}}, {"id": "d6i3", "t": {"az": "Ətrafdakı səs və hərəkətlərə yayınır", "ru": "Отвлекается на звуки и движения вокруг", "en": "Is distracted by surrounding sounds and movements"}}], "mean": {"az": "uzun müddət diqqəti saxlamaq", "ru": "удерживание внимания в течение длительного времени", "en": "sustaining attention over a long period"}, "means": {"az": "Davamlı diqqət tapşırıq boyu fokusu saxlamaqdır. Dərs və oyunda uğur üçün lazımdır.", "ru": "Устойчивое внимание — удержание фокуса на протяжении всего задания. Необходимо для успеха на занятиях и в игре.", "en": "Sustained attention is keeping focus throughout a task. It is needed for success in lessons and play."}, "looks": {"az": "Uşağın diqqəti tez yayınır, tapşırığı yarımçıq qoyur.", "ru": "Внимание ребёнка быстро рассеивается, он оставляет задание незавершённым.", "en": "The child's attention is quickly distracted and tasks are left unfinished."}, "support": {"az": "Qısa fəaliyyətlərlə başlayın, vaxtı tədricən uzadın, vizual taymerdən istifadə edin.", "ru": "Начинайте с коротких занятий, постепенно увеличивайте время, используйте визуальный таймер.", "en": "Start with short activities, extend the time gradually and use a visual timer."}}, {"id": "d7", "title": {"az": "İrəli yaddaş", "ru": "Прямая память", "en": "Forward Memory"}, "task": {"az": "Mütəxəssis şəkillərə sıra ilə toxunur, uşaq eyni sırada təkrarlayır.", "ru": "Специалист по очереди касается картинок, ребёнок повторяет в том же порядке.", "en": "The examiner touches pictures in sequence and the child repeats the sequence in the same order."}, "items": [{"id": "d7i1", "t": {"az": "Şəkillərin sırasını yadda saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с запоминанием порядка картинок", "en": "Has difficulty remembering the order of the pictures"}}, {"id": "d7i2", "t": {"az": "Eyni sırada təkrarlamaqda çətinlik çəkir", "ru": "Испытывает трудности с повторением в том же порядке", "en": "Has difficulty repeating them in the same order"}}, {"id": "d7i3", "t": {"az": "Şəkil sayı artanda sıranı qarışdırır", "ru": "Путает порядок, когда количество картинок увеличивается", "en": "Mixes up the order as the number of pictures increases"}}], "mean": {"az": "əşyaları eyni sıra ilə xatırlamaq", "ru": "запоминание предметов в том же порядке", "en": "remembering objects in the same order"}, "means": {"az": "İrəli yaddaş görülən şeyləri eyni sıra ilə xatırlamaqdır. Göstərişləri yadda saxlamaq üçün əsasdır.", "ru": "Прямая память — запоминание увиденного в том же порядке. Основа для запоминания инструкций.", "en": "Forward memory is remembering what was seen in the same order. It is a basis for remembering instructions."}, "looks": {"az": "Uşaq şəkillərin sırasını xatırlamır, ardıcıllığı qarışdırır.", "ru": "Ребёнок не помнит порядок картинок, путает последовательность.", "en": "The child does not remember the order of the pictures and mixes up the sequence."}, "support": {"az": "Kartları göstərib eyni sırada təkrarlama oyunları, sadə yaddaş oyunları.", "ru": "Игры: показать карточки и повторить в том же порядке, простые игры на память.", "en": "Games of showing cards and repeating them in the same order, and simple memory games."}}, {"id": "d8", "title": {"az": "Tərs yaddaş", "ru": "Обратная память", "en": "Reverse Memory"}, "task": {"az": "Mütəxəssis şəkillərə sıra ilə toxunur, uşaq tərs sırada təkrarlayır.", "ru": "Специалист по очереди касается картинок, ребёнок повторяет в обратном порядке.", "en": "The examiner touches pictures in sequence and the child repeats the sequence in reverse order."}, "items": [{"id": "d8i1", "t": {"az": "Sıranı tərsinə çevirməkdə çətinlik çəkir", "ru": "Испытывает трудности с обращением порядка", "en": "Has difficulty reversing the order"}}, {"id": "d8i2", "t": {"az": "Məlumatı yadda saxlayıb eyni zamanda dəyişməkdə çətinlik çəkir", "ru": "Испытывает трудности с одновременным удержанием и преобразованием информации", "en": "Has difficulty holding information in mind and transforming it at the same time"}}, {"id": "d8i3", "t": {"az": "Şəkil sayı artanda tapşırığı yarımçıq qoyur", "ru": "Прекращает выполнение задания, когда количество картинок увеличивается", "en": "Abandons the task as the number of pictures increases"}}], "mean": {"az": "əşyaları tərs sıra ilə xatırlamaq", "ru": "запоминание предметов в обратном порядке", "en": "remembering objects in reverse order"}, "means": {"az": "Tərs yaddaş məlumatı saxlayıb dəyişdirməyi tələb edir. İş yaddaşı və çevik düşünmə bacarığı ilə bağlıdır.", "ru": "Обратная память требует удерживать информацию и преобразовывать её. Связана с рабочей памятью и гибким мышлением.", "en": "Reverse memory requires holding information and manipulating it. It is linked to working memory and flexible thinking."}, "looks": {"az": "Uşaq sıranı tərsinə çevirməkdə çətinlik çəkir, ilk sırada qalır.", "ru": "Ребёнку трудно перевернуть порядок, он остаётся на прямой последовательности.", "en": "The child has difficulty reversing the order and stays with the forward sequence."}, "support": {"az": "Az sayda kartla başlayın, «axırdan başa» təkrarlama oyunları qurun.", "ru": "Начинайте с небольшого числа карточек, организуйте игры на повторение «с конца к началу».", "en": "Start with a small number of cards and set up repetition games \"from the end to the beginning\"."}}, {"id": "d9", "title": {"az": "Bölünmüş diqqət", "ru": "Распределённое внимание", "en": "Attention Divided"}, "task": {"az": "Uşaq iki tapşırığı eyni vaxtda edir: biri ilə şəkilləri qoyur, digərinə baxıb və ya cavab verir.", "ru": "Ребёнок выполняет два задания одновременно: в одном раскладывает картинки, одновременно следя за другим или отвечая на него.", "en": "The child performs two tasks at the same time: places pictures in one while watching or responding to the other."}, "items": [{"id": "d9i1", "t": {"az": "İki tapşırıq arasında diqqəti bölməkdə çətinlik çəkir", "ru": "Испытывает трудности с распределением внимания между двумя заданиями", "en": "Has difficulty dividing attention between two tasks"}}, {"id": "d9i2", "t": {"az": "Hər iki tapşırıqda sürət və dəqiqliyi saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением скорости и точности в обоих заданиях", "en": "Has difficulty maintaining speed and accuracy on both tasks"}}, {"id": "d9i3", "t": {"az": "Bir tapşırıqdan digərinə keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с переключением с одного задания на другое", "en": "Has difficulty switching from one task to the other"}}], "mean": {"az": "iki tapşırığa eyni anda diqqət", "ru": "распределение внимания между двумя заданиями", "en": "dividing attention between two tasks"}, "means": {"az": "Bölünmüş diqqət iki işə eyni anda fikir verməkdir. Gündəlik həyatda və sinifdə vacibdir.", "ru": "Распределённое внимание — это внимание к двум делам одновременно. Важно в повседневной жизни и в классе.", "en": "Divided attention is attending to two things at the same time. It matters in daily life and in the classroom."}, "looks": {"az": "Uşaq iki işi birlikdə edə bilmir, birini buraxır.", "ru": "Ребёнок не может выполнять два дела вместе, одно из них бросает.", "en": "The child cannot do two things together and drops one of them."}, "support": {"az": "Sadə iki addımlı oyunlar (top tutarkən say), tədricən mürəkkəbləşdirin.", "ru": "Простые двухшаговые игры (считать, ловя мяч), постепенно усложняйте.", "en": "Simple two-step games (counting while catching a ball), made harder gradually."}}, {"id": "d10", "title": {"az": "Qeyri-verbal əməkdaşlıq (bütün seansa aid)", "ru": "Невербальное сотрудничество (вся сессия)", "en": "Nonverbal Cooperation (whole session)"}, "task": {"az": "Ayrıca tapşırıq yoxdur. Göstərişlər jest və nümunə ilə verilir, uşağın davranışına baxılır.", "ru": "Отдельного задания нет. Инструкции даются жестами и на примере, наблюдают за поведением ребёнка.", "en": "There is no separate task. Instructions are given by gesture and demonstration, and the child's behavior is observed."}, "items": [{"id": "d10i1", "t": {"az": "Jestlə verilən göstərişi başa düşməkdə çətinlik çəkir", "ru": "Испытывает трудности с пониманием инструкции, данной жестом", "en": "Has difficulty understanding an instruction given by gesture"}}, {"id": "d10i2", "t": {"az": "Tapşırığa davam etməkdə çətinlik çəkir", "ru": "Испытывает трудности с продолжением выполнения задания", "en": "Has difficulty persisting with the task"}}, {"id": "d10i3", "t": {"az": "Çətin tapşırıqda sakitliyini qorumaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением спокойствия при трудном задании", "en": "Has difficulty staying calm on a hard task"}}], "mean": {"az": "sözsüz göstərişlərə uyğun davranmaq", "ru": "соответствие невербальным указаниям", "en": "responding to nonverbal instructions"}, "means": {"az": "Sözsüz göstərişlərə uyğunlaşmaq uşağın jest və nümunəni anlamasını göstərir. Bu, bütün seansa aid müşahidədir.", "ru": "Следование невербальным указаниям показывает понимание ребёнком жестов и образца. Это наблюдение относится ко всему сеансу.", "en": "Following nonverbal instructions shows the child's understanding of gestures and models. This is an observation covering the whole session."}, "looks": {"az": "Uşaq jestlə verilən göstərişi başa düşmür, nümunəni təqlid etmir.", "ru": "Ребёнок не понимает указание, данное жестом, и не подражает образцу.", "en": "The child does not understand an instruction given by gesture and does not imitate a model."}, "support": {"az": "Göstərişi jest və nümunə ilə verin, uşağın cavabını gözləyin və hər cəhdi təriflə.", "ru": "Давайте указание жестом и образцом, ждите ответа ребёнка и хвалите каждую попытку.", "en": "Give the instruction with a gesture and a model, wait for the child's response and praise every attempt."}}], "specialist": [{"az": "Qeyri-verbal nəticələri dil əsaslı ölçmələrlə müqayisə edin.", "ru": "Сравните невербальные результаты с речевыми измерениями.", "en": "Compare nonverbal results with language-based measures."}, {"az": "Güclü vizual idrakı öyrənmə strategiyasına çevirin.", "ru": "Превратите сильное зрительное мышление в стратегию обучения.", "en": "Translate strong visual reasoning into a learning strategy."}, {"az": "Eşitmə/dil amillərini ayrı-ayrılıqda qiymətləndirməyi tövsiyə edin.", "ru": "Рекомендуйте отдельно оценить слух/речь.", "en": "Recommend separately assessing hearing/language factors."}], "parentIntro": {"az": "Bu test uşağınızın danışmadan da güclü düşünə bildiyini göstərir. Vizual güclü tərəfləri dəstəkləyin.", "ru": "Этот тест показывает, что ребёнок мыслит сильно и без слов. Поддерживайте зрительные сильные стороны.", "en": "This test shows your child can reason strongly without speaking. Support their visual strengths."}, "parentTips": [{"az": "Göstərişləri sözlə yanaşı şəkil və jestlə verin.", "ru": "Давайте инструкции картинками и жестами наряду со словами.", "en": "Give instructions with pictures and gestures alongside words."}, {"az": "Tapmaca, lego və naxış oyunları üçün vaxt ayırın.", "ru": "Выделяйте время на пазлы, лего и узоры.", "en": "Make time for puzzles, building blocks and patterns."}, {"az": "Səbri tərifləyin — düşünmə vaxtı vacibdir.", "ru": "Хвалите терпение — время на размышление важно.", "en": "Praise patience — thinking time matters."}], "games": [{"az": "Naxış davam etdirmə: rəngli bloklarla sıra qurun.", "ru": "Продолжение узора: стройте ряд из цветных блоков.", "en": "Pattern continuation: build a row with colored blocks."}, {"az": "Tapmaca yarışı: çətinliyi tədricən artırın.", "ru": "Гонка пазлов: постепенно увеличивайте сложность.", "en": "Puzzle race: gradually increase difficulty."}, {"az": "'Tap görüm' vizual yaddaş oyunu.", "ru": "Зрительная игра памяти «угадай».", "en": "'Guess what' visual memory game."}]}, "sp2": {"id": "sp2", "name": "Sensory Profile 2", "full": {"az": "Sensor Profil 2", "ru": "Сенсорный профиль 2", "en": "Sensory Profile 2"}, "age": {"az": "Doğuşdan ~14 yaşadək (formalar üzrə)", "ru": "От рождения до ~14 лет (по формам)", "en": "Birth to ~14 years (by form)"}, "summary": {"az": "Uşağın gündəlik həyatda sensor uyaranlara necə reaksiya verdiyini qiymətləndirir. Erqoterapiya və sensor müdaxilə planlaması üçün xüsusilə dəyərlidir.", "ru": "Оценивает, как ребёнок реагирует на сенсорные стимулы в повседневной жизни. Особенно ценен для эрготерапии и сенсорного вмешательства.", "en": "Assesses how the child responds to sensory input in daily life. Especially valuable for occupational therapy and sensory intervention planning."}, "advantages": [{"az": "Sensor müdaxiləni dəqiq hədəfləyir", "ru": "Точно нацеливает сенсорное вмешательство", "en": "Precisely targets sensory intervention"}, {"az": "Gündəlik davranışı sensor baxımdan izah edir", "ru": "Объясняет повседневное поведение через сенсорику", "en": "Explains daily behavior through a sensory lens"}, {"az": "Ev və məktəb mühitinə tövsiyələr verir", "ru": "Даёт рекомендации для дома и школы", "en": "Provides recommendations for home and school"}, {"az": "Valideyn üçün başa düşülən profil yaradır", "ru": "Создаёт понятный родителю профиль", "en": "Creates a parent-friendly profile"}], "instruction": {"howto": [{"az": "Uşağı gündəlik mühitdə müşahidə edən şəxslə doldurun.", "ru": "Заполняйте с тем, кто наблюдает ребёнка в быту.", "en": "Complete with someone who observes the child in daily life."}, {"az": "Hər bənddə davranışın tezliyini qeyd edin.", "ru": "Отмечайте частоту поведения по каждому пункту.", "en": "Record the frequency of the behavior for each item."}, {"az": "Müxtəlif mühitləri (ev, məktəb) nəzərə alın.", "ru": "Учитывайте разные среды (дом, школа).", "en": "Consider different settings (home, school)."}], "methods": [{"az": "Valideyn/müəllim hesabat anketi", "ru": "Анкета-отчёт родителя/учителя", "en": "Parent/teacher report questionnaire"}, {"az": "Tezlik əsaslı qiymətləndirmə", "ru": "Оценка на основе частоты", "en": "Frequency-based rating"}], "scoring": [{"az": "Cavablar dörd sensor kvadrant üzrə yığılır.", "ru": "Ответы сводятся по четырём сенсорным квадрантам.", "en": "Responses aggregate into four sensory quadrants."}, {"az": "Kəsim diapazonları yalnız rəsmi norma ilə müəyyən edilir.", "ru": "Пороговые диапазоны определяются только по официальным нормам.", "en": "Cutoff ranges are determined only by official norms."}]}, "official": [{"label": {"az": "Axtarış (Seeking) balı", "ru": "Балл поиска (Seeking)", "en": "Seeking score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Qaçınma (Avoiding) balı", "ru": "Балл избегания (Avoiding)", "en": "Avoiding score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Həssaslıq (Sensitivity) balı", "ru": "Балл чувствительности (Sensitivity)", "en": "Sensitivity score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}, {"label": {"az": "Qeydiyyat (Registration) balı", "ru": "Балл регистрации (Registration)", "en": "Registration score"}, "hint": {"az": "rəsmi norma", "ru": "официальная норма", "en": "official norm"}}], "domains": [{"id": "d1", "title": {"az": "Eşitmə emalı", "ru": "Слуховая обработка", "en": "Auditory Processing"}, "task": {"az": "Valideynə sual: uşaq gözlənilməz səslərə (tozsoran, fen, zəng) necə reaksiya verir? Səs-küylü yerdə nə edir?", "ru": "Вопрос родителю: как ребёнок реагирует на неожиданные звуки (пылесос, фен, звонок)? Что он делает в шумном месте?", "en": "Question to the parent: how does the child react to unexpected sounds (vacuum cleaner, hair dryer, bell)? What does the child do in a noisy place?"}, "items": [{"id": "d1i1", "t": {"az": "Gözlənilməz səslərə həddən artıq güclü reaksiya verir (qulaqlarını tutur, ağlayır)", "ru": "Чрезмерно сильно реагирует на неожиданные звуки (закрывает уши, плачет)", "en": "Reacts excessively to unexpected sounds (covers ears, cries)"}}, {"id": "d1i2", "t": {"az": "Səs-küylü yerdə diqqətini toplamaqda çətinlik çəkir", "ru": "Испытывает трудности с концентрацией в шумном месте", "en": "Has difficulty concentrating in a noisy place"}}, {"id": "d1i3", "t": {"az": "Adı çağırılanda və ya səs eşidiləndə reaksiya vermir", "ru": "Не реагирует, когда его зовут по имени или слышен звук", "en": "Does not respond when called by name or when a sound is heard"}}], "mean": {"az": "səslərə reaksiya", "ru": "реакция на звуки", "en": "responses to sounds"}, "means": {"az": "Eşitmə emalı uşağın səslərə reaksiyasıdır. Səs-küy və səssizlik şəraitində rahatlıq üçün vacibdir.", "ru": "Слуховая обработка — это реакция ребёнка на звуки. Важна для комфорта в шуме и в тишине.", "en": "Auditory processing is the child's response to sounds. It is important for comfort in noise and in quiet."}, "looks": {"az": "Valideyn uşağın gözlənilməz səslərdən qulağını tutduğunu və ya səsə az reaksiya verdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок закрывает уши при неожиданных звуках или слабо реагирует на звук.", "en": "The parent may notice that the child covers the ears at unexpected sounds or responds little to sound."}, "support": {"az": "Səs-küylü mühitə hazırlayın, sakit künc təşkil edin, səsə tədricən alışdırın.", "ru": "Готовьте к шумной обстановке, организуйте тихий уголок, постепенно приучайте к звуку.", "en": "Prepare the child for noisy settings, set up a quiet corner and gradually accustom the child to sound."}}, {"id": "d2", "title": {"az": "Görmə emalı", "ru": "Зрительная обработка", "en": "Visual Processing"}, "task": {"az": "Valideynə sual: parlaq işıqda, çox oyuncaq olan otaqda və ya hərəkətli şeylərə baxanda nə olur?", "ru": "Вопрос родителю: что происходит при ярком свете, в комнате с большим количеством игрушек или при взгляде на движущиеся предметы?", "en": "Question to the parent: what happens in bright light, in a room with many toys, or when looking at moving objects?"}, "items": [{"id": "d2i1", "t": {"az": "Parlaq işıqdan narahat olur (gözünü qısır, üzünü çevirir)", "ru": "Яркий свет вызывает дискомфорт (щурится, отворачивается)", "en": "Is bothered by bright light (squints, turns away)"}}, {"id": "d2i2", "t": {"az": "Çox əşya olan yerdə tez yorulur", "ru": "Быстро утомляется там, где много предметов", "en": "Tires quickly in places with many objects"}}, {"id": "d2i3", "t": {"az": "Hərəkətli və ya fırlanan əşyalara həddindən artıq cəlb olunur", "ru": "Чрезмерно притягивается к движущимся или вращающимся предметам", "en": "Is excessively drawn to moving or spinning objects"}}], "mean": {"az": "işıq və vizual təsirlərə reaksiya", "ru": "реакция на свет и зрительные стимулы", "en": "responses to light and visual stimuli"}, "means": {"az": "Görmə emalı işıq və vizual təsirlərə reaksiyadır. Çoxlu oyuncaq, parlaq işıq uşağa təsir edə bilər.", "ru": "Зрительная обработка — это реакция на свет и зрительные стимулы. Множество игрушек и яркий свет могут влиять на ребёнка.", "en": "Visual processing is the response to light and visual stimuli. Many toys and bright light can affect the child."}, "looks": {"az": "Valideyn uşağın parlaq işıqdan narahat olduğunu və ya vizual detalları görmədiyini görə bilər.", "ru": "Родитель может замечать, что ребёнка беспокоит яркий свет или он не замечает зрительных деталей.", "en": "The parent may notice that the child is bothered by bright light or does not notice visual details."}, "support": {"az": "Otağı sadə saxlayın, oyuncaqları qutularda təşkil edin, işıq səviyyəsini tənzimləyin.", "ru": "Сохраняйте комнату простой, раскладывайте игрушки по коробкам, регулируйте уровень освещения.", "en": "Keep the room simple, organize toys in boxes and adjust the light level."}}, {"id": "d3", "title": {"az": "Toxunma emalı", "ru": "Тактильная обработка", "en": "Touch Processing"}, "task": {"az": "Valideynə sual: paltarın etiketinə, saç yuyulmasına, ayaqyalın gəzməyə və qucaqlanmağa necə reaksiya verir?", "ru": "Вопрос родителю: как ребёнок реагирует на бирки на одежде, мытьё головы, хождение босиком, объятия?", "en": "Question to the parent: how does the child react to clothing labels, hair washing, walking barefoot, and hugs?"}, "items": [{"id": "d3i1", "t": {"az": "Müəyyən parçalardan və ya toxunuşdan narahat olur", "ru": "Испытывает дискомфорт от определённых тканей или прикосновений", "en": "Is bothered by certain fabrics or touch"}}, {"id": "d3i2", "t": {"az": "Güclü sıxılma və ya təzyiq axtarır", "ru": "Ищет сильное сжатие или давление", "en": "Seeks strong squeezing or pressure"}}, {"id": "d3i3", "t": {"az": "Əlləri və ya ağzı ilə hər şeyə toxunmağa meyl edir", "ru": "Склонен трогать всё руками или ртом", "en": "Tends to touch everything with hands or mouth"}}], "mean": {"az": "toxunuşa, paltara, materiallara reaksiya", "ru": "реакция на прикосновения, одежду, материалы", "en": "responses to touch, clothing and materials"}, "means": {"az": "Toxunma emalı paltar, material və toxunuşa reaksiyadır. Gündəlik geyinmə və qulluqda rolu var.", "ru": "Тактильная обработка — это реакция на одежду, материалы и прикосновения. Играет роль при одевании и уходе.", "en": "Touch processing is the response to clothing, materials and touch. It plays a role in daily dressing and care."}, "looks": {"az": "Valideyn uşağın paltar etiketlərindən, saç yuyulmasından və ya qucaqlanmadan narahat olduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнка беспокоят ярлычки на одежде, мытьё головы или объятия.", "en": "The parent may notice that the child is bothered by clothing tags, hair washing or hugs."}, "support": {"az": "Rahat, yumşaq paltar seçin, müxtəlif materialları oyunda tədricən tanıdın.", "ru": "Выбирайте удобную, мягкую одежду, постепенно знакомьте с разными материалами в игре.", "en": "Choose comfortable, soft clothing and gradually introduce different materials through play."}}, {"id": "d4", "title": {"az": "Hərəkət emalı", "ru": "Обработка движения", "en": "Movement Processing"}, "task": {"az": "Valideynə sual: yellənçək, fırlanma, təpədən sürüşmə kimi oyunlara münasibəti necədir?", "ru": "Вопрос родителю: как ребёнок относится к качелям, кружению, скольжению с горки?", "en": "Question to the parent: how does the child respond to swings, spinning, and sliding down a slide?"}, "items": [{"id": "d4i1", "t": {"az": "Fırlanma, yellənmə kimi hərəkətləri çox axtarır", "ru": "Активно ищет кружение, раскачивание и подобные движения", "en": "Strongly seeks spinning, swinging, and similar movements"}}, {"id": "d4i2", "t": {"az": "Hərəkətli oyunlarda ehtiyatlı və ya qorxaqdır", "ru": "Осторожен или боязлив в подвижных играх", "en": "Is cautious or fearful in active play"}}, {"id": "d4i3", "t": {"az": "Tarazlığı saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с сохранением равновесия", "en": "Has difficulty keeping balance"}}], "mean": {"az": "hərəkət və tarazlıq hissi", "ru": "ощущение движения и равновесия", "en": "sense of movement and balance"}, "means": {"az": "Hərəkət emalı yelləmə, fırlanma, sürüşmə kimi hərəkətlərə reaksiyadır. Tarazlıq və fəallıq üçün vacibdir.", "ru": "Вестибулярная обработка — это реакция на движения: качание, вращение, скольжение. Важна для равновесия и активности.", "en": "Movement processing is the response to movements such as swinging, spinning and sliding. It is important for balance and activity."}, "looks": {"az": "Valideyn uşağın hərəkətləri həddən artıq axtardığını və ya hərəkətdən qorxduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнок чрезмерно ищет движения или боится движения.", "en": "The parent may notice that the child seeks movement excessively or is afraid of movement."}, "support": {"az": "Təhlükəsiz hərəkət oyunları (yellənçək, yastıqdan keçid) təşkil edin, uşağın tempinə uyğun gedin.", "ru": "Организуйте безопасные игры с движением (качели, переход по подушкам), следуйте темпу ребёнка.", "en": "Set up safe movement games (swing, walking across cushions) and follow the child's pace."}}, {"id": "d5", "title": {"az": "Bədən mövqeyi", "ru": "Положение тела", "en": "Body Position"}, "task": {"az": "Valideynə sual: uşaq əşyalara və adamlara çırpılır? Qapını çırpır, əşyanı sındırır? Oturanda və yeriyəndə bədənini necə saxlayır?", "ru": "Вопрос родителю: сталкивается ли ребёнок с предметами и людьми? Хлопает ли дверью, ломает ли вещи? Как держит тело, когда сидит и ходит?", "en": "Question to the parent: does the child bump into objects and people? Does the child slam doors or break things? How does the child hold his or her body when sitting and walking?"}, "items": [{"id": "d5i1", "t": {"az": "Bədən mövqeyini az hiss edir (tez-tez yıxılır, əşyalara dəyir)", "ru": "Слабо ощущает положение тела (часто падает, задевает предметы)", "en": "Has a poor sense of body position (falls often, bumps into things)"}}, {"id": "d5i2", "t": {"az": "Əşyalara və adamlara çırpılır", "ru": "Сталкивается с предметами и людьми", "en": "Bumps into objects and people"}}, {"id": "d5i3", "t": {"az": "Gücünü tənzimləməkdə çətinlik çəkir (çox möhkəm tutur, çox bərk vurur)", "ru": "Испытывает трудности с регуляцией силы (слишком крепко держит, слишком сильно бьёт)", "en": "Has difficulty regulating force (grips too tightly, hits too hard)"}}], "mean": {"az": "bədən hissələrinin vəziyyətini hiss etmək", "ru": "ощущение положения частей тела", "en": "sense of the position of body parts"}, "means": {"az": "Bədən mövqeyi bədənin hissələrini hiss etməkdir. Koordinasiya və təhlükəsizlik üçün lazımdır.", "ru": "Положение тела — это ощущение частей тела. Необходимо для координации и безопасности.", "en": "Body position is the sense of where body parts are. It is needed for coordination and safety."}, "looks": {"az": "Valideyn uşağın əşyalara çırpıldığını, tez-tez yıxıldığını və ya güc tənzimləməkdə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок натыкается на предметы, часто падает или с трудом регулирует силу.", "en": "The parent may notice that the child bumps into objects, falls often or has difficulty regulating force."}, "support": {"az": "Ağır əşya daşıma, itələmə, sıxma oyunları və məsafə hissi üçün maneə yolları.", "ru": "Игры с переноской тяжёлых предметов, толканием, сжиманием и полосы препятствий для чувства расстояния.", "en": "Games of carrying heavy objects, pushing and squeezing, and obstacle courses for a sense of distance."}}, {"id": "d6", "title": {"az": "Oral (dad və qoxu)", "ru": "Оральная обработка (вкус и запах)", "en": "Oral Sensory Processing (taste and smell)"}, "task": {"az": "Valideynə sual: yeni yeməklərə, yeməyin teksturasına və qoxulara necə reaksiya verir?", "ru": "Вопрос родителю: как ребёнок реагирует на новую еду, текстуру пищи и запахи?", "en": "Question to the parent: how does the child respond to new foods, food textures, and smells?"}, "items": [{"id": "d6i1", "t": {"az": "Yeni dadlardan və qoxulardan imtina edir", "ru": "Отказывается от новых вкусов и запахов", "en": "Refuses new tastes and smells"}}, {"id": "d6i2", "t": {"az": "Müəyyən teksturadan (yumşaq, lopa) imtina edir", "ru": "Отказывается от определённых текстур (мягкие, комковатые)", "en": "Refuses certain textures (soft, lumpy)"}}, {"id": "d6i3", "t": {"az": "Yeyilməyən əşyaları ağzına aparır", "ru": "Берёт в рот несъедобные предметы", "en": "Puts inedible objects in the mouth"}}], "mean": {"az": "dad, qoxu və ağıza aid reaksiyalar", "ru": "реакции на вкус, запах и ощущения во рту", "en": "responses to taste, smell and mouth sensations"}, "means": {"az": "Oral emal dad, qoxu və ağız hissləridir. Qidalanma və gündəlik rahatlıq üçün vacibdir.", "ru": "Оральная обработка — это вкус, запах и ощущения во рту. Важна для питания и повседневного комфорта.", "en": "Oral processing involves taste, smell and sensations in the mouth. It is important for eating and daily comfort."}, "looks": {"az": "Valideyn uşağın yeni dad və teksturalardan imtina etdiyini və ya qoxudan narahat olduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнок отказывается от новых вкусов и текстур или его беспокоят запахи.", "en": "The parent may notice that the child refuses new tastes and textures or is bothered by smells."}, "support": {"az": "Yeni yeməkləri kiçik hissələrlə və oyun şəraitində təqdim edin, təzyiq göstərməyin.", "ru": "Предлагайте новую еду маленькими порциями и в игровой обстановке, не давите.", "en": "Offer new foods in small portions and in a playful setting, without pressure."}}, {"id": "d7", "title": {"az": "Davranış reaksiyaları", "ru": "Поведенческие реакции", "en": "Behavioral Responses"}, "task": {"az": "Valideynə sual: səs-küylü, izdihamlı və ya yeni yerdə uşağın davranışı necə dəyişir?", "ru": "Вопрос родителю: как меняется поведение ребёнка в шумном, людном или новом месте?", "en": "Question to the parent: how does the child's behavior change in a noisy, crowded, or new place?"}, "items": [{"id": "d7i1", "t": {"az": "Sensor yük artanda davranışı pozulur", "ru": "Поведение нарушается при возрастании сенсорной нагрузки", "en": "Behavior breaks down when sensory load increases"}}, {"id": "d7i2", "t": {"az": "Bir fəaliyyətdən digərinə keçməkdə çətinlik çəkir", "ru": "Испытывает трудности с переходом от одной деятельности к другой", "en": "Has difficulty moving from one activity to another"}}, {"id": "d7i3", "t": {"az": "Mühit dəyişəndə narahat olur", "ru": "Тревожится при смене обстановки", "en": "Becomes distressed when the environment changes"}}], "mean": {"az": "sensor təsirə davranışla cavab", "ru": "поведенческая реакция на сенсорные воздействия", "en": "behavioral responses to sensory input"}, "means": {"az": "Sensor təsirə davranışla cavab uşağın səs-küylü və yeni yerlərdə davranışının dəyişməsini göstərir.", "ru": "Поведенческая реакция на сенсорные воздействия показывает, как меняется поведение ребёнка в шумных и новых местах.", "en": "Behavioral responses to sensory input show how the child's behavior changes in noisy and new places."}, "looks": {"az": "Valideyn uşağın izdihamlı və ya səs-küylü yerdə davranışının pozulduğunu görə bilər.", "ru": "Родитель может замечать, что в людном или шумном месте поведение ребёнка нарушается.", "en": "The parent may notice that the child's behavior breaks down in a crowded or noisy place."}, "support": {"az": "Çətin yerlərə əvvəlcədən hazırlayın, sakitləşmə üçün sevimli əşya və fasilə verin.", "ru": "Готовьте к трудным местам заранее, берите любимый предмет для успокоения и делайте перерывы.", "en": "Prepare for difficult places in advance, bring a favorite calming item and take breaks."}}, {"id": "d8", "title": {"az": "Sosial-emosional", "ru": "Социально-эмоциональная сфера", "en": "Social-Emotional Responses"}, "task": {"az": "Valideynə sual: sensor narahatlıq olanda əhval-ruhiyyəsi dəyişir? Özünü sakitləşdirə bilir?", "ru": "Вопрос родителю: меняется ли настроение ребёнка при сенсорном дискомфорте? Умеет ли он успокаиваться сам?", "en": "Question to the parent: does the child's mood change with sensory discomfort? Can the child calm himself or herself?"}, "items": [{"id": "d8i1", "t": {"az": "Sensor narahatlıq əhvalına təsir edir", "ru": "Сенсорный дискомфорт влияет на настроение", "en": "Sensory discomfort affects mood"}}, {"id": "d8i2", "t": {"az": "Özünü sakitləşdirməkdə çətinlik çəkir", "ru": "Испытывает трудности с самоуспокоением", "en": "Has difficulty calming himself or herself"}}, {"id": "d8i3", "t": {"az": "Ya diqqət axtarır, ya da başqalarından uzaqlaşır", "ru": "Либо ищет внимания, либо отдаляется от других", "en": "Either seeks attention or withdraws from others"}}], "mean": {"az": "hissləri və sosial vəziyyəti idarə etmək", "ru": "управление чувствами и социальной ситуацией", "en": "managing feelings and social situations"}, "means": {"az": "Sensor mühit əhval-ruhiyyəyə təsir edə bilər. Hissləri və sosial vəziyyəti idarə etmək rahatlıq üçün lazımdır.", "ru": "Сенсорная среда может влиять на настроение. Управление чувствами и социальной ситуацией необходимо для комфорта.", "en": "The sensory environment can affect mood. Managing feelings and social situations is needed for comfort."}, "looks": {"az": "Valideyn uşağın sensor narahatlıq olanda əhval-ruhiyyəsinin pisləşdiyini və ya özünü sakitləşdirməkdə çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что при сенсорном дискомфорте настроение ребёнка ухудшается или ему трудно успокоиться.", "en": "The parent may notice that the child's mood worsens during sensory discomfort or that the child has difficulty calming down."}, "support": {"az": "Narahatlıq vəziyyətlərini birlikdə adlandırın, sakit künc və dərin nəfəs məşqləri təklif edin.", "ru": "Вместе называйте ситуации дискомфорта, предлагайте тихий уголок и упражнения на глубокое дыхание.", "en": "Name situations of discomfort together and offer a quiet corner and deep-breathing exercises."}}, {"id": "d9", "title": {"az": "Diqqət", "ru": "Внимание", "en": "Attention"}, "task": {"az": "Valideynə sual: dərs, oyun və ya yemək zamanı diqqəti dağılır? Yerində otura bilir?", "ru": "Вопрос родителю: рассеивается ли внимание ребёнка во время занятия, игры или еды? Может ли он усидеть на месте?", "en": "Question to the parent: is the child's attention scattered during lessons, play, or meals? Can the child stay seated?"}, "items": [{"id": "d9i1", "t": {"az": "Diqqəti asanlıqla yayınır", "ru": "Внимание легко отвлекается", "en": "Is easily distracted"}}, {"id": "d9i2", "t": {"az": "Tapşırığa diqqəti saxlamaqda çətinlik çəkir", "ru": "Испытывает трудности с удержанием внимания на задании", "en": "Has difficulty sustaining attention on a task"}}, {"id": "d9i3", "t": {"az": "Diqqətini saxlamaq üçün hərəkət edir", "ru": "Двигается, чтобы удерживать внимание", "en": "Moves in order to keep attention"}}], "mean": {"az": "sensor mühitdə diqqəti saxlamaq", "ru": "удерживание внимания в сенсорной среде", "en": "sustaining attention in a sensory environment"}, "means": {"az": "Sensor mühitdə diqqət dərs, oyun və yemək zamanı fokus saxlamaq bacarığıdır.", "ru": "Внимание в сенсорной среде — это умение сохранять фокус на занятиях, в игре и во время еды.", "en": "Attention in a sensory environment is the ability to keep focus during lessons, play and meals."}, "looks": {"az": "Valideyn uşağın diqqətinin asanlıqla yayındığını və yerində oturmaqda çətinlik çəkdiyini görə bilər.", "ru": "Родитель может замечать, что внимание ребёнка легко рассеивается и ему трудно усидеть на месте.", "en": "The parent may notice that the child's attention is easily distracted and that the child has difficulty staying seated."}, "support": {"az": "Mühiti sadələşdirin, qısa tapşırıqlar verin, fasilələrdə hərəkət imkanı yaradın.", "ru": "Упростите обстановку, давайте короткие задания, в перерывах предусмотрите возможность двигаться.", "en": "Simplify the environment, give short tasks and allow movement during breaks."}}, {"id": "d10", "title": {"az": "Axtarış kvadrantı", "ru": "Квадрант «поиск»", "en": "Seeking Quadrant"}, "task": {"az": "Valideynə sual: uşaq əlavə hərəkət, səs və ya toxunuş axtarır? Daim hərəkətdədir?", "ru": "Вопрос родителю: ищет ли ребёнок дополнительного движения, звука или прикосновения? Постоянно ли он в движении?", "en": "Question to the parent: does the child look for extra movement, sound, or touch? Is the child constantly on the move?"}, "items": [{"id": "d10i1", "t": {"az": "Əlavə sensor təsir axtarır", "ru": "Ищет дополнительные сенсорные впечатления", "en": "Seeks additional sensory input"}}, {"id": "d10i2", "t": {"az": "Daim hərəkətdə və fəaldır", "ru": "Постоянно в движении и активен", "en": "Is constantly moving and active"}}, {"id": "d10i3", "t": {"az": "Səs, toxunuş və ya hərəkətdən çox həzz alır", "ru": "Получает чрезмерное удовольствие от звука, прикосновения или движения", "en": "Takes great pleasure in sound, touch, or movement"}}], "mean": {"az": "güclü sensor təcrübə axtarmaq", "ru": "поиск интенсивных сенсорных впечатлений", "en": "seeking intense sensory experiences"}, "means": {"az": "Güclü sensor təcrübə axtarmaq uşağın əlavə hərəkət, səs və toxunuşa ehtiyacını göstərir.", "ru": "Поиск интенсивных сенсорных впечатлений показывает потребность ребёнка в дополнительных движениях, звуках и прикосновениях.", "en": "Seeking intense sensory experiences shows the child's need for extra movement, sound and touch."}, "looks": {"az": "Valideyn uşağın daim hərəkətdə olduğunu, səs-küy və toxunuş axtardığını görə bilər.", "ru": "Родитель может замечать, что ребёнок постоянно в движении, ищет шум и прикосновения.", "en": "The parent may notice that the child is constantly moving and seeks noise and touch."}, "support": {"az": "Təhlükəsiz hərəkət fasilələri, qum, su, plastilin və top oyunları təşkil edin.", "ru": "Организуйте безопасные перерывы на движение, игры с песком, водой, пластилином и мячом.", "en": "Set up safe movement breaks and games with sand, water, modeling clay and a ball."}}, {"id": "d11", "title": {"az": "Qaçınma kvadrantı", "ru": "Квадрант «избегание»", "en": "Avoiding Quadrant"}, "task": {"az": "Valideynə sual: güclü səs, izdiham və gözlənilməz hadisələrdən uzaq durur? Tanış mühiti üstün tutur?", "ru": "Вопрос родителю: избегает ли ребёнок громких звуков, толпы, неожиданных событий? Предпочитает ли знакомую обстановку?", "en": "Question to the parent: does the child avoid loud sounds, crowds, and unexpected events? Does the child prefer a familiar environment?"}, "items": [{"id": "d11i1", "t": {"az": "Güclü təsirlərdən uzaqlaşır", "ru": "Отстраняется от сильных воздействий", "en": "Withdraws from strong sensory input"}}, {"id": "d11i2", "t": {"az": "İzdihamlı yerlərdən qaçır", "ru": "Избегает людных мест", "en": "Avoids crowded places"}}, {"id": "d11i3", "t": {"az": "Tanış və proqnozlaşdırıla bilən mühit tələb edir", "ru": "Требует знакомой и предсказуемой обстановки", "en": "Needs a familiar and predictable environment"}}], "mean": {"az": "sensor təsirdən uzaq durmaq", "ru": "избегание сенсорных воздействий", "en": "avoiding sensory input"}, "means": {"az": "Sensor təsirdən uzaq durmaq uşağın güclü səs, izdiham və gözlənilməz hadisələrdən çəkinməsidir.", "ru": "Избегание сенсорных воздействий — это стремление ребёнка уходить от сильных звуков, толпы и неожиданных событий.", "en": "Avoiding sensory input is the child's tendency to withdraw from loud sounds, crowds and unexpected events."}, "looks": {"az": "Valideyn uşağın tanış mühiti üstün tutduğunu və yeni vəziyyətdən çəkindiyini görə bilər.", "ru": "Родитель может замечать, что ребёнок предпочитает знакомую обстановку и сторонится новых ситуаций.", "en": "The parent may notice that the child prefers familiar settings and avoids new situations."}, "support": {"az": "Yeni vəziyyətlərə tədricən, əvvəlcədən xəbərdar edərək yaxınlaşdırın, uğurlu cəhdləri təriflə.", "ru": "Подводите к новым ситуациям постепенно, заранее предупреждая; хвалите удачные попытки.", "en": "Introduce new situations gradually with advance warning, and praise successful attempts."}}, {"id": "d12", "title": {"az": "Həssaslıq kvadrantı", "ru": "Квадрант «чувствительность»", "en": "Sensitivity Quadrant"}, "task": {"az": "Valideynə sual: kiçik səs və ya dəyişikliyi başqalarından tez hiss edir? Tez yüklənir?", "ru": "Вопрос родителю: замечает ли ребёнок небольшой звук или изменение раньше других? Быстро ли перегружается?", "en": "Question to the parent: does the child notice a small sound or change sooner than others? Does the child become overloaded quickly?"}, "items": [{"id": "d12i1", "t": {"az": "Təsirlərə həddindən artıq reaksiya verir", "ru": "Чрезмерно реагирует на воздействия", "en": "Overreacts to sensory input"}}, {"id": "d12i2", "t": {"az": "Kiçik dəyişiklikləri tez hiss edir", "ru": "Быстро замечает небольшие изменения", "en": "Quickly notices small changes"}}, {"id": "d12i3", "t": {"az": "Tez yüklənir və sakitləşməkdə çətinlik çəkir", "ru": "Быстро перегружается и с трудом успокаивается", "en": "Becomes overloaded quickly and has difficulty calming down"}}], "mean": {"az": "sensor təsirləri tez hiss etmək", "ru": "быстрая чувствительность к сенсорным воздействиям", "en": "noticing sensory input quickly"}, "means": {"az": "Sensor təsirləri tez hiss etmək uşağın kiçik səs və dəyişikliyi başqalarından tez fərq etməsini göstərir.", "ru": "Быстрая чувствительность к сенсорным воздействиям означает, что ребёнок замечает малые звуки и изменения раньше других.", "en": "Noticing sensory input quickly means the child notices small sounds and changes sooner than others."}, "looks": {"az": "Valideyn uşağın kiçik səsə və ya dəyişikliyə tez reaksiya verdiyini, tez yorulduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнок быстро реагирует на малейший звук или изменение и быстро устаёт.", "en": "The parent may notice that the child reacts quickly to a small sound or change and tires quickly."}, "support": {"az": "Sakit mühit yaradın, gün ərzində fasilələr planlaşdırın, yük artanda sakit künc təklif edin.", "ru": "Создайте спокойную обстановку, планируйте перерывы в течение дня, при перегрузке предлагайте тихий уголок.", "en": "Create a calm environment, plan breaks through the day and offer a quiet corner when overloaded."}}, {"id": "d13", "title": {"az": "Qeydiyyat kvadrantı", "ru": "Квадрант «регистрация»", "en": "Registration Quadrant"}, "task": {"az": "Valideynə sual: uşaq səs, toxunuş və ya ağrını gec hiss edir? Bəzən «öz dünyasında» olur?", "ru": "Вопрос родителю: поздно ли ребёнок замечает звук, прикосновение или боль? Бывает ли, что он «в своём мире»?", "en": "Question to the parent: is the child slow to notice sound, touch, or pain? Does the child sometimes seem to be \"in his or her own world\"?"}, "items": [{"id": "d13i1", "t": {"az": "Təsirləri gec fərq edir", "ru": "Поздно замечает воздействия", "en": "Is slow to notice sensory input"}}, {"id": "d13i2", "t": {"az": "Ağrını və ya temperaturu az hiss edir", "ru": "Слабо ощущает боль или температуру", "en": "Has a poor sense of pain or temperature"}}, {"id": "d13i3", "t": {"az": "Enerjisi aşağıdır və ya «öz dünyasında» görünür", "ru": "Низкий уровень энергии или выглядит «в своём мире»", "en": "Has low energy or appears to be \"in his or her own world\""}}], "mean": {"az": "sensor təsirləri gec fərq etmək", "ru": "поздняя регистрация сенсорных воздействий", "en": "noticing sensory input slowly"}, "means": {"az": "Sensor təsirləri gec fərq etmək uşağın səs, toxunuş və ya ağrını gec hiss etməsini göstərir.", "ru": "Поздняя регистрация сенсорных воздействий означает, что ребёнок с опозданием замечает звук, прикосновение или боль.", "en": "Noticing sensory input slowly means the child registers sound, touch or pain late."}, "looks": {"az": "Valideyn uşağın adı çağırılanda gec cavab verdiyini və ya bəzən «öz dünyasında» olduğunu görə bilər.", "ru": "Родитель может замечать, что ребёнок поздно отзывается на имя или порой бывает «в своём мире».", "en": "The parent may notice that the child responds late when called by name or is sometimes \"in his or her own world\"."}, "support": {"az": "Diqqəti cəlb etmək üçün jest, toxunuş və aydın səs istifadə edin, canlı və maraqlı oyuncaqlar təklif edin.", "ru": "Привлекайте внимание жестом, прикосновением и чётким голосом, предлагайте яркие и интересные игрушки.", "en": "Use gestures, touch and a clear voice to gain attention, and offer lively, interesting toys."}}], "specialist": [{"az": "Hər kvadrantı uşağın konkret gündəlik davranışı ilə bağlayın.", "ru": "Свяжите каждый квадрант с конкретным повседневным поведением.", "en": "Link each quadrant to the child's concrete daily behavior."}, {"az": "Ev və sinif üçün 'sensor pəhriz' tövsiyələri hazırlayın.", "ru": "Подготовьте рекомендации «сенсорной диеты» для дома и класса.", "en": "Prepare 'sensory diet' recommendations for home and classroom."}, {"az": "Erqoterapevtlə birgə müdaxilə planı qurun.", "ru": "Постройте план вмешательства совместно с эрготерапевтом.", "en": "Build the intervention plan together with an occupational therapist."}], "parentIntro": {"az": "Uşağınızın 'çətin' görünən davranışları çox vaxt sensor ehtiyacdır. Mühiti uyğunlaşdırmaq çox kömək edir.", "ru": "«Трудное» поведение ребёнка часто — сенсорная потребность. Адаптация среды очень помогает.", "en": "Your child's 'difficult' behaviors are often a sensory need. Adapting the environment helps a lot."}, "parentTips": [{"az": "Həssaslıq varsa: səs-küyü azaldın, sakit künc yaradın.", "ru": "При чувствительности: снижайте шум, создайте тихий уголок.", "en": "If sensitive: reduce noise, create a quiet corner."}, {"az": "Axtarış varsa: təhlükəsiz hərəkət və sıxılma imkanı verin.", "ru": "При поиске: дайте безопасное движение и сжатие.", "en": "If seeking: provide safe movement and deep-pressure input."}, {"az": "Keçidləri əvvəlcədən xəbər verin ki, sürpriz olmasın.", "ru": "Предупреждайте о переходах заранее, чтобы не было сюрприза.", "en": "Announce transitions in advance so they aren't a surprise."}], "games": [{"az": "Sensor qutu: düyü, lobya, qum içində əşya axtarmaq.", "ru": "Сенсорная коробка: поиск предметов в рисе, фасоли, песке.", "en": "Sensory bin: find objects in rice, beans or sand."}, {"az": "Yastıq 'sendviçi': yumşaq təzyiq sakitləşdirir.", "ru": "«Бутерброд» из подушек: мягкое давление успокаивает.", "en": "Pillow 'sandwich': gentle pressure soothes."}, {"az": "Maneə yolu: tarazlıq və bədən fərqindəliyi üçün.", "ru": "Полоса препятствий: для баланса и осознания тела.", "en": "Obstacle course: for balance and body awareness."}]}}, "school": [{"az": "Yazı və köçürmə tapşırıqlarına əlavə vaxt vermək.", "ru": "Давать дополнительное время на письмо и переписывание.", "en": "Allow extra time for writing and copying tasks."}, {"az": "Vizual izahı şifahi izahla müşayiət etmək.", "ru": "Сопровождать наглядное объяснение словесным.", "en": "Pair visual explanations with spoken ones."}, {"az": "Tapşırıqları kiçik mərhələlərə bölmək.", "ru": "Делить задания на небольшие этапы.", "en": "Break tasks into small steps."}], "nextsteps": [{"az": "Prioritet sahələr üzrə 8–12 həftəlik məşq planı qurmaq.", "ru": "Составить план занятий на 8–12 недель по приоритетным областям.", "en": "Set up an 8–12 week practice plan for the priority areas."}, {"az": "3–6 aydan sonra təkrar müşahidə aparmaq.", "ru": "Повторить наблюдение через 3–6 месяцев.", "en": "Repeat the observation after 3–6 months."}, {"az": "Nəticələri valideynlə görüşdə müzakirə etmək.", "ru": "Обсудить результаты с родителями на встрече.", "en": "Discuss the results with parents at a meeting."}], "groups": {"VCI": {"az": "Şifahi anlama (VCI)", "ru": "Вербальное понимание (VCI)", "en": "Verbal comprehension (VCI)"}, "VSI": {"az": "Vizual-məkan (VSI)", "ru": "Зрительно-пространственный (VSI)", "en": "Visual-spatial (VSI)"}, "FRI": {"az": "Axıcı mühakimə (FRI)", "ru": "Текучее мышление (FRI)", "en": "Fluid reasoning (FRI)"}, "WMI": {"az": "İşlək yaddaş (WMI)", "ru": "Рабочая память (WMI)", "en": "Working memory (WMI)"}, "PSI": {"az": "Emal sürəti (PSI)", "ru": "Скорость обработки (PSI)", "en": "Processing speed (PSI)"}}};